    const { side, symbol, price, stopLoss, takeProfit } = req.body;

    // Create a manual signal
    const signal = {
      symbol,
      side,
      confidence: 100,
      entryPrice: price,
      stopLoss,
      takeProfit,
      reasoning: 'Manual entry',
      indicators: ['Manual']
    };

    try {
      // Execute trade
      await engine.shadowTrader.processSignal(
        signal,
        price,
        engine.activeMode,
        engine.balanceManager,
