  }

  async init() {
    // Wait for database initialization
    let retry = 0;
    while (retry < 5) {
      try {
        await runQuery('SELECT 1');
        break;
      } catch (e) {
        retry++;
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
    await this.loadSettings();
  }

  backupDatabase() {
    try {
      const dbPath = path.join(process.cwd(), 'trading.db');
      const backupPath = path.join(process.cwd(), `trading_backup_${Date.now()}.db`);
      if (fs.existsSync(dbPath)) {
        fs.copyFileSync(dbPath, backupPath);
        console.log(`Database backed up to ${backupPath}`);

        // Clean up old backups (keep last 5)
        const files = fs.readdirSync(process.cwd());
        const backups = files.filter(f => f.startsWith('trading_backup_')).sort();
        if (backups.length > 5) {
          const toDelete = backups.slice(0, backups.length - 5);
          toDelete.forEach(f => fs.unlinkSync(path.join(process.cwd(), f)));
        }
      }
    } catch (e) {
      console.error('Failed to backup database:', e);
    }
  }

  async loadSettings() {
    try {
      const settings = await runQuery(`SELECT * FROM settings`, [], 'all');
      const config: any = {};
      for (const row of settings as any[]) {
        config[row.key] = row.value;
      }

      if (config.symbol) {
        this.symbol = config.symbol;
        if (this.exchange) {
          this.exchange.setActiveSymbol(this.symbol);
        }
      }
      if (config.timeframe) this.timeframe = config.timeframe;
      if (config.activeMode) this.activeMode = config.activeMode;
      if (config.strategy) this.strategy = config.strategy;

      const exchangeName = String(
        config.exchange || process.env.EXCHANGE_NAME || 'coinmarketcap'
      ).toLowerCase();
      const exchangeApiKey = String(
        config.apiKey || process.env.EXCHANGE_API_KEY || ''
      );
      const exchangeApiSecret = String(
        config.apiSecret || process.env.EXCHANGE_API_SECRET || ''
      );
      const exchangeApiPassword = String(
        config.apiPassword || process.env.EXCHANGE_API_PASSWORD || ''
      );
      const useTestnet = String(
        config.exchangeUseTestnet || process.env.EXCHANGE_USE_TESTNET || 'true'
      ).toLowerCase() === 'true';

      this.aiStrategySwitching = config.aiStrategySwitching === 'true';
      this.aiSignalGeneration = config.aiSignalGeneration === 'true';
      this.aiSentimentAnalysis = config.aiSentimentAnalysis === 'true';

      this.startupDiagnostics = {
        exchangeEnabled: this.isExchangeEnabled,
        exchangeName,
        exchangeConfigured: false,
        exchangeReason: 'pending_validation'
      };

      if (this.isExchangeEnabled) {
        const requiresApiKey = exchangeName === 'coinmarketcap';
        if (requiresApiKey && !exchangeApiKey) {
          const message = `Exchange "${exchangeName}" requires EXCHANGE_API_KEY or persisted settings.apiKey`;
          if (process.env.NODE_ENV === 'production') {
            throw new Error(message);
          }
          console.warn(`[TradingEngine] ${message}. Exchange disabled until configured.`);
          this.exchange = null;
          this.startupDiagnostics.exchangeConfigured = false;
          this.startupDiagnostics.exchangeReason = message;
        } else {
          this.exchange = new ExchangeConnector(
            exchangeName,
            exchangeApiKey,
            exchangeApiSecret,
            exchangeApiPassword || undefined,
            useTestnet
          );
          this.exchange.setActiveSymbol(this.symbol);
          this.startupDiagnostics.exchangeConfigured = true;
          this.startupDiagnostics.exchangeReason = 'ok';
        }
      } else {
        this.exchange = null;
        this.startupDiagnostics.exchangeConfigured = false;
        this.startupDiagnostics.exchangeReason = 'exchange_disabled';
      }

      this.broadcast({ type: 'status', data: { symbol: this.symbol, timeframe: this.timeframe } });

      if (this.isRunning) {
        this.runCycle().catch(console.error);
      }
    } catch (e) {
      console.error('Failed to load settings:', e);
      this.exchange = null;
      this.startupDiagnostics.exchangeConfigured = false;
      this.startupDiagnostics.exchangeReason = e instanceof Error ? e.message : 'load_settings_failed';
    }
  }

  async start() {
    // Initialize job queues (only if Redis is available)
    this.startSchedulers();
    this.isRunning = true;
    this.shadowTrader.reset();
    logger.info('Trading engine started and reset', { service: 'TradingEngine' });
    this.broadcast({ type: 'status', data: { isRunning: true } });

    // Broadcast initial performance (async, don't wait)
    this.shadowTrader.getPerformance().then(perf => {
      this.broadcast({ type: 'performance', data: perf });
    }).catch(err => {
      logger.warn('Failed to get initial performance', { error: err.message });
      this.broadcast({ type: 'performance', data: {} });
    });

    while (this.isRunning) {
      const cycleStart = Date.now();
      try {
        await this.runCycle();
      } catch (error: any) {
        logger.error('Error in trading cycle:', { error: error.message });
        this.broadcast({ type: 'error', data: { message: error.message } });
        // Add delay on error to prevent tight error loops
        await this.sleepWithTimeout(5000, 10000);
        continue;
      }

      // Wait for next cycle with abortable sleep (max 30s timeout)
      const cycleDuration = Date.now() - cycleStart;
      const sleepTime = Math.max(0, 1000 - cycleDuration);
      if (this.isRunning && sleepTime > 0) {
        await this.sleepWithTimeout(sleepTime, 30000);
      }
    }

    // Ensure clean exit
    this.isRunning = false;
    logger.info('Trading engine loop exited naturally', { service: 'TradingEngine' });
  }

  private sleepAbortable(ms: number) {
    return new Promise(resolve => {
      const timeout = setTimeout(resolve, ms);
      // Cleanup on abort could be added here if needed
    });
  }

  private sleepWithTimeout(ms: number, timeoutMs: number = 30000): Promise<void> {
    return new Promise((resolve) => {
      const timeout = setTimeout(() => {
        // Don't reject - just resolve to continue the loop
        resolve();
      }, timeoutMs);
      const timer = setTimeout(() => {
        clearTimeout(timeout);
        resolve();
      }, ms);
    });
  }

  stop() {
    this.isRunning = false;
    this.stopSchedulers();
    logger.info('Trading engine stopped', { service: 'TradingEngine' });
    this.broadcast({ type: 'status', data: { isRunning: false } });
  }

  async killBot() {
    this.stop();

    // Fetch current price to close trades accurately
    let currentPrice = 0;
    try {
      const candles = await this.exchange.getCandles(this.symbol, this.timeframe, 1);
      if (candles && candles.length > 0) {
        currentPrice = candles[0].close;
      }
    } catch (e) {
      console.error('Failed to fetch current price for killBot, using entry prices');
    }

    // Close all shadow positions
    for (const mode of Object.keys(this.shadowTrader.portfolios)) {
      const portfolio = this.shadowTrader.portfolios[mode as any];

      for (const trade of portfolio.openTrades) {
        const exitPrice = currentPrice || trade.price;
        const leverage = trade.leverage || 1;
        const marginUsed = trade.amount * trade.price / leverage;
        const currentNotional = trade.amount * exitPrice;
        const currentMargin = currentNotional / leverage;
        let pnl = 0;
        if (trade.side === 'buy') {
          pnl = currentMargin - marginUsed;
        } else {
          pnl = marginUsed - currentMargin;
        }

        portfolio.balance += pnl;

        if (mode === this.activeMode) {
          const tradeCost = trade.amount * trade.price / trade.leverage;
          this.balanceManager.recordTradeResult(pnl, tradeCost);

          if (this.exchange && this.exchange.apiKey) {
            try {
              const closeSide = trade.side === 'buy' ? 'sell' : 'buy';
              await this.exchange.placeOrder(trade.symbol, closeSide, trade.amount, 'market');
            } catch (e: any) {
              console.error(`Failed to execute live close order for ${trade.symbol}: ${e.message}`);
            }
          }
        }

        await runQuery(`
          UPDATE shadow_trades
          SET status = 'closed', pnl = ?, exit_price = ?, exit_timestamp = ?
          WHERE id = ?
        `, [pnl, exitPrice, Date.now(), trade.id]);
      }
      portfolio.openTrades = [];
    }

    // Return all bot funds to main balance
    const balances = await this.balanceManager.getBalances();
    if (balances.botBalance > 0) {
      const amount = balances.botBalance;
      await this.balanceManager.withdrawFromBot(amount);
      const portfolio = this.shadowTrader.portfolios[this.activeMode as any];
      if (portfolio) {
        portfolio.initialBalance -= amount;
        portfolio.balance -= amount;
      }
    }

    this.broadcast({ type: 'performance', data: this.shadowTrader.getPerformance() });
    this.broadcast({ type: 'balances', data: this.balanceManager.getBalances() });
    console.log('Bot Killed: All positions closed and funds returned to main balance');
  }

  setTimeframe(timeframe: string) {
    this.timeframe = timeframe;
    console.log(`Timeframe changed to ${timeframe}`);
    this.broadcast({ type: 'status', data: { timeframe } });
    if (this.isRunning) {
      this.runCycle().catch(console.error);
    }
  }

  async runCycle() {
    // 1. Fetch new candles
    let candles = [];
    try {
      candles = this.exchange ? await this.exchange.getCandles(this.symbol, this.timeframe, 200) : [];
    } catch (e) {
      console.warn(`Exchange API failed to fetch candles: ${e}`);
    }
    if (candles.length < 100) return;

    // 2. Calculate indicators
    const df = this.indicators.calculateAll(candles);
    if (df.length === 0) return;

    // 3. Detect regime
    let regimeResult;
    if (this.manualRegime) {
      regimeResult = {
        regime: this.manualRegime,
        confidence: 100,
        reasoning: "Manually set by user",
        metrics: {},
        timestamp: Date.now()
      };
    } else {
      // Fetch recent shadow performance for AI context (MD 1.3)
      const shadowPerformance = await this.shadowTrader.getPerformance();

      // Fetch latest market data and news for AI context
      const marketData = await this.marketDataService.getLatestMarketData();
      const marketNews = await this.marketDataService.getLatestNews(10);

      const marketContext = {
        btc_dominance: marketData?.btc_dominance ? `${marketData.btc_dominance.toFixed(1)}%` : "N/A",
        fear_greed_index: marketData?.fear_greed_index || "N/A",
        major_news: marketNews.length > 0 ? marketNews[0].title : "No recent major news",
        all_news: marketNews.map(n => n.title)
      };

      regimeResult = await this.regimeDetector.detect(df, this.aiSentimentAnalysis, shadowPerformance, marketContext);
    }

    if (this.manualRegime || this.regimeDetector.shouldUpdateRegime(this.currentRegime, regimeResult.regime, regimeResult.confidence)) {
      this.currentRegime = regimeResult.regime;

      // Save regime history
      await runQuery(`
        INSERT INTO regime_history (timestamp, regime, confidence, reasoning)
        VALUES (?, ?, ?, ?)
      `, [Date.now(), this.currentRegime, regimeResult.confidence, regimeResult.reasoning]);

      // Audit log: regime change
      try {
        const auditId = randomUUID();
        const timestamp = Date.now();
        await runQuery(`
          INSERT INTO audit_system_events (id, event_type, message, timestamp, severity, metadata)
          VALUES (?, ?, ?, ?, ?, ?)
        `, [auditId, 'regime_change', `Regime changed to ${this.currentRegime}`, timestamp, 'info', JSON.stringify({ confidence: regimeResult.confidence, reasoning: regimeResult.reasoning })]);
      } catch (error) {
        console.error('Failed to log regime change audit:', error);
      }

      this.broadcast({ type: 'regime', data: regimeResult });

      if (this.aiStrategySwitching && TradingEngine.aiStrategySwitchingEnabled) {
        try {
          const apiKey = process.env.GEMINI_API_KEY;
          if (!apiKey) {
            console.warn("AI Strategy Switch skipped: GEMINI_API_KEY is not set.");
          } else {
            const { GoogleGenAI } = await import('@google/genai');
            const ai = new GoogleGenAI({ apiKey });
            const prompt = `You are an expert quantitative trader. The market regime has just changed to "${this.currentRegime}" with ${regimeResult.confidence}% confidence. 
            Reasoning: ${regimeResult.reasoning}

            Based on this new regime, which risk mode should the trading bot switch to?
            Available modes: "ultra_conservative", "conservative", "moderate", "aggressive", "degen".

            Return ONLY the mode name as a plain string.`;

            const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
            });

            if (response.text) {
              const newMode = response.text.trim().toLowerCase().replace(/[^a-z_]/g, '');
              const validModes = ["ultra_conservative", "conservative", "moderate", "aggressive", "degen"];
              if (validModes.includes(newMode)) {
                this.activeMode = newMode;
                await runQuery(`INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)`, ['activeMode', newMode]);
                this.broadcast({ type: 'ai_mode_switch', data: { mode: newMode } });
                console.log(`AI switched strategy to ${newMode}`);
              }
            }
          }
        } catch (error: any) {
          if (error.message && error.message.includes("API_KEY_INVALID")) {
            console.error("AI Strategy Switch failed: Invalid API Key. Disabling AI features.");
            TradingEngine.aiStrategySwitchingEnabled = false;
          } else {
            console.error("AI Strategy Switch failed:", error);
          }
          // Fallback
          let newMode = 'moderate';
          if (this.currentRegime === 'strong_bull' || this.currentRegime === 'bear') {
            newMode = 'aggressive';
          } else if (this.currentRegime === 'sideways') {
            newMode = 'conservative';
          }
          this.activeMode = newMode;
          await runQuery(`INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)`, ['activeMode', newMode]);
          this.broadcast({ type: 'ai_mode_switch', data: { mode: newMode } });
        }
      }
    }

    // 4. Generate signal
    const signal = await this.signalGenerator.generateSignal(df, this.currentRegime, this.symbol, this.aiSignalGeneration, this.strategy, this.activeMode);

    if (signal) {
      this.broadcast({ type: 'signal', data: signal });

      // 5. Execute shadow trades
      const currentPrice = df[df.length - 1].close;
      await this.shadowTrader.processSignal(
        signal,
        currentPrice,
        this.activeMode,
        this.balanceManager,
        this.exchange,
        this.currentRegime
      );
    }

    // 6. Update positions
    const currentPrice = df[df.length - 1].close;
    await this.shadowTrader.updatePositions(currentPrice, this.activeMode, this.balanceManager, this.exchange, df[df.length - 1]);

    // 7. Broadcast updates
    const performance = this.shadowTrader.getPerformance();

    this.broadcast({ type: 'performance', data: performance });

    const balances = this.balanceManager.getBalances();
    this.broadcast({ type: 'balances', data: balances });

    // Broadcast latest candle for chart
    this.broadcast({ type: 'candle', data: df[df.length - 1] });
  }

  broadcast(message: any) {
    this.wss.clients.forEach(client => {
      if (client.readyState === 1) { // WebSocket.OPEN
        client.send(JSON.stringify(message));
      }
    });
  }

  async runBacktest(mode: string, customConfig?: any, startTime?: number, endTime?: number) {
    // Fetch candles for the period
    // If startTime/endTime are not provided, default to last 500 candles
    let candles: any[] = [];

    if (startTime && endTime) {
      console.log(`Running backtest from ${new Date(startTime).toISOString()} to ${new Date(endTime).toISOString()}`);
      // Use getHistoricalCandles to fetch and cache data
      // Calculate how many candles we need based on timeframe
      let limit = 20000;
      if (this.timeframe === '15m') limit = Math.ceil((endTime - startTime) / (15 * 60 * 1000));
      else if (this.timeframe === '1h') limit = Math.ceil((endTime - startTime) / (60 * 60 * 1000));
      else if (this.timeframe === '1d') limit = Math.ceil((endTime - startTime) / (24 * 60 * 60 * 1000));

      // Cap at 100,000 candles to prevent memory issues
      limit = Math.min(limit, 100000);

      if (this.exchange) {
        candles = await this.exchange.getHistoricalCandles(this.symbol, this.timeframe, startTime, limit, endTime);
        console.log(`[Backtest] Fetched ${candles.length} candles from exchange`);
      } else {
        candles = [];
        console.log(`[Backtest] No exchange connector found`);
      }

      // Filter by endTime just in case
      candles = candles.filter(c => c.time <= endTime);
    } else {
      try {
        if (this.exchange) {
          candles = await this.exchange.getCandles(this.symbol, this.timeframe, 500);
        } else {
          candles = [];
        }
      } catch (e) {
        console.warn(`Exchange API failed to fetch candles for backtest: ${e}`);
        candles = [];
      }
    }

    if (candles.length < 100) return { trades: [], candles: [] };

    // Ensure candles are sorted and unique by time
    const uniqueCandlesMap = new Map();
    candles.forEach(c => uniqueCandlesMap.set(c.time, c));
    const sortedCandles = Array.from(uniqueCandlesMap.values()).sort((a: any, b: any) => a.time - b.time);

    const df = this.indicators.calculateAll(sortedCandles);
    const virtualTrades = [];
    const regimeChanges = [];
    let lastRegime = null;
    const config = customConfig || this.shadowTrader.riskManager.getConfig(mode as any);

    // Start from index 50 to have enough data for indicators
    for (let i = 50; i < df.length; i++) {
      const slice = df.slice(0, i + 1);
      const regimeResult = await this.regimeDetector.detect(slice, this.aiSentimentAnalysis);

      if (lastRegime === null) {
        lastRegime = regimeResult.regime;
        regimeChanges.push({
          time: df[i].time,
          regime: lastRegime
        });
      } else if (this.regimeDetector.shouldUpdateRegime(lastRegime, regimeResult.regime, regimeResult.confidence)) {
        regimeChanges.push({
          time: df[i].time,
          regime: regimeResult.regime
        });
        lastRegime = regimeResult.regime;
      }

      const signal = await this.signalGenerator.generateSignal(slice, lastRegime, this.symbol, this.aiSignalGeneration, this.strategy, this.activeMode);

      if (signal) {
        console.log(`[Backtest] Signal generated at ${new Date(df[i].time).toISOString()}: ${signal.side} ${signal.symbol} confidence=${signal.confidence}`);
      }

      if (signal && signal.confidence >= (config.confidenceThreshold || 0)) {
        // Apply multipliers
        const riskPerUnit = Math.abs(signal.entryPrice - signal.stopLoss);
        const adjustedStopLoss = signal.side === 'buy' 
          ? signal.entryPrice - (riskPerUnit * (config.slMultiplier || 1))
          : signal.entryPrice + (riskPerUnit * (config.slMultiplier || 1));
        const adjustedTakeProfit = signal.side === 'buy'
          ? signal.entryPrice + (riskPerUnit * (config.tpMultiplier || 1))
          : signal.entryPrice - (riskPerUnit * (config.tpMultiplier || 1));

        // Simulate forward to see if it hits TP or SL
        let exitPrice = null;
        let exitTime = null;
        let pnl = 0;
        let status = 'expired';

        for (let j = i + 1; j < df.length; j++) {
          const candle = df[j];
          if (signal.side === 'buy') {
            if (candle.low <= adjustedStopLoss) {
              exitPrice = adjustedStopLoss;
              exitTime = candle.time;
              pnl = (exitPrice - signal.entryPrice) / signal.entryPrice * 100 * (config.leverage || 1);
              status = 'loss';
              break;
            }
            if (candle.high >= adjustedTakeProfit) {
              exitPrice = adjustedTakeProfit;
              exitTime = candle.time;
              pnl = (exitPrice - signal.entryPrice) / signal.entryPrice * 100 * (config.leverage || 1);
              status = 'profit';
              break;
            }
          } else {
            if (candle.high >= adjustedStopLoss) {
              exitPrice = adjustedStopLoss;
              exitTime = candle.time;
              pnl = (signal.entryPrice - exitPrice) / signal.entryPrice * 100 * (config.leverage || 1);
              status = 'loss';
              break;
            }
            if (candle.low <= adjustedTakeProfit) {
              exitPrice = adjustedTakeProfit;
              exitTime = candle.time;
              pnl = (signal.entryPrice - exitPrice) / signal.entryPrice * 100 * (config.leverage || 1);
              status = 'profit';
              break;
            }
          }
        }

        virtualTrades.push({
          ...signal,
          stopLoss: adjustedStopLoss,
          takeProfit: adjustedTakeProfit,
          exitPrice,
          exitTime,
          pnl,
          status,
          time: df[i].time
        });

        // Skip ahead to exit time to avoid overlapping trades in simulation
        if (exitTime) {
          const exitIndex = df.findIndex(c => c.time === exitTime);
          if (exitIndex > i) i = exitIndex;
        }
      }
    }
    return { trades: virtualTrades, candles: df, regimeChanges };
  }

  getStartupDiagnostics() {
    return {
      ...this.startupDiagnostics,
      hasExchangeInstance: Boolean(this.exchange),
      exchangeCapabilities: this.exchange?.getCapabilities() || null,
      isRunning: this.isRunning,
      symbol: this.symbol,
      timeframe: this.timeframe
    };
  }
}

let engine: TradingEngine | null = null;

export async function startTradingEngine(wss: WebSocketServer, redis?: Redis) {
  if (!engine) {
    engine = new TradingEngine(wss, redis);
    await engine.init();
    // Start engine asynchronously
    engine.start().catch(console.error);
  }
  return engine;
}

export function getTradingEngine() {
  return engine;
}

export function getStartupDiagnostics() {
  return engine?.getStartupDiagnostics() || null;
}

import { runQuery } from '../database.js';
import axios from 'axios';
import crypto from 'crypto';
import { logger } from '../logging/logger.js';
import { randomUUID } from 'crypto';
import { ExchangeAdapterFactory, BaseExchangeAdapter } from './adapter.js';
import { PositionReconciliationEngine } from './reconciliation.js';

type ExchangeName = 'coinmarketcap' | 'binance' | 'kraken' | 'okx' | 'coinbase';
type Capabilities = {
  provider: ExchangeName;
  supportsLiveTrading: boolean;
  supportsAccountReads: boolean;
  supportsPublicMarketData: boolean;
};
type OrderResponse = {
  id: string;
  status: string;
  filled: number;
  price: number;
  timestamp: number;
  simulated: boolean;
  exchange: ExchangeName;
};
type BalanceResponse = Record<string, number | boolean>;
type ExecutionAdapter = {
  capabilities: Capabilities;
  placeOrder: (symbol: string, side: 'buy' | 'sell', amount: number, orderType: 'market' | 'limit', price?: number) => Promise<OrderResponse>;
  getBalance: () => Promise<BalanceResponse>;
  cancelOrder: (orderId: string, symbol: string) => Promise<boolean>;
};

export class ExchangeConnector {
  apiKey: string;
  exchangeName: ExchangeName;
  testnet: boolean;
  private apiSecret: string;
  private apiPassword?: string;
  private currentPrice = 0;
  private lastUpdate = 0;
  private updateInterval: NodeJS.Timeout | null = null;
  private executionAdapter: ExecutionAdapter;
  private exchangeAdapter: BaseExchangeAdapter;
  private reconciliationEngine: PositionReconciliationEngine;
  private symbolMap: Record<string, string> = {
    'BTC/USDT': 'BTC',
    'ETH/USDT': 'ETH',
    'SOL/USDT': 'SOL'
  };

  private activeSymbol = 'BTC/USDT';

  constructor(exchangeName: string, apiKey: string, apiSecret: string, apiPassword?: string, testnet: boolean = true) {
    this.exchangeName = this.normalizeExchangeName(exchangeName);
    this.apiKey = apiKey;
    this.apiSecret = apiSecret;
    this.apiPassword = apiPassword;
    this.testnet = testnet;

    // Validate credentials for non-demo exchanges in production mode
    // In testnet mode, allow empty credentials for testing purposes
    if (this.exchangeName !== 'coinmarketcap' && !this.testnet) {
      if (!this.apiKey || !this.apiSecret) {
        const message = `Exchange "${this.exchangeName}" requires EXCHANGE_API_KEY and EXCHANGE_API_SECRET`;
        if (this.exchangeName === 'okx' || this.exchangeName === 'coinbase') {
          throw new Error(`${message} and EXCHANGE_API_PASSWORD`);
        }
        throw new Error(message);
      }
    }

    logger.info('ExchangeConnector initialized', {
      service: 'ExchangeConnector',
      exchangeName: this.exchangeName,
      testnet: this.testnet
    });

    // Initialize new adapter system
    this.exchangeAdapter = ExchangeAdapterFactory.createAdapter(
      this.exchangeName as any,
      this.apiKey,
      this.apiSecret,
      this.apiPassword,
      this.testnet
    );

    this.reconciliationEngine = new PositionReconciliationEngine();
    this.reconciliationEngine.registerAdapter(this.exchangeName, this.exchangeAdapter);

    this.executionAdapter = this.createExecutionAdapter();
    this.startLiveUpdates();
    this.startReconciliation();
  }

  private normalizeExchangeName(name: string): ExchangeName {
    const normalized = String(name || 'coinmarketcap').toLowerCase();
    const supportedExchanges: ExchangeName[] = ['coinmarketcap', 'binance', 'kraken', 'okx', 'coinbase'];

    if (supportedExchanges.includes(normalized as ExchangeName)) {
      return normalized as ExchangeName;
    }

    logger.warn('Unsupported exchange name, defaulting to coinmarketcap', {
      service: 'ExchangeConnector',
      suppliedExchange: normalized
    });
    return 'coinmarketcap';
  }

  setActiveSymbol(symbol: string) {
    this.activeSymbol = symbol;
  }

  private startLiveUpdates() {
    if (this.updateInterval) clearInterval(this.updateInterval);

    this.updateInterval = setInterval(async () => {
      try {
        await this.fetchLatestPrice(this.activeSymbol);
      } catch (error) {
        logger.error('Failed to fetch live market data', {
          service: 'ExchangeConnector',
          exchangeName: this.exchangeName,
          error: (error as Error).message
        });
      }
    }, 5000);
    this.updateInterval.unref?.();
  }

  private startReconciliation() {
    this.reconciliationEngine.startReconciliation(30000); // 30 second intervals
  }

  shutdown() {
    if (this.updateInterval) {
      clearInterval(this.updateInterval);
      this.updateInterval = null;
    }
    this.reconciliationEngine.stopReconciliation();
  }

  getCapabilities() {
    return this.executionAdapter.capabilities;
  }

  private getBinanceBaseUrl(): string {
    return this.testnet ? 'https://testnet.binance.vision' : 'https://api.binance.com';
  }

  private getOkxBaseUrl(): string {
    return this.testnet ? 'https://www.okx.com' : 'https://www.okx.com';
  }

  private getCoinbaseBaseUrl(): string {
    return this.testnet ? 'https://api-public.sandbox.exchange.coinbase.com' : 'https://api.coinbase.com';
  }

  private signOkxRequest(timestamp: string, method: string, path: string, body: string = ''): string {
    const message = timestamp + method + path + body;
    return crypto.createHmac('sha256', this.apiSecret).update(message).digest('base64');
  }

  private signCoinbaseRequest(timestamp: string, method: string, path: string, body: string = ''): string {
    const message = timestamp + method + path + body;
    return crypto.createHmac('sha256', this.apiSecret).update(message).digest('base64');
  }

  private async fetchLatestPrice(symbol: string) {
    const baseSymbol = this.symbolMap[symbol] || symbol.split('/')[0];
    try {
      if (this.exchangeName === 'binance') {
        const pair = symbol.replace('/', '');
        const ticker = await axios.get(`${this.getBinanceBaseUrl()}/api/v3/ticker/24hr`, {
          params: { symbol: pair }
        });

        const price = Number(ticker.data?.lastPrice || 0);
        if (Number.isFinite(price) && price > 0) {
          this.currentPrice = price;
          this.lastUpdate = Date.now();
          await this.saveTickToDb(symbol, this.currentPrice, Number(ticker.data?.volume || 0));
        }
        return;
      }

      if (this.exchangeName === 'kraken') {
        const pair = symbol.replace('/', '');
        const response = await axios.get('https://api.kraken.com/0/public/Ticker', {
          params: { pair }
        });

        const firstResult = Object.values(response.data?.result || {})[0] as any;
        const price = Number(firstResult?.c?.[0] || 0);
        const volume = Number(firstResult?.v?.[1] || 0);
        if (Number.isFinite(price) && price > 0) {
          this.currentPrice = price;
          this.lastUpdate = Date.now();
          await this.saveTickToDb(symbol, this.currentPrice, volume);
        }
        return;
      }

      if (this.exchangeName === 'okx') {
        const pair = symbol.replace('/', '-');
        const response = await axios.get(`${this.getOkxBaseUrl()}/api/v5/market/ticker`, {
          params: { instId: pair }
        });

        const price = Number(response.data?.data?.[0]?.last || 0);
        const volume = Number(response.data?.data?.[0]?.vol24h || 0);
        if (Number.isFinite(price) && price > 0) {
          this.currentPrice = price;
          this.lastUpdate = Date.now();
          await this.saveTickToDb(symbol, this.currentPrice, volume);
        }
        return;
      }

      if (this.exchangeName === 'coinbase') {
        const pair = symbol.replace('/', '-');
        const response = await axios.get(`${this.getCoinbaseBaseUrl()}/api/v3/brokerage/market/get_ticker`, {
          params: { product_id: pair }
        });

        const price = Number(response.data?.price || 0);
        const volume = Number(response.data?.volume || 0);
        if (Number.isFinite(price) && price > 0) {
          this.currentPrice = price;
          this.lastUpdate = Date.now();
          await this.saveTickToDb(symbol, this.currentPrice, volume);
        }
        return;
      }

      const response = await axios.get('https://pro-api.coinmarketcap.com/v1/cryptocurrency/quotes/latest', {
        headers: {
          'X-CMC_PRO_API_KEY': this.apiKey,
          Accept: 'application/json'
        },
        params: {
          symbol: baseSymbol,
          convert: 'USD'
        }
      });

      const data = response.data?.data?.[baseSymbol];
      if (data?.quote?.USD) {
        this.currentPrice = Number(data.quote.USD.price);
        this.lastUpdate = Date.now();
        await this.saveTickToDb(symbol, this.currentPrice, Number(data.quote.USD.volume_24h || 0));
      }
    } catch (error: any) {
      logger.error('Price fetch failed', {
        service: 'ExchangeConnector',
        exchangeName: this.exchangeName,
        error: error.response?.data || error.message
      });
    }
  }

  private async saveTickToDb(symbol: string, price: number, volume: number) {
    const now = Date.now();
    const candleTime = Math.floor(now / 60000) * 60000;

    try {
      await runQuery(
        `
        INSERT INTO candles (symbol, timeframe, time, open, high, low, close, volume)
        VALUES (?, '1m', ?, ?, ?, ?, ?, ?)
        ON CONFLICT(symbol, timeframe, time) DO UPDATE SET
        high = MAX(high, excluded.high),
        low = MIN(low, excluded.low),
        close = excluded.close,
        volume = excluded.volume
      `,
        [symbol, candleTime, price, price, price, price, volume]
      );
    } catch (error) {
      logger.error('Failed to save tick to DB', { service: 'ExchangeConnector', error: (error as Error).message });
    }
  }

  async fetchExchangeOHLCV(symbol: string, timeframe: string, since: number, limit: number) {
    return this.getHistoricalCandles(symbol, timeframe, since, limit);
  }

  async getHistoricalCandles(symbol: string, timeframe: string, since: number, limit: number = 1000, toTime?: number) {
    let rows;

    if (toTime) {
      rows = await runQuery(
        `
        SELECT time, open, high, low, close, volume
        FROM candles
        WHERE symbol = ? AND timeframe = ? AND time >= ? AND time <= ?
        ORDER BY time ASC
      `,
        [symbol, timeframe, since, toTime],
        'all'
      );
    } else {
      rows = await runQuery(
        `
        SELECT time, open, high, low, close, volume
        FROM candles
        WHERE symbol = ? AND timeframe = ? AND time >= ?
        ORDER BY time DESC
        LIMIT ?
      `,
        [symbol, timeframe, since, limit],
        'all'
      );
      rows = rows.reverse();
    }

    return rows;
  }

  async getCandles(symbol: string, timeframe: string, limit: number = 100) {
    let rows = await runQuery(
      `
      SELECT time, open, high, low, close, volume
      FROM candles
      WHERE symbol = ? AND timeframe = ?
      ORDER BY time DESC
      LIMIT ?
    `,
      [symbol, timeframe, limit],
      'all'
    );

    if (rows.length === 0) {
      if (this.currentPrice === 0) {
        await this.fetchLatestPrice(symbol);
      }

      const price = this.currentPrice || 50000;
      const now = Date.now();
      const msPerCandle = { '1m': 60000, '5m': 300000, '15m': 900000, '1h': 3600000, '1d': 86400000 }[timeframe] || 3600000;

      rows = Array.from({ length: limit }).map((_, i) => {
        const time = now - (limit - 1 - i) * msPerCandle;
        const noise = price * 0.001;
        return {
          time,
          open: price - noise + Math.random() * noise * 2,
          high: price + Math.random() * noise * 2,
          low: price - Math.random() * noise * 2,
          close: price - noise + Math.random() * noise * 2,
          volume: Math.random() * 100
        };
      });
    } else {
      rows = rows.reverse();
    }

    return rows;
  }

  private signBinanceQuery(query: string): string {
    return crypto.createHmac('sha256', this.apiSecret).update(query).digest('hex');
  }

  private signKrakenPayload(path: string, nonce: string, requestBody: URLSearchParams): string {
    const secret = Buffer.from(this.apiSecret, 'base64');
    const hash = crypto.createHash('sha256').update(`${nonce}${requestBody.toString()}`).digest();
    return crypto.createHmac('sha512', secret).update(path).update(hash).digest('base64');
  }

  private createExecutionAdapter(): ExecutionAdapter {
    if (this.exchangeName === 'binance') {
      return {
        capabilities: {
          provider: 'binance',
          supportsLiveTrading: true,
          supportsAccountReads: true,
          supportsPublicMarketData: true
        },
        placeOrder: async (symbol, side, amount, orderType, price) => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Binance order execution requires EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const pair = symbol.replace('/', '');
          const params = new URLSearchParams({
            symbol: pair,
            side: side.toUpperCase(),
            type: orderType.toUpperCase(),
            quantity: String(amount),
            timestamp: String(Date.now())
          });

          if (orderType === 'limit' && price) {
            params.set('price', String(price));
            params.set('timeInForce', 'GTC');
          }

          const signature = this.signBinanceQuery(params.toString());
          params.set('signature', signature);

          const response = await axios.post(`${this.getBinanceBaseUrl()}/api/v3/order`, params.toString(), {
            headers: {
              'X-MBX-APIKEY': this.apiKey,
              'Content-Type': 'application/x-www-form-urlencoded'
            }
          });

          return {
            id: String(response.data?.orderId || ''),
            status: response.data?.status || 'unknown',
            filled: Number(response.data?.executedQty || 0),
            price: Number(response.data?.price || response.data?.fills?.[0]?.price || price || this.currentPrice || 0),
            timestamp: Number(response.data?.transactTime || Date.now()),
            simulated: false,
            exchange: 'binance' as ExchangeName
          };
        },
        getBalance: async () => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Binance account reads require EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const params = new URLSearchParams({ timestamp: String(Date.now()) });
          params.set('signature', this.signBinanceQuery(params.toString()));

          const response = await axios.get(`${this.getBinanceBaseUrl()}/api/v3/account`, {
            params,
            headers: { 'X-MBX-APIKEY': this.apiKey }
          });

          const balances = response.data?.balances || [];
          const result: BalanceResponse = { simulated: false };
          for (const row of balances) {
            const free = Number(row.free || 0);
            if (free > 0) result[row.asset] = free;
          }
          return result;
        },
        cancelOrder: async (orderId, symbol) => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Binance order cancellation requires EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const params = new URLSearchParams({
            symbol: symbol.replace('/', ''),
            orderId,
            timestamp: String(Date.now())
          });
          params.set('signature', this.signBinanceQuery(params.toString()));
          await axios.delete(`${this.getBinanceBaseUrl()}/api/v3/order`, {
            params,
            headers: { 'X-MBX-APIKEY': this.apiKey }
          });
          return true;
        }
      };
    }

    if (this.exchangeName === 'kraken') {
      return {
        capabilities: {
          provider: 'kraken',
          supportsLiveTrading: true,
          supportsAccountReads: true,
          supportsPublicMarketData: true
        },
        placeOrder: async (symbol, side, amount) => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Kraken order execution requires EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const nonce = `${Date.now()}${Math.floor(Math.random() * 1000)}`;
          const endpoint = '/0/private/AddOrder';
          const params = new URLSearchParams({
            nonce,
            pair: symbol.replace('/', ''),
            type: side,
            ordertype: 'market',
            volume: String(amount)
          });
          const signature = this.signKrakenPayload(endpoint, nonce, params);
          const response = await axios.post(`https://api.kraken.com${endpoint}`, params.toString(), {
            headers: {
              'API-Key': this.apiKey,
              'API-Sign': signature,
              'Content-Type': 'application/x-www-form-urlencoded'
            }
          });
          const txid = response.data?.result?.txid?.[0];
          return {
            id: String(txid || ''),
            status: response.data?.error?.length ? 'rejected' : 'open',
            filled: amount,
            price: this.currentPrice || 0,
            timestamp: Date.now(),
            simulated: false,
            exchange: 'kraken' as ExchangeName
          };
        },
        getBalance: async () => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Kraken account reads require EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const nonce = `${Date.now()}${Math.floor(Math.random() * 1000)}`;
          const endpoint = '/0/private/Balance';
          const params = new URLSearchParams({ nonce });
          const signature = this.signKrakenPayload(endpoint, nonce, params);
          const response = await axios.post(`https://api.kraken.com${endpoint}`, params.toString(), {
            headers: {
              'API-Key': this.apiKey,
              'API-Sign': signature,
              'Content-Type': 'application/x-www-form-urlencoded'
            }
          });
          const result: BalanceResponse = { simulated: false };
          const balances = response.data?.result || {};
          for (const [asset, value] of Object.entries(balances)) {
            const amount = Number(value || 0);
            if (amount > 0) result[asset] = amount;
          }
          return result;
        },
        cancelOrder: async (orderId) => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Kraken order cancellation requires EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const nonce = `${Date.now()}${Math.floor(Math.random() * 1000)}`;
          const endpoint = '/0/private/CancelOrder';
          const params = new URLSearchParams({ nonce, txid: orderId });
          const signature = this.signKrakenPayload(endpoint, nonce, params);
          await axios.post(`https://api.kraken.com${endpoint}`, params.toString(), {
            headers: {
              'API-Key': this.apiKey,
              'API-Sign': signature,
              'Content-Type': 'application/x-www-form-urlencoded'
            }
          });
          return true;
        }
      };
    }

    if (this.exchangeName === 'okx') {
      return {
        capabilities: {
          provider: 'okx',
          supportsLiveTrading: true,
          supportsAccountReads: true,
          supportsPublicMarketData: true
        },
        placeOrder: async (symbol, side, amount, orderType, price) => {
          if (!this.apiKey || !this.apiSecret || !this.apiPassword) {
            throw new Error('OKX order execution requires EXCHANGE_API_KEY, EXCHANGE_API_SECRET, and EXCHANGE_API_PASSWORD');
          }
          const pair = symbol.replace('/', '-');
          const timestamp = Date.now().toString();
          const method = 'POST';
          const path = '/api/v5/trade/order';
          const orderBody = JSON.stringify({
            instId: pair,
            tdMode: 'cash',
            side: side === 'buy' ? 'buy' : 'sell',
            ordType: orderType === 'limit' ? 'limit' : 'market',
            sz: String(amount),
            px: price ? String(price) : ''
          });
          const signature = this.signOkxRequest(timestamp, method, path, orderBody);

          const response = await axios.post(`${this.getOkxBaseUrl()}${path}`, orderBody, {
            headers: {
              'OK-ACCESS-KEY': this.apiKey,
              'OK-ACCESS-SIGN': signature,
              'OK-ACCESS-TIMESTAMP': timestamp,
              'OK-ACCESS-PASSPHRASE': this.apiPassword,
              'Content-Type': 'application/json'
            }
          });

          const data = response.data?.data?.[0];
          return {
            id: String(data?.ordId || ''),
            status: data?.state === 'filled' ? 'closed' : (data?.state === 'live' ? 'open' : 'unknown'),
            filled: Number(data?.accFillSz || 0),
            price: Number(data?.avgPx || price || this.currentPrice || 0),
            timestamp: Number(data?.cTime || Date.now()),
            simulated: false,
            exchange: 'okx' as ExchangeName
          };
        },
        getBalance: async () => {
          if (!this.apiKey || !this.apiSecret || !this.apiPassword) {
            throw new Error('OKX account reads require EXCHANGE_API_KEY, EXCHANGE_API_SECRET, and EXCHANGE_API_PASSWORD');
          }
          const timestamp = Date.now().toString();
          const method = 'GET';
          const path = '/api/v5/account/balance';
          const signature = this.signOkxRequest(timestamp, method, path, '');

          const response = await axios.get(`${this.getOkxBaseUrl()}${path}`, {
            headers: {
              'OK-ACCESS-KEY': this.apiKey,
              'OK-ACCESS-SIGN': signature,
              'OK-ACCESS-TIMESTAMP': timestamp,
              'OK-ACCESS-PASSPHRASE': this.apiPassword,
              'Content-Type': 'application/json'
            }
          });

          const result: BalanceResponse = { simulated: false };
          const balances = response.data?.data?.[0]?.details || [];
          for (const row of balances) {
            const free = Number(row.cashBal || 0);
            if (free > 0) result[row.ccy] = free;
          }
          return result;
        },
        cancelOrder: async (orderId, symbol) => {
          if (!this.apiKey || !this.apiSecret || !this.apiPassword) {
            throw new Error('OKX order cancellation requires EXCHANGE_API_KEY, EXCHANGE_API_SECRET, and EXCHANGE_API_PASSWORD');
          }
          const pair = symbol.replace('/', '-');
          const timestamp = Date.now().toString();
          const method = 'POST';
          const path = '/api/v5/trade/cancel-order';
          const orderBody = JSON.stringify({
            instId: pair,
            ordId: orderId
          });
          const signature = this.signOkxRequest(timestamp, method, path, orderBody);

          await axios.post(`${this.getOkxBaseUrl()}${path}`, orderBody, {
            headers: {
              'OK-ACCESS-KEY': this.apiKey,
              'OK-ACCESS-SIGN': signature,
              'OK-ACCESS-TIMESTAMP': timestamp,
              'OK-ACCESS-PASSPHRASE': this.apiPassword,
              'Content-Type': 'application/json'
            }
          });
          return true;
        }
      };
    }

    if (this.exchangeName === 'coinbase') {
      return {
        capabilities: {
          provider: 'coinbase',
          supportsLiveTrading: true,
          supportsAccountReads: true,
          supportsPublicMarketData: true
        },
        placeOrder: async (symbol, side, amount, orderType, price) => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Coinbase order execution requires EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const pair = symbol.replace('/', '-');
          const timestamp = Date.now().toString();
          const method = 'POST';
          const path = '/api/v3/brokerage/orders';
          const orderBody = JSON.stringify({
            product_id: pair,
            side: side === 'buy' ? 'BUY' : 'SELL',
            order_type: orderType === 'limit' ? 'LIMIT' : 'MARKET',
            size: String(amount),
            base_size: String(amount),
            ...(price && { price: String(price) })
          });
          const signature = this.signCoinbaseRequest(timestamp, method, path, orderBody);

          const response = await axios.post(`${this.getCoinbaseBaseUrl()}${path}`, orderBody, {
            headers: {
              'CB-ACCESS-KEY': this.apiKey,
              'CB-ACCESS-SIGN': signature,
              'CB-ACCESS-TIMESTAMP': timestamp,
              'Content-Type': 'application/json'
            }
          });

          const data = response.data;
          return {
            id: String(data?.order_id || ''),
            status: data?.status === 'FILLED' ? 'closed' : (data?.status === 'OPEN' ? 'open' : 'unknown'),
            filled: Number(data?.filled_size || 0),
            price: Number(data?.average_filled_price || price || this.currentPrice || 0),
            timestamp: Number(data?.created_time ? new Date(data.created_time).getTime() : Date.now()),
            simulated: false,
            exchange: 'coinbase' as ExchangeName
          };
        },
        getBalance: async () => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Coinbase account reads require EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const timestamp = Date.now().toString();
          const method = 'GET';
          const path = '/api/v3/brokerage/accounts';
          const signature = this.signCoinbaseRequest(timestamp, method, path, '');

          const response = await axios.get(`${this.getCoinbaseBaseUrl()}${path}`, {
            headers: {
              'CB-ACCESS-KEY': this.apiKey,
              'CB-ACCESS-SIGN': signature,
              'CB-ACCESS-TIMESTAMP': timestamp,
              'Content-Type': 'application/json'
            }
          });

          const result: BalanceResponse = { simulated: false };
          const accounts = response.data?.accounts || [];
          for (const row of accounts) {
            const free = Number(row.available_balance?.value || 0);
            if (free > 0) result[row.currency] = free;
          }
          return result;
        },
        cancelOrder: async (orderId, symbol) => {
          if (!this.apiKey || !this.apiSecret) {
            throw new Error('Coinbase order cancellation requires EXCHANGE_API_KEY and EXCHANGE_API_SECRET');
          }
          const timestamp = Date.now().toString();
          const method = 'DELETE';
          const path = `/api/v3/brokerage/orders/${orderId}`;
          const signature = this.signCoinbaseRequest(timestamp, method, path, '');

          await axios.delete(`${this.getCoinbaseBaseUrl()}${path}`, {
            headers: {
              'CB-ACCESS-KEY': this.apiKey,
              'CB-ACCESS-SIGN': signature,
              'CB-ACCESS-TIMESTAMP': timestamp,
              'Content-Type': 'application/json'
            }
          });
          return true;
        }
      };
    }

    return {
      capabilities: {
        provider: this.exchangeName,
        supportsLiveTrading: false,
        supportsAccountReads: false,
        supportsPublicMarketData: true
      },
      placeOrder: async (_symbol, _side, amount, _orderType, price) => ({
        id: Math.random().toString(36).substring(7),
        status: 'closed',
        filled: amount,
        price: price || this.currentPrice,
        timestamp: Date.now(),
        simulated: true,
        exchange: this.exchangeName
      }),
      getBalance: async () => ({ USDT: 10000, BTC: 0.5, simulated: true }),
      cancelOrder: async () => true
    };
  }

  async placeOrder(symbol: string, side: 'buy' | 'sell', amount: number, orderType: 'market' | 'limit' = 'market', price?: number) {
    return this.executionAdapter.placeOrder(symbol, side, amount, orderType, price);
  }

  async getBalance() {
    return this.executionAdapter.getBalance();
  }

  async cancelOrder(orderId: string, symbol: string) {
    return this.executionAdapter.cancelOrder(orderId, symbol);
  }

  async placeOCOOrder(
    symbol: string,
    side: 'buy' | 'sell',
    quantity: number,
    stopPrice: number,
    takeProfitPrice: number
  ) {
    try {
      const result = await this.exchangeAdapter.placeOCOOrder(symbol, side, quantity, stopPrice, takeProfitPrice);

      // Log the OCO order placement
      await this.logSystemEvent('oco_order_placed', `OCO order placed for ${symbol}`, {
        symbol,
        side,
        quantity,
        stopPrice,
        takeProfitPrice,
        stopOrderId: result.stopOrder.id,
        takeProfitOrderId: result.takeProfitOrder.id
      });

      return result;
    } catch (error) {
      logger.error('Failed to place OCO order', {
        service: 'ExchangeConnector',
        exchange: this.exchangeName,
        symbol,
        error: error.message
      });
      throw error;
    }
  }

  private async logSystemEvent(eventType: string, message: string, metadata?: any) {
    try {
      const auditId = randomUUID();
      const timestamp = Date.now();
      const metadataJson = metadata ? JSON.stringify(metadata) : null;

      await runQuery(`
        INSERT INTO audit_system_events (id, event_type, message, timestamp, severity, metadata)
        VALUES (?, ?, ?, ?, ?, ?)
      `, [auditId, eventType, message, timestamp, 'info', metadataJson]);
    } catch (error) {
      logger.error('Failed to log system event', { error: error.message });
    }
  }

  async getCurrentPrice(symbol: string) {
    if (Date.now() - this.lastUpdate > 10000) {
      await this.fetchLatestPrice(symbol);
    }
    return this.currentPrice;
  }

  async getOrderBook(symbol: string, limit: number = 50): Promise<OrderBookData> {
    try {
      const orderBook = await this.exchangeAdapter.getOrderBook(symbol, limit);

      return {
        symbol,
        timestamp: orderBook.timestamp,
        bids: orderBook.bids.map(b => [b.price, b.quantity]),
        asks: orderBook.asks.map(a => [a.price, a.quantity]),
        exchange: this.exchangeName
      };
    } catch (error) {
      logger.error('Failed to fetch order book', {
        service: 'ExchangeConnector',
        exchange: this.exchangeName,
        symbol,
        error: error.message
      });

      // Return mock data for development
      return this.getMockOrderBook(symbol);
    }
  }

  private getOrderBookUrl(symbol: string, limit: number): string {
    const baseUrls = {
      binance: 'https://api.binance.com/api/v3/depth',
      kraken: 'https://api.kraken.com/0/public/Depth',
      okx: 'https://www.okx.com/api/v5/market/books',
      coinbase: 'https://api.exchange.coinbase.com/products/{symbol}/book',
      coinmarketcap: '' // No order book API
    };

    const baseUrl = baseUrls[this.exchangeName];
    if (!baseUrl) return '';

    switch (this.exchangeName) {
      case 'binance':
        return `${baseUrl}?symbol=${symbol.replace('/', '')}&limit=${limit}`;
      case 'kraken':
        return `${baseUrl}?pair=${symbol.replace('/', '')}&count=${limit}`;
      case 'okx':
        return `${baseUrl}?instId=${symbol}&sz=${limit}`;
      case 'coinbase':
        return baseUrl.replace('{symbol}', symbol);
      default:
        return '';
    }
  }

  private normalizeOrderBook(data: any, symbol: string): OrderBookData {
    let bids: [number, number][] = [];
    let asks: [number, number][] = [];

    switch (this.exchangeName) {
      case 'binance':
        bids = data.bids.map(([price, qty]: [string, string]) => [parseFloat(price), parseFloat(qty)]);
        asks = data.asks.map(([price, qty]: [string, string]) => [parseFloat(price), parseFloat(qty)]);
        break;
      case 'kraken':
        const pair = Object.keys(data.result)[0];
        bids = data.result[pair].bids.map(([price, qty]: [string, string]) => [parseFloat(price), parseFloat(qty)]);
        asks = data.result[pair].asks.map(([price, qty]: [string, string]) => [parseFloat(price), parseFloat(qty)]);
        break;
      case 'okx':
        bids = data.data[0].bids.map(([price, qty]: [string, string]) => [parseFloat(price), parseFloat(qty)]);
        asks = data.data[0].asks.map(([price, qty]: [string, string]) => [parseFloat(price), parseFloat(qty)]);
        break;
      case 'coinbase':
        bids = data.bids.map((bid: any) => [parseFloat(bid.price), parseFloat(bid.size)]);
        asks = data.asks.map((ask: any) => [parseFloat(ask.price), parseFloat(ask.size)]);
        break;
    }

    return {
      symbol,
      timestamp: Date.now(),
      bids,
      asks,
      exchange: this.exchangeName
    };
  }

  private getMockOrderBook(symbol: string): OrderBookData {
    const midPrice = 50000;
    const spread = 1;

    const bids: [number, number][] = [];
    const asks: [number, number][] = [];

    for (let i = 0; i < 20; i++) {
      bids.push([midPrice - spread * (i + 1), 1 + Math.random() * 5]);
      asks.push([midPrice + spread * (i + 1), 1 + Math.random() * 5]);
    }

    return {
      symbol,
      timestamp: Date.now(),
      bids,
      asks,
      exchange: 'mock'
    };
  }

  private getAuthHeaders(): Record<string, string> {
    // For public endpoints, usually no auth needed
    // Some exchanges require API key for higher rate limits
    if (this.apiKey && ['binance', 'okx'].includes(this.exchangeName)) {
      const timestamp = Date.now().toString();
      // Simplified - would need proper signing for production
      return {
        'X-MBX-APIKEY': this.apiKey,
        'X-MBX-TIMESTAMP': timestamp
      };
    }

    return {};
  }
}

type OrderBookData = {
  symbol: string;
  timestamp: number;
  bids: [number, number][]; // [price, quantity]
  asks: [number, number][]; // [price, quantity]
  exchange: string;
};

import { randomUUID } from 'crypto';
import os from 'os';
import path from 'path';
import { LogRotator, TimeBasedRotator } from './rotation.js';

export type LogLevel = 'info' | 'warn' | 'error' | 'debug';

export interface LogContext {
  requestId?: string;
  route?: string;
  method?: string;
  service?: string;
  [key: string]: unknown;
}

const parseLevel = (value: string | undefined): LogLevel => {
  // Default to 'info' in production, 'debug' in development
  const defaultLevel = process.env.NODE_ENV === 'production' ? 'info' : 'debug';
  const normalized = (value || defaultLevel).toLowerCase();
  if (normalized === 'debug' || normalized === 'info' || normalized === 'warn' || normalized === 'error') {
    return normalized;
  }
  return 'info';
};

const minimumLevel = parseLevel(process.env.LOG_LEVEL);
const levelOrder: Record<LogLevel, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40
};

const shouldLog = (level: LogLevel): boolean => levelOrder[level] >= levelOrder[minimumLevel];

// Log rotation setup
const logDir = process.env.LOG_DIR || path.join(process.cwd(), 'logs');
const logFile = path.join(logDir, 'trading-system.log');

// Ensure log directory exists
try {
  if (!require('fs').existsSync(logDir)) {
    require('fs').mkdirSync(logDir, { recursive: true });
  }
} catch (e) {
  // If we can't create log directory, fall back to stdout/stderr only
}

const sizeRotator = new LogRotator(logFile, {
  maxSizeBytes: 10 * 1024 * 1024, // 10MB
  maxFiles: 5,
  compress: false
});

const timeRotator = new TimeBasedRotator(logFile, {
  maxFiles: 7, // Keep 7 days of logs
  compress: false
});

// Start periodic checks
sizeRotator.startPeriodicCheck(60000); // Check every minute
timeRotator.checkAndRotate(); // Check on startup

function writeLogLine(line: string) {
  // Write to stdout/stderr
  if (line.includes('"level":"error"')) {
    process.stderr.write(`${line}\n`);
  } else {
    process.stdout.write(`${line}\n`);
  }

  // Write to file with rotation
  try {
    if (require('fs').existsSync(logDir)) {
      // Check for time-based rotation
      timeRotator.checkAndRotate();

      // Check for size-based rotation
      if (sizeRotator.needsRotation()) {
        sizeRotator.rotate();
      }

      require('fs').appendFileSync(logFile, `${line}\n`);
    }
  } catch (e) {
    // If file write fails, continue with stdout/stderr only
  }
}

function write(level: LogLevel, message: string, context: LogContext = {}) {
  if (!shouldLog(level)) return;

  const payload = {
    ts: new Date().toISOString(),
    level,
    message,
    service: context.service || 'trading-system',
    pid: process.pid,
    hostname: os.hostname(),
    ...context
  };

  const line = JSON.stringify(payload);
  writeLogLine(line);
}

export const logger = {
  debug: (message: string, context?: LogContext) => write('debug', message, context),
  info: (message: string, context?: LogContext) => write('info', message, context),
  warn: (message: string, context?: LogContext) => write('warn', message, context),
  error: (message: string, context?: LogContext) => write('error', message, context)
};

export function getRequestId(headerValue?: string | string[]): string {
  if (Array.isArray(headerValue)) {
    return headerValue[0] || randomUUID();
  }

  return typeof headerValue === 'string' && headerValue.trim().length > 0
    ? headerValue.trim()
    : randomUUID();
}

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export interface RotationConfig {
  maxSizeBytes: number;      // e.g., 10 * 1024 * 1024 for 10MB
  maxFiles: number;          // e.g., 5 to keep last 5 files
  compress: boolean;         // whether to gzip old logs
}

const DEFAULT_CONFIG: RotationConfig = {
  maxSizeBytes: 10 * 1024 * 1024, // 10MB
  maxFiles: 5,
  compress: false
};

export class LogRotator {
  private logFilePath: string;
  private config: RotationConfig;
  private checkInterval: NodeJS.Timeout | null = null;

  constructor(logFilePath: string, config: Partial<RotationConfig> = {}) {
    this.logFilePath = logFilePath;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Check if log file needs rotation based on size
   */
  needsRotation(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }
      const stats = fs.statSync(this.logFilePath);
      return stats.size >= this.config.maxSizeBytes;
    } catch (error) {
      console.error('Error checking log file size:', error);
      return false;
    }
  }

  /**
   * Rotate the log file
   */
  rotate(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }

      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const rotatedPath = `${this.logFilePath}.${timestamp}`;

      // Rename current log file
      fs.renameSync(this.logFilePath, rotatedPath);

      // Compress if enabled
      if (this.config.compress) {
        this.compressFile(rotatedPath);
      }

      // Clean up old files
      this.cleanupOldFiles();

      return true;
    } catch (error) {
      console.error('Error rotating log file:', error);
      return false;
    }
  }

  /**
   * Compress a log file using gzip
   */
  private compressFile(filePath: string): void {
    import('zlib').then(({ gzipSync }) => {
      try {
        const data = fs.readFileSync(filePath);
        const compressed = gzipSync(data);
        fs.writeFileSync(`${filePath}.gz`, compressed);
        fs.unlinkSync(filePath);
      } catch (error) {
        console.error('Error compressing log file:', error);
      }
    }).catch(() => {});
  }

  /**
   * Remove old rotated files beyond maxFiles limit
   */
  private cleanupOldFiles(): void {
    try {
      const logDir = path.dirname(this.logFilePath);
      const logBasename = path.basename(this.logFilePath);
      const files = fs.readdirSync(logDir)
        .filter(f => f.startsWith(logBasename) && f !== logBasename)
        .map(f => ({
          name: f,
          path: path.join(logDir, f),
          time: fs.statSync(path.join(logDir, f)).mtimeMs
        }))
        .sort((a, b) => b.time - a.time);

      // Remove files beyond maxFiles limit
      for (let i = this.config.maxFiles - 1; i < files.length; i++) {
        try {
          fs.unlinkSync(files[i].path);
        } catch (error) {
          console.error(`Error removing old log file ${files[i].path}:`, error);
        }
      }
    } catch (error) {
      console.error('Error cleaning up old log files:', error);
    }
  }

  /**
   * Start periodic rotation check
   */
  startPeriodicCheck(intervalMs: number = 60000): void {
    if (this.checkInterval) {
      return;
    }
    this.checkInterval = setInterval(() => {
      if (this.needsRotation()) {
        this.rotate();
      }
    }, intervalMs);
    this.checkInterval.unref?.();
  }

  /**
   * Stop periodic rotation check
   */
  stopPeriodicCheck(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
    }
  }
}

/**
 * Daily time-based rotation utility
 */
export class TimeBasedRotator {
  private logFilePath: string;
  private lastRotationDate: string;
  private config: RotationConfig;

  constructor(logFilePath: string, config: Partial<RotationConfig> = {}) {
    this.logFilePath = logFilePath;
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.lastRotationDate = new Date().toISOString().split('T')[0];
  }

  /**
   * Check if a new day has started and rotate if needed
   */
  checkAndRotate(): boolean {
    const today = new Date().toISOString().split('T')[0];
    if (today !== this.lastRotationDate) {
      this.lastRotationDate = today;
      return this.rotate();
    }
    return false;
  }

  /**
   * Rotate the log file (time-based)
   */
  rotate(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }

      const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
      const rotatedPath = `${this.logFilePath}.${yesterday}`;

      // Remove existing rotated file for this date
      if (fs.existsSync(rotatedPath)) {
        fs.unlinkSync(rotatedPath);
      }

      // Rename current log file
      fs.renameSync(this.logFilePath, rotatedPath);

      // Compress if enabled
      if (this.config.compress) {
        this.compressFile(rotatedPath);
      }

      // Clean up old files
      this.cleanupOldFiles();

      return true;
    } catch (error) {
      console.error('Error rotating log file:', error);
      return false;
    }
  }

  private compressFile(filePath: string): void {
    import('zlib').then(({ gzipSync }) => {
      try {
        const data = fs.readFileSync(filePath);
        const compressed = gzipSync(data);
        fs.writeFileSync(`${filePath}.gz`, compressed);
        fs.unlinkSync(filePath);
      } catch (error) {
        console.error('Error compressing log file:', error);
      }
    }).catch(() => {});
  }

  private cleanupOldFiles(): void {
    try {
      const logDir = path.dirname(this.logFilePath);
      const logBasename = path.basename(this.logFilePath);
      const files = fs.readdirSync(logDir)
        .filter(f => f.startsWith(logBasename) && f !== logBasename)
        .map(f => ({
          name: f,
          path: path.join(logDir, f),
          time: fs.statSync(path.join(logDir, f)).mtimeMs
        }))
        .sort((a, b) => b.time - a.time);

      for (let i = this.config.maxFiles - 1; i < files.length; i++) {
        try {
          fs.unlinkSync(files[i].path);
        } catch (error) {
          console.error(`Error removing old log file ${files[i].path}:`, error);
        }
      }
    } catch (error) {
      console.error('Error cleaning up old log files:', error);
    }
  }
}

import axios from 'axios';
import crypto from 'crypto';

export type ExchangeName = 'binance' | 'kraken' | 'okx' | 'coinbase';

export interface OrderBookEntry {
  price: number;
  quantity: number;
}

export interface OrderBook {
  bids: OrderBookEntry[];
  asks: OrderBookEntry[];
  timestamp: number;
}

export interface Position {
  symbol: string;
  side: 'long' | 'short';
  quantity: number;
  entryPrice: number;
  currentPrice: number;
  pnl: number;
  leverage: number;
}

export interface Order {
  id: string;
  symbol: string;
  side: 'buy' | 'sell';
  type: 'market' | 'limit' | 'stop' | 'oco';
  quantity: number;
  price?: number;
  stopPrice?: number;
  takeProfitPrice?: number;
  status: 'pending' | 'open' | 'filled' | 'canceled' | 'expired';
  timestamp: number;
  linkedOrderId?: string; // For OCO orders
}

export abstract class BaseExchangeAdapter {
  protected apiKey: string;
  protected apiSecret: string;
  protected apiPassword?: string;
  protected testnet: boolean;

  constructor(apiKey: string, apiSecret: string, apiPassword?: string, testnet: boolean = true) {
    this.apiKey = apiKey;
    this.apiSecret = apiSecret;
    this.apiPassword = apiPassword;
    this.testnet = testnet;
  }

  abstract getName(): ExchangeName;
  abstract placeOrder(order: Omit<Order, 'id' | 'status' | 'timestamp'>): Promise<Order>;
  abstract placeOCOOrder(
    symbol: string,
    side: 'buy' | 'sell',
    quantity: number,
    stopPrice: number,
    takeProfitPrice: number
  ): Promise<{ stopOrder: Order; takeProfitOrder: Order }>;
  abstract cancelOrder(orderId: string): Promise<boolean>;
  abstract getPositions(): Promise<Position[]>;
  abstract getOrderBook(symbol: string, depth: number): Promise<OrderBook>;
  abstract getBalance(): Promise<Record<string, number>>;
}

export class BinanceAdapter extends BaseExchangeAdapter {
  getName(): ExchangeName {
    return 'binance';
  }

  private getBaseUrl(): string {
    return this.testnet ? 'https://testnet.binance.vision' : 'https://api.binance.com';
  }

  private signRequest(query: string): string {
    return crypto.createHmac('sha256', this.apiSecret).update(query).digest('hex');
  }

  async placeOrder(order: Omit<Order, 'id' | 'status' | 'timestamp'>): Promise<Order> {
    const pair = order.symbol.replace('/', '');
    const params = new URLSearchParams({
      symbol: pair,
      side: order.side.toUpperCase(),
      type: order.type.toUpperCase(),
      quantity: String(order.quantity),
      timestamp: String(Date.now())
    });

    if (order.type === 'limit' && order.price) {
      params.set('price', String(order.price));
      params.set('timeInForce', 'GTC');
    }

    const signature = this.signRequest(params.toString());
    params.set('signature', signature);

    const response = await axios.post(`${this.getBaseUrl()}/api/v3/order`, params.toString(), {
      headers: {
        'X-MBX-APIKEY': this.apiKey,
        'Content-Type': 'application/x-www-form-urlencoded'
      }
    });

    return {
      ...order,
      id: String(response.data.orderId),
      status: response.data.status === 'FILLED' ? 'filled' : 'open',
      timestamp: response.data.transactTime
    };
  }

  async placeOCOOrder(
    symbol: string,
    side: 'buy' | 'sell',
    quantity: number,
    stopPrice: number,
    takeProfitPrice: number
  ): Promise<{ stopOrder: Order; takeProfitOrder: Order }> {
    const pair = symbol.replace('/', '');
    const params = new URLSearchParams({
      symbol: pair,
      side: side.toUpperCase(),
      quantity: String(quantity),
      price: String(takeProfitPrice),
      stopPrice: String(stopPrice),
      stopLimitPrice: String(stopPrice), // Required for OCO
      timestamp: String(Date.now())
    });

    const signature = this.signRequest(params.toString());
    params.set('signature', signature);

    const response = await axios.post(`${this.getBaseUrl()}/api/v3/order/oco`, params.toString(), {
      headers: {
        'X-MBX-APIKEY': this.apiKey,
        'Content-Type': 'application/x-www-form-urlencoded'
      }
    });

    const ocoData = response.data.orders;
    const stopOrderData = ocoData.find((o: any) => o.type === 'STOP_LOSS_LIMIT');
    const tpOrderData = ocoData.find((o: any) => o.type === 'LIMIT_MAKER');

    const stopOrder: Order = {
      id: String(stopOrderData.orderId),
      symbol,
      side,
      type: 'stop',
      quantity,
      stopPrice,
      status: 'open',
      timestamp: response.data.transactTime
    };

    const takeProfitOrder: Order = {
      id: String(tpOrderData.orderId),
      symbol,
      side,
      type: 'limit',
      quantity,
      price: takeProfitPrice,
      status: 'open',
      timestamp: response.data.transactTime
    };

    return { stopOrder, takeProfitOrder };
  }

  async cancelOrder(orderId: string): Promise<boolean> {
    // Implementation similar to existing connector
    return true;
  }

  async getPositions(): Promise<Position[]> {
    // Implementation for getting positions
    return [];
  }

  async getOrderBook(symbol: string, depth: number): Promise<OrderBook> {
    const pair = symbol.replace('/', '');
    const response = await axios.get(`${this.getBaseUrl()}/api/v3/depth`, {
      params: { symbol: pair, limit: depth }
    });

    return {
      bids: response.data.bids.map(([price, qty]: [string, string]) => ({
        price: parseFloat(price),
        quantity: parseFloat(qty)
      })),
      asks: response.data.asks.map(([price, qty]: [string, string]) => ({
        price: parseFloat(price),
        quantity: parseFloat(qty)
      })),
      timestamp: Date.now()
    };
  }

  async getBalance(): Promise<Record<string, number>> {
    const params = new URLSearchParams({ timestamp: String(Date.now()) });
    params.set('signature', this.signRequest(params.toString()));

    const response = await axios.get(`${this.getBaseUrl()}/api/v3/account`, {
      params,
      headers: { 'X-MBX-APIKEY': this.apiKey }
    });

    const balances: Record<string, number> = {};
    for (const balance of response.data.balances) {
      const free = parseFloat(balance.free);
      if (free > 0) balances[balance.asset] = free;
    }
    return balances;
  }
}

