import { runQuery } from '../database.js';
import { logger } from '../logging/logger.js';
import { BaseExchangeAdapter } from './adapter.js';

export interface PositionReconciliation {
  symbol: string;
  localQuantity: number;
  exchangeQuantity: number;
  discrepancy: number;
  timestamp: number;
  resolved: boolean;
  resolutionAction?: string;
}

export class PositionReconciliationEngine {
  private exchangeAdapters: Map<string, BaseExchangeAdapter> = new Map();
  private reconciliationInterval: NodeJS.Timeout | null = null;
  private isRunning = false;

  registerAdapter(exchangeName: string, adapter: BaseExchangeAdapter) {
    this.exchangeAdapters.set(exchangeName, adapter);
  }

  startReconciliation(intervalMs: number = 30000) {
    if (this.isRunning) return;

    this.isRunning = true;
    this.reconciliationInterval = setInterval(async () => {
      try {
        await this.performReconciliation();
      } catch (error) {
        logger.error('Reconciliation cycle failed', { error: error.message });
      }
    }, intervalMs);
    this.reconciliationInterval.unref?.();

    logger.info('Position reconciliation engine started', { intervalMs });
  }

  stopReconciliation() {
    if (this.reconciliationInterval) {
      clearInterval(this.reconciliationInterval);
      this.reconciliationInterval = null;
    }
    this.isRunning = false;
    logger.info('Position reconciliation engine stopped');
  }

  private async performReconciliation() {
    const exchanges = Array.from(this.exchangeAdapters.keys());

    for (const exchangeName of exchanges) {
      try {
        await this.reconcileExchangePositions(exchangeName);
      } catch (error) {
        logger.error('Failed to reconcile positions for exchange', {
          exchange: exchangeName,
          error: error.message
        });
      }
    }
  }

  private async reconcileExchangePositions(exchangeName: string) {
    const adapter = this.exchangeAdapters.get(exchangeName);
    if (!adapter) return;

    // Get exchange positions
    const exchangePositions = await adapter.getPositions();

    // Get local shadow positions for this exchange
    const localPositions = await this.getLocalPositions(exchangeName);

    // Compare positions
    const reconciliationResults: PositionReconciliation[] = [];

    // Check all symbols that have positions in either local or exchange
    const allSymbols = new Set([
      ...exchangePositions.map(p => p.symbol),
      ...localPositions.map(p => p.symbol)
    ]);

    for (const symbol of allSymbols) {
      const exchangePos = exchangePositions.find(p => p.symbol === symbol);
      const localPos = localPositions.find(p => p.symbol === symbol);

      const exchangeQty = exchangePos?.quantity || 0;
      const localQty = localPos?.quantity || 0;
      const discrepancy = Math.abs(exchangeQty - localQty);

      if (discrepancy > 0.001) { // Allow for small floating point differences
        const reconciliation: PositionReconciliation = {
          symbol,
          localQuantity: localQty,
          exchangeQuantity: exchangeQty,
          discrepancy,
          timestamp: Date.now(),
          resolved: false
        };

        reconciliationResults.push(reconciliation);

        // Attempt auto-resolution
        await this.attemptAutoResolution(exchangeName, reconciliation, adapter);
      }
    }

    // Log reconciliation results
    if (reconciliationResults.length > 0) {
      await this.logReconciliationResults(exchangeName, reconciliationResults);
    }
  }

  private async getLocalPositions(exchangeName: string): Promise<any[]> {
    // Query shadow_trades for open positions on this exchange
    const rows = await runQuery(`
      SELECT symbol, SUM(CASE WHEN side = 'buy' THEN amount ELSE -amount END) as net_quantity
      FROM shadow_trades
      WHERE status = 'open' AND exchange = ?
      GROUP BY symbol
      HAVING net_quantity != 0
    `, [exchangeName], 'all');

    return rows.map(row => ({
      symbol: row.symbol,
      quantity: row.net_quantity
    }));
  }

  private async attemptAutoResolution(
    exchangeName: string,
    reconciliation: PositionReconciliation,
    adapter: BaseExchangeAdapter
  ) {
    try {
      if (Math.abs(reconciliation.discrepancy) > 0.01) { // Significant discrepancy
        // Close the phantom position on exchange if local shows zero
        if (reconciliation.localQuantity === 0 && Math.abs(reconciliation.exchangeQuantity) > 0) {
          logger.warn('Detected ghost position on exchange, attempting to close', {
            exchange: exchangeName,
            symbol: reconciliation.symbol,
            quantity: reconciliation.exchangeQuantity
          });

          // Place market order to close position
          const side = reconciliation.exchangeQuantity > 0 ? 'sell' : 'buy';
          const quantity = Math.abs(reconciliation.exchangeQuantity);

          await adapter.placeOrder({
            symbol: reconciliation.symbol,
            side,
            type: 'market',
            quantity
          });

          reconciliation.resolved = true;
          reconciliation.resolutionAction = `Closed ghost position: ${side} ${quantity}`;
        }
        // If exchange shows zero but local shows position, this is a sync issue
        else if (reconciliation.exchangeQuantity === 0 && Math.abs(reconciliation.localQuantity) > 0) {
          logger.warn('Detected missing position on exchange', {
            exchange: exchangeName,
            symbol: reconciliation.symbol,
            localQuantity: reconciliation.localQuantity
          });

          // This requires manual intervention - log for review
          reconciliation.resolutionAction = 'Manual review required - position missing on exchange';
        }
      } else {
        // Small discrepancy, likely rounding error - mark as resolved
        reconciliation.resolved = true;
        reconciliation.resolutionAction = 'Small discrepancy resolved (rounding error)';
      }
    } catch (error) {
      logger.error('Auto-resolution failed', {
        exchange: exchangeName,
        symbol: reconciliation.symbol,
        error: error.message
      });
      reconciliation.resolutionAction = `Auto-resolution failed: ${error.message}`;
    }
  }

  private async logReconciliationResults(exchangeName: string, results: PositionReconciliation[]) {
    const timestamp = Date.now();

    for (const result of results) {
      await runQuery(`
        INSERT INTO order_reconciliation_log
        (exchange_name, symbol, local_quantity, exchange_quantity, discrepancy, resolved, resolution_action, timestamp)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `, [
        exchangeName,
        result.symbol,
        result.localQuantity,
        result.exchangeQuantity,
        result.discrepancy,
        result.resolved,
        result.resolutionAction || null,
        timestamp
      ]);
    }

    const unresolvedCount = results.filter(r => !r.resolved).length;
    if (unresolvedCount > 0) {
      logger.warn('Position reconciliation completed with unresolved discrepancies', {
        exchange: exchangeName,
        totalDiscrepancies: results.length,
        unresolvedCount
      });
    } else {
      logger.info('Position reconciliation completed successfully', {
        exchange: exchangeName,
        checkedPositions: results.length
      });
    }
  }

  async getReconciliationHistory(exchangeName?: string, limit: number = 100): Promise<any[]> {
    let query = `
      SELECT * FROM order_reconciliation_log
      WHERE 1=1
    `;
    const params: any[] = [];

    if (exchangeName) {
      query += ' AND exchange_name = ?';
      params.push(exchangeName);
    }

    query += ' ORDER BY timestamp DESC LIMIT ?';
    params.push(limit);

    return await runQuery(query, params, 'all');
  }
}

import { EMA, RSI, BollingerBands, ADX, StochasticRSI, MACD, SMA, ATR } from 'technicalindicators';
import { Worker, isMainThread, parentPort, workerData } from 'worker_threads';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export class IndicatorEngine {
  EMA_FAST = 9;
  EMA_MEDIUM = 21;
  EMA_SLOW = 50;
  RSI_PERIOD = 14;
  BB_PERIOD = 20;
  BB_STD_DEV = 2.0;
  ADX_PERIOD = 14;
  STOCH_RSI_PERIOD = 14;
  VOLUME_PERIOD = 20;

  private workerPool: Worker[] = [];
  private maxWorkers = 4;

  async calculateAllParallel(candles: Candle[]): Promise<any[]> {
    if (candles.length < 50) {
      throw new Error("Need at least 50 candles for indicator calculation");
    }

    // Split work across workers
    const chunkSize = Math.ceil(candles.length / this.maxWorkers);
    const promises: Promise<any[]>[] = [];

    for (let i = 0; i < this.maxWorkers; i++) {
      const start = i * chunkSize;
      const end = Math.min(start + chunkSize + 50, candles.length); // Include overlap for accurate calculations
      const chunk = candles.slice(start, end);

      promises.push(this.calculateChunk(chunk, start));
    }

    const results = await Promise.all(promises);

    // Merge results
    const merged = this.mergeResults(results);
    return merged.filter(r => r.ema_50 !== null);
  }

  private async calculateChunk(candles: Candle[], offset: number): Promise<any[]> {
    return new Promise((resolve, reject) => {
      const worker = new Worker(path.join(__dirname, 'indicator-worker.js'), {
        workerData: { candles, offset }
      });

      worker.on('message', resolve);
      worker.on('error', reject);
      worker.on('exit', (code) => {
        if (code !== 0) {
          reject(new Error(`Worker stopped with exit code ${code}`));
        }
      });
    });
  }

  private mergeResults(results: any[][]): any[] {
    // Simple merge - take the longest result and fill gaps
    const maxLength = Math.max(...results.map(r => r.length));
    const merged = new Array(maxLength);

    for (let i = 0; i < maxLength; i++) {
      for (const result of results) {
        if (result[i]) {
          merged[i] = result[i];
          break;
        }
      }
    }

    return merged;
  }

  calculateAll(candles: Candle[]) {
    if (candles.length < 50) {
      throw new Error("Need at least 50 candles for indicator calculation");
    }

    const closes = candles.map(c => c.close);
    const highs = candles.map(c => c.high);
    const lows = candles.map(c => c.low);
    const volumes = candles.map(c => c.volume);

    const ema9 = EMA.calculate({ period: this.EMA_FAST, values: closes });
    const ema21 = EMA.calculate({ period: this.EMA_MEDIUM, values: closes });
    const ema50 = EMA.calculate({ period: this.EMA_SLOW, values: closes });

    const rsi14 = RSI.calculate({ period: this.RSI_PERIOD, values: closes });

    const bb = BollingerBands.calculate({ period: this.BB_PERIOD, stdDev: this.BB_STD_DEV, values: closes });

    const adx = ADX.calculate({ period: this.ADX_PERIOD, high: highs, low: lows, close: closes });

    const stochRsi = StochasticRSI.calculate({ rsiPeriod: this.STOCH_RSI_PERIOD, stochasticPeriod: 14, kPeriod: 3, dPeriod: 3, values: closes });

    const macd = MACD.calculate({ fastPeriod: 12, slowPeriod: 26, signalPeriod: 9, SimpleMAOscillator: false, SimpleMASignal: false, values: closes });

    const volumeSma20 = SMA.calculate({ period: this.VOLUME_PERIOD, values: volumes });

    const atr = ATR.calculate({ period: 14, high: highs, low: lows, close: closes });

    // Calculate VWAP
    const vwap = [];
    let cumulativeTypicalPriceVolume = 0;
    let cumulativeVolume = 0;
    for (let i = 0; i < candles.length; i++) {
      const typicalPrice = (highs[i] + lows[i] + closes[i]) / 3;
      cumulativeTypicalPriceVolume += typicalPrice * volumes[i];
      cumulativeVolume += volumes[i];
      vwap.push(cumulativeTypicalPriceVolume / cumulativeVolume);
    }

    // Align arrays to the end
    const result = [];
    for (let i = 0; i < candles.length; i++) {
      const c = candles[i];

      const getVal = (arr: any[], offset: number) => {
        const idx = i - (candles.length - arr.length);
        return idx >= 0 ? arr[idx] : null;
      };

      const bbVal = getVal(bb, 0);
      const adxVal = getVal(adx, 0);
      const stochRsiVal = getVal(stochRsi, 0);
      const macdVal = getVal(macd, 0);

      result.push({
        ...c,
        ema_9: getVal(ema9, 0),
        ema_21: getVal(ema21, 0),
        ema_50: getVal(ema50, 0),
        rsi_14: getVal(rsi14, 0),
        bb_upper: bbVal ? bbVal.upper : null,
        bb_middle: bbVal ? bbVal.middle : null,
        bb_lower: bbVal ? bbVal.lower : null,
        bb_width: bbVal ? (bbVal.upper - bbVal.lower) / bbVal.middle : null,
        vwap: vwap[i],
        adx: adxVal ? adxVal.adx : null,
        adx_plus: adxVal ? adxVal.pdi : null,
        adx_minus: adxVal ? adxVal.mdi : null,
        stoch_rsi_k: stochRsiVal ? stochRsiVal.k : null,
        stoch_rsi_d: stochRsiVal ? stochRsiVal.d : null,
        macd_line: macdVal ? macdVal.MACD : null,
        signal_line: macdVal ? macdVal.signal : null,
        macd_histogram: macdVal ? macdVal.histogram : null,
        volume_sma_20: getVal(volumeSma20, 0),
        volume_ratio: getVal(volumeSma20, 0) ? c.volume / getVal(volumeSma20, 0) : null,
        atr: getVal(atr, 0)
      });
    }

    // Filter out rows with nulls (warmup period)
    return result.filter(r => r.ema_50 !== null && r.adx !== null);
  }
}

export enum RegimeType {
  STRONG_BULL = "strong_bull",
  WEAK_BULL = "weak_bull",
  BEAR = "bear",
  SIDEWAYS = "sideways",
  UNCERTAIN = "uncertain"
}

export class RegimeDetector {
  static aiEnabled = true;

  STRONG_BULL_THRESHOLDS = {
    adx_min: 30,
    price_30d_min: 0.12,
    price_7d_min: 0.03,
    volume_ratio_min: 1.3
  };

  BEAR_THRESHOLDS = {
    price_30d_max: -0.08,
    price_7d_max: -0.05,
    rsi_avg_max: 40
  };

  SIDEWAYS_THRESHOLDS = {
    adx_max: 20,
    price_30d_range: 0.04,
    price_7d_range: 0.015
  };

  WEAK_BULL_THRESHOLDS = {
    price_30d_min: 0.04,
    price_30d_max: 0.12
  };

  async detect(df: any[], useAI: boolean = false, shadowPerformance: any = null, marketContext: any = null) {
    const metrics = this._calculateMetrics(df);
    let { regime, confidence, reasoning } = this._classifyRegime(metrics);
    ({ regime, confidence, reasoning } = this._applyNewsSentimentWeight(regime, confidence, reasoning, marketContext));

    let aiValidation = null;

    if (useAI && RegimeDetector.aiEnabled) {
      try {
        const apiKey = process.env.GEMINI_API_KEY;
        if (!apiKey) {
          console.warn("AI Regime Analysis skipped: GEMINI_API_KEY is not set.");
        } else {
          const { GoogleGenAI } = await import('@google/genai');
          const ai = new GoogleGenAI({ apiKey });

          // Use provided market context or default to mock
          const context = marketContext || {
            btc_dominance: "52%",
            fear_greed_index: 45,
            major_news: "Market awaiting key economic data",
            all_news: ["Market awaiting key economic data"]
          };

          const prompt = `You are analyzing trading system performance and news sentiment for regime validation.
Current regime detected by rule-based algorithm: ${regime}
Rule-based confidence: ${confidence}%

Technical Metrics: ${JSON.stringify(metrics)}
Shadow Performance (7d): ${JSON.stringify(shadowPerformance)}
Market Context (News & Global): ${JSON.stringify(context)}

Tasks:
1. Validate if regime classification is correct based on technicals AND news sentiment.
2. Analyze the sentiment of the provided news (all_news). Are they bullish, bearish, or neutral?
3. Identify if external factors (news, macro) explain recent shadow performance.
4. Recommend: [continue | reduce_risk | halt | switch]

Output JSON only:
{
  "regime_validation": "correct" | "misclassified",
  "news_sentiment": "bullish" | "bearish" | "neutral",
  "sentiment_score": number (-1.0 to 1.0),
  "performance_explanation": "string (1 sentence)",
  "external_factors": ["string"],
  "recommended_action": "continue" | "reduce_risk" | "halt" | "switch",
  "confidence": number (0-100)
}`;

          const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
              responseMimeType: "application/json"
            }
          });

          if (response.text) {
            aiValidation = JSON.parse(response.text);
            reasoning = `AI Analysis: ${aiValidation.performance_explanation} Sentiment: ${aiValidation.news_sentiment} (${aiValidation.sentiment_score}). Rec: ${aiValidation.recommended_action}.`;

            // Adjust confidence based on sentiment alignment
            if (aiValidation.news_sentiment === 'bullish' && (regime === RegimeType.STRONG_BULL || regime === RegimeType.WEAK_BULL)) {
              confidence = Math.min(100, confidence + 5);
            } else if (aiValidation.news_sentiment === 'bearish' && regime === RegimeType.BEAR) {
              confidence = Math.min(100, confidence + 5);
            } else if (aiValidation.news_sentiment !== 'neutral') {
              // Dissonance between technicals and news
              confidence = Math.max(50, confidence - 10);
            }
          }
        }
      } catch (e: any) {
        if (e.message && e.message.includes("API_KEY_INVALID")) {
          console.error("AI Regime Analysis failed: Invalid API Key. Disabling AI features.");
          RegimeDetector.aiEnabled = false;
        } else {
          console.error("AI Regime Analysis failed:", e);
        }
      }
    }

    return {
      regime,
      confidence,
      metrics,
      reasoning,
      aiValidation,
      timestamp: df[df.length - 1]?.time || null
    };
  }

  _calculateMetrics(df: any[]) {
    const periods_30d = Math.min(df.length, 2880);
    const periods_7d = Math.min(df.length, 672);

    const price_30d = this._calculatePriceChange(df, periods_30d);
    const price_7d = this._calculatePriceChange(df, periods_7d);

    const lastRow = df[df.length - 1];
    const adx = lastRow.adx;

    const last30d = df.slice(-periods_30d);
    const avg_volume_30d = last30d.reduce((sum, row) => sum + (row.volume || 0), 0) / last30d.length;

    const last7d = df.slice(-periods_7d);
    const avg_volume_7d = last7d.reduce((sum, row) => sum + (row.volume || 0), 0) / last7d.length;

    const volume_ratio = avg_volume_30d > 0 ? avg_volume_7d / avg_volume_30d : 1;

    const rsi_avg_7d = last7d.reduce((sum, row) => sum + (row.rsi_14 || 0), 0) / last7d.length;

    return {
      price_change_30d: price_30d,
      price_change_7d: price_7d,
      adx,
      volume_ratio,
      rsi_avg_7d
    };
  }

  _calculatePriceChange(df: any[], periods: number) {
    if (df.length < periods) periods = df.length;
    if (periods === 0) return 0;

    const current = df[df.length - 1].close;
    const past = df[df.length - periods].close;

    return (current - past) / past;
  }

  _classifyRegime(metrics: any) {
    const { adx, price_change_30d, price_change_7d, volume_ratio, rsi_avg_7d } = metrics;

    // console.log(`[RegimeDetector] Classifying: adx=${adx}, price30d=${price_change_30d}, price7d=${price_change_7d}, vol=${volume_ratio}`);

    if (
      adx > this.STRONG_BULL_THRESHOLDS.adx_min &&
      price_change_30d > this.STRONG_BULL_THRESHOLDS.price_30d_min &&
      price_change_7d >= this.STRONG_BULL_THRESHOLDS.price_7d_min &&
      volume_ratio >= this.STRONG_BULL_THRESHOLDS.volume_ratio_min
    ) {
      return {
        regime: RegimeType.STRONG_BULL,
        confidence: 95,
        reasoning: `Strong uptrend: ADX ${adx.toFixed(1)}, +${(price_change_30d * 100).toFixed(1)}% (30d), volume ${volume_ratio.toFixed(1)}x average`
      };
    }

    if (
      price_change_30d < this.BEAR_THRESHOLDS.price_30d_max ||
      (price_change_7d < this.BEAR_THRESHOLDS.price_7d_max && rsi_avg_7d < this.BEAR_THRESHOLDS.rsi_avg_max)
    ) {
      return {
        regime: RegimeType.BEAR,
        confidence: 85,
        reasoning: `Downtrend detected: ${(price_change_30d * 100).toFixed(1)}% (30d), RSI avg ${rsi_avg_7d.toFixed(1)}`
      };
    }

    if (
      adx < this.SIDEWAYS_THRESHOLDS.adx_max &&
      Math.abs(price_change_30d) < this.SIDEWAYS_THRESHOLDS.price_30d_range &&
      Math.abs(price_change_7d) < this.SIDEWAYS_THRESHOLDS.price_7d_range
    ) {
      return {
        regime: RegimeType.SIDEWAYS,
        confidence: 80,
        reasoning: `Range-bound: ADX ${adx.toFixed(1)}, price ±${(Math.abs(price_change_30d) * 100).toFixed(1)}% (30d)`
      };
    }

    if (
      price_change_30d > this.WEAK_BULL_THRESHOLDS.price_30d_min &&
      price_change_30d < this.WEAK_BULL_THRESHOLDS.price_30d_max
    ) {
      return {
        regime: RegimeType.WEAK_BULL,
        confidence: 70,
        reasoning: `Weak uptrend: +${(price_change_30d * 100).toFixed(1)}% (30d), ADX ${adx.toFixed(1)}`
      };
    }

    return {
      regime: RegimeType.UNCERTAIN,
      confidence: 50,
      reasoning: "Market regime unclear, awaiting confirmation"
    };
  }

  _applyNewsSentimentWeight(regime: RegimeType, confidence: number, reasoning: string, marketContext: any) {
    if (!marketContext) return { regime, confidence, reasoning };

    const sentimentLabel = String(marketContext.news_sentiment || '').toLowerCase();
    const rawScore = Number(marketContext.sentiment_score ?? Number.NaN);
    const score = Number.isFinite(rawScore)
      ? Math.max(-1, Math.min(1, rawScore))
      : sentimentLabel === 'bullish'
        ? 0.5
        : sentimentLabel === 'bearish'
          ? -0.5
          : 0;
    if (score === 0) return { regime, confidence, reasoning };

    const isBullRegime = regime === RegimeType.STRONG_BULL || regime === RegimeType.WEAK_BULL;
    const aligns = (score > 0 && isBullRegime) || (score < 0 && regime === RegimeType.BEAR);
    const magnitudeBoost = Math.max(2, Math.round(Math.abs(score) * 10));

    if (aligns) {
      const boostedConfidence = Math.min(100, confidence + magnitudeBoost);
      return {
        regime,
        confidence: boostedConfidence,
        reasoning: `${reasoning}. News sentiment alignment score=${score.toFixed(2)} boosted confidence by ${boostedConfidence - confidence}.`
      };
    }

    if (regime === RegimeType.UNCERTAIN && Math.abs(score) >= 0.75) {
      const sentimentRegime = score > 0 ? RegimeType.WEAK_BULL : RegimeType.BEAR;
      const sentimentConfidence = Math.max(confidence, 60 + Math.round(Math.abs(score) * 10));
      return {
        regime: sentimentRegime,
        confidence: Math.min(85, sentimentConfidence),
        reasoning: `${reasoning}. Strong news sentiment score=${score.toFixed(2)} nudged regime to ${sentimentRegime}.`
      };
    }

    const reducedConfidence = Math.max(45, confidence - Math.max(4, magnitudeBoost));
    return {
      regime,
      confidence: reducedConfidence,
      reasoning: `${reasoning}. News sentiment dissonance score=${score.toFixed(2)} reduced confidence by ${confidence - reducedConfidence}.`
    };
  }

  shouldUpdateRegime(lastRegime: RegimeType, newRegime: RegimeType, newConfidence: number) {
    if (lastRegime !== newRegime && newConfidence > 75) return true;
    if (lastRegime === RegimeType.UNCERTAIN && newConfidence > 70) return true;
    return false;
  }
}

import { RegimeType } from '../regime/detector.js';

export interface Signal {
  symbol: string;
  side: 'buy' | 'sell';
  confidence: number;
  entryPrice: number;
  stopLoss: number;
  takeProfit: number;
  reasoning: string;
  indicators: string[]; // List of indicators that triggered the signal
  aiWarning?: boolean; // Flag for non-critical AI errors
}

export class SignalGenerator {
  static aiEnabled = true;
  static aiHealth: {
    totalRequests: number;
    successfulConfirmations: number;
    failedConfirmations: number;
    lastFailureReason: string | null;
    circuitBreakerTripped: boolean;
    consecutiveFailures: number;
  } = {
    totalRequests: 0,
    successfulConfirmations: 0,
    failedConfirmations: 0,
    lastFailureReason: null,
    circuitBreakerTripped: false,
    consecutiveFailures: 0
  };

  private streamingBuffers: Map<string, any[]> = new Map();
  private maxBufferSize = 100;

  // ATR multipliers for different regimes (conservative to aggressive)
  private static ATR_STOP_MULTIPLIERS = {
    ultra_conservative: 2.0,
    conservative: 1.8,
    moderate: 1.5,
    aggressive: 1.2,
    degen: 1.0,
    ai_enhanced: 1.5
  };

  private static ATR_PROFIT_MULTIPLIERS = {
    ultra_conservative: 1.0,
    conservative: 1.2,
    moderate: 1.5,
    aggressive: 2.0,
    degen: 2.5,
    ai_enhanced: 1.5
  };

  static resetAIHealth() {
    this.aiHealth = {
      totalRequests: 0,
      successfulConfirmations: 0,
      failedConfirmations: 0,
      lastFailureReason: null,
      circuitBreakerTripped: false,
      consecutiveFailures: 0
    };
  }

  static getAIHealth() {
    const h = this.aiHealth;
    const successRate = h.totalRequests > 0 ? (h.successfulConfirmations / h.totalRequests) * 100 : 0;
    return {
      ...h,
      successRate,
      aiAvailable: this.aiEnabled && !this.aiHealth.circuitBreakerTripped
    };
  }

  private calculateATRAdjustedLevels(entryPrice: number, atr: number, side: 'buy' | 'sell', riskMode: string): { stopLoss: number, takeProfit: number } {
    const stopMultiplier = SignalGenerator.ATR_STOP_MULTIPLIERS[riskMode] || 1.5;
    const profitMultiplier = SignalGenerator.ATR_PROFIT_MULTIPLIERS[riskMode] || 1.5;

    if (side === 'buy') {
      const stopLoss = entryPrice - (stopMultiplier * atr);
      const takeProfit = entryPrice + (profitMultiplier * atr);
      return { stopLoss, takeProfit };
    } else {
      const stopLoss = entryPrice + (stopMultiplier * atr);
      const takeProfit = entryPrice - (profitMultiplier * atr);
      return { stopLoss, takeProfit };
    }
  }

  // Streaming signal generation
  addToStream(symbol: string, candle: any): void {
    let buffer = this.streamingBuffers.get(symbol);
    if (!buffer) {
      buffer = [];
      this.streamingBuffers.set(symbol, buffer);
    }

    buffer.push(candle);

    // Keep buffer size manageable
    if (buffer.length > this.maxBufferSize) {
      buffer.shift();
    }
  }

  async generateStreamingSignal(
    symbol: string,
    regime: RegimeType,
    useAI: boolean = false,
    strategy: string = 'regime',
    riskMode: string = 'moderate'
  ): Promise<Signal | null> {
    const buffer = this.streamingBuffers.get(symbol);
    if (!buffer || buffer.length < 50) {
      return null; // Need minimum data for indicators
    }

    // Use the most recent data
    return this.generateSignal(buffer, regime, symbol, useAI, strategy, riskMode);
  }

  getStreamingBufferSize(symbol: string): number {
    const buffer = this.streamingBuffers.get(symbol);
    return buffer ? buffer.length : 0;
  }

  clearStreamingBuffer(symbol: string): void {
    this.streamingBuffers.delete(symbol);
  }

  async generateSignal(df: any[], regime: RegimeType, symbol: string, useAI: boolean = false, strategy: string = 'regime', riskMode: string = 'moderate'): Promise<Signal | null> {
    if (df.length < 50) return null;

    let signal: Signal | null = null;

    if (strategy === 'shotgun') {
      signal = this._shotgunStrategy(df, symbol, riskMode);
    } else if (strategy === 'alt_chaser') {
      signal = this._altChaserStrategy(df, symbol, riskMode);
    } else if (strategy === 'chasing_dragons') {
      signal = this._chasingDragonsStrategy(df, symbol, riskMode);
    } else {
      switch (regime) {
        case RegimeType.STRONG_BULL:
          signal = this._strongBullStrategy(df, symbol, riskMode);
          break;
        case RegimeType.WEAK_BULL:
          signal = this._weakBullStrategy(df, symbol, riskMode);
          break;
        case RegimeType.BEAR:
          signal = this._bearStrategy(df, symbol, riskMode);
          break;
        case RegimeType.SIDEWAYS:
          signal = this._sidewaysStrategy(df, symbol, riskMode);
          break;
        default:
          return null;
      }
    }

    if (signal && useAI && SignalGenerator.aiEnabled && !SignalGenerator.aiHealth.circuitBreakerTripped) {
      try {
        const apiKey = process.env.GEMINI_API_KEY;
        if (!apiKey) {
          console.warn("AI Signal Confirmation skipped: GEMINI_API_KEY is not set.");
          SignalGenerator.aiHealth.totalRequests++;
          SignalGenerator.aiHealth.failedConfirmations++;
          SignalGenerator.aiHealth.consecutiveFailures++;
          SignalGenerator.aiHealth.lastFailureReason = 'GEMINI_API_KEY not configured';
          signal.aiWarning = true;
          // Disable AI features when no key is configured
          SignalGenerator.aiEnabled = false;
          if (SignalGenerator.aiHealth.consecutiveFailures >= 3) {
            SignalGenerator.aiHealth.circuitBreakerTripped = true;
            console.error('[AI Circuit Breaker] Tripped due to missing API key');
          }
        } else {
          const { GoogleGenAI } = await import('@google/genai');
          const ai = new GoogleGenAI({ apiKey });

          const lastCandles = df.slice(-5).map(c => ({
            time: new Date(c.time).toISOString(),
            open: c.open,
            high: c.high,
            low: c.low,
            close: c.close,
            volume: c.volume
          }));

          const prompt = `You are a quantitative trading system. A base algorithm has generated a ${signal.side.toUpperCase()} signal for ${symbol} based on ${signal.indicators.join(', ')}.
          Entry: ${signal.entryPrice}, Stop Loss: ${signal.stopLoss}, Take Profit: ${signal.takeProfit}.
          Recent price action: ${JSON.stringify(lastCandles)}

          Do you confirm this trade? If the macro structure looks poor, reject it.
          Return a JSON object:
          { "confirmed": boolean, "reasoning": "string" }`;

          const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
              responseMimeType: "application/json"
            }
          });

          if (response.text) {
            const aiResult = JSON.parse(response.text);
            SignalGenerator.aiHealth.totalRequests++;
            SignalGenerator.aiHealth.successfulConfirmations++;
            SignalGenerator.aiHealth.consecutiveFailures = 0;
            if (!aiResult.confirmed) {
              console.log(`AI rejected signal for ${symbol}: ${aiResult.reasoning}`);
              return null; // Block trade when AI rejects
            } else {
              signal.reasoning = `AI Confirmed: ${aiResult.reasoning}`;
            }
          }
        }
      } catch (e: any) {
        SignalGenerator.aiHealth.totalRequests++;
        SignalGenerator.aiHealth.failedConfirmations++;
        SignalGenerator.aiHealth.consecutiveFailures++;
        SignalGenerator.aiHealth.lastFailureReason = e.message || String(e);

        if (e.message && e.message.includes("API_KEY_INVALID")) {
          console.error("AI Signal Confirmation failed: Invalid API Key. Disabling AI features.");
          SignalGenerator.aiEnabled = false;
          SignalGenerator.aiHealth.circuitBreakerTripped = true;
          return null; // Block trade when AI key is invalid and AI is required
        } else {
          console.error("AI Signal Confirmation failed:", e);
          // Non-critical AI error: add warning flag to signal, allow trade to proceed
          signal.aiWarning = true;
          signal.reasoning += ` [AI Confirmation Failed: ${e.message}]`;

          // Circuit breaker: trip after 5 consecutive failures
          if (SignalGenerator.aiHealth.consecutiveFailures >= 5) {
            SignalGenerator.aiHealth.circuitBreakerTripped = true;
            console.error(`[AI Circuit Breaker] Tripped after ${SignalGenerator.aiHealth.consecutiveFailures} consecutive failures. AI features disabled temporarily.`);
            SignalGenerator.aiEnabled = false;
          }
        }
      }
    }

    return signal;
  }

  _strongBullStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const data = df[df.length - 1];
    let score = 0;
    const indicators: string[] = [];

    // Trend confirmation (45%)
    if (data.close > data.ema_9 && data.ema_9 > data.ema_21) {
      score += 45;
      indicators.push('EMA Trend');
    } else {
      return null; // Trend must be intact
    }

    // RSI Momentum (20%)
    if (data.rsi_14 > 50 && data.rsi_14 < 75) {
      score += 20;
      indicators.push('RSI Momentum');
    } else if (data.rsi_14 >= 75) {
      score += 5;
      indicators.push('RSI Overbought');
    }

    // Volume Confirmation (20%)
    if (data.volume_ratio > 1.2) {
      score += 20;
      indicators.push('Volume Surge');
    }

    // Timing: Stoch RSI (15%)
    if (data.stoch_rsi_k < 30) {
      score += 15;
      indicators.push('StochRSI Oversold');
    } else if (data.stoch_rsi_k < 50) {
      score += 5;
      indicators.push('StochRSI Moderate');
    }

    if (score >= 60) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(data.close, data.atr, 'buy', riskMode);
      return {
        symbol,
        side: 'buy',
        confidence: score,
        entryPrice: data.close,
        stopLoss,
        takeProfit,
        reasoning: `Strong Bull: Score ${score} - ${indicators.join(', ')} (ATR-adjusted)`,
        indicators
      };
    }
    return null;
  }

  _weakBullStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const data = df[df.length - 1];
    let score = 0;
    const indicators: string[] = [];

    // Strategy A: Mean reversion (60% weight)
    if (data.close <= data.bb_lower * 1.01) {
      if (data.close > data.vwap * 0.995) {
        if (data.rsi_14 < 40) {
          score += 60;
          indicators.push('Mean Reversion (BB/VWAP/RSI)');
        }
      }
    }
    // Strategy B: Momentum continuation (40% weight)
    else if (data.close > data.ema_9 && data.ema_9 > data.ema_21) {
      if (data.rsi_14 > 50 && data.rsi_14 < 70) {
        if (data.volume_ratio > 1.3) {
          score += 40;
          indicators.push('Momentum Breakout');
        }
      }
    }

    // Volume confirmation boost
    if (data.close > data.open && data.volume_ratio > 1.1) {
      score += 15;
      indicators.push('Bullish Volume');
    }

    // Penalty: Wrong side of VWAP
    if (data.close < data.vwap * 0.98) {
      score *= 0.7;
    }

    if (score >= 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(data.close, data.atr, 'buy', riskMode);
      return {
        symbol,
        side: 'buy',
        confidence: Math.min(score, 100),
        entryPrice: data.close,
        stopLoss,
        takeProfit,
        reasoning: `Weak Bull: Score ${Math.min(score, 100).toFixed(0)} - ${indicators.join(', ')} (ATR-adjusted)`,
        indicators
      };
    }
    return null;
  }

  _bearStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const data = df[df.length - 1];
    let score = 0;
    const indicators: string[] = [];

    // Must have: Downtrend confirmed
    if (data.ema_9 < data.ema_21) {
      score += 30;
      indicators.push('Downtrend EMA');
    } else {
      return null;
    }

    // Resistance rejection
    if (data.high >= data.bb_upper * 0.995) {
      if (data.close < data.open) {
        if (data.rsi_14 > 60) {
          score += 50;
          indicators.push('Resistance Rejection');
        }
      }
    } else if (data.rsi_14 > 65 && data.rsi_14 < 75) {
      score += 35;
      indicators.push('Failed Rally');
    }

    // MACD confirmation
    if (data.macd_line < data.signal_line) {
      score += 15;
      indicators.push('MACD Bearish');
    }

    if (score >= 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(data.close, data.atr, 'sell', riskMode);
      return {
        symbol,
        side: 'sell',
        confidence: score,
        entryPrice: data.close,
        stopLoss,
        takeProfit,
        reasoning: `Bear: Score ${score} - ${indicators.join(', ')} (ATR-adjusted)`,
        indicators
      };
    }
    return null;
  }

  _sidewaysStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const data = df[df.length - 1];
    let score = 0;
    let side: 'buy' | 'sell' = 'buy';
    const indicators: string[] = [];

    // Long Setup
    if (data.close <= data.bb_lower * 1.005) {
      score += 30;
      indicators.push('BB Lower');
      if (data.rsi_14 < 35) {
        score += 25;
        indicators.push('RSI Oversold');
      }
      if (data.stoch_rsi_k < 25) {
        score += 20;
        indicators.push('Stoch Oversold');
      }
      side = 'buy';
    }
    // Short Setup
    else if (data.close >= data.bb_upper * 0.995) {
      score += 30;
      indicators.push('BB Upper');
      if (data.rsi_14 > 65) {
        score += 25;
        indicators.push('RSI Overbought');
      }
      if (data.stoch_rsi_k > 75) {
        score += 20;
        indicators.push('Stoch Overbought');
      }
      side = 'sell';
    }

    // Volume filter: Reduce if volume spiking
    if (data.volume_ratio > 1.5) {
      score *= 0.5;
      indicators.push('Volume Spike Penalty');
    }

    if (score >= 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(data.close, data.atr, side, riskMode);
      return {
        symbol,
        side,
        confidence: score,
        entryPrice: data.close,
        stopLoss,
        takeProfit,
        reasoning: `Sideways: Score ${score} - ${indicators.join(', ')} (ATR-adjusted)`,
        indicators
      };
    }

    return null;
  }

  _shotgunStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    // Shotgun: Buy/sell 0.5s before candle end, close 10s after.
    // This needs to be triggered at specific times.
    // For now, let's just return a signal if indicators align.
    const last = df[df.length - 1];
    if (last.rsi_14 > 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(last.close, last.atr, 'buy', riskMode);
      return {
        symbol,
        side: 'buy',
        confidence: 60,
        entryPrice: last.close,
        stopLoss,
        takeProfit,
        reasoning: 'Shotgun: Triggered by RSI (ATR-adjusted)',
        indicators: ['RSI']
      };
    }
    return null;
  }

  _altChaserStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const last = df[df.length - 1];
    const prev = df[df.length - 2];
    const change = Math.abs(last.close - prev.close) / prev.close;
    if (change > 0.01) {
      const side = last.close > prev.close ? 'buy' : 'sell';
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(last.close, last.atr, side, riskMode);
      return {
        symbol,
        side,
        confidence: 65,
        entryPrice: last.close,
        stopLoss,
        takeProfit,
        reasoning: 'Alt Chaser: Price change > 1% (ATR-adjusted)',
        indicators: ['Price Action']
      };
    }
    return null;
  }

  _chasingDragonsStrategy(df: any[], symbol: string, riskMode: string): Signal | null {
    const last = df[df.length - 1];
    // Placeholder for probability score logic
    if (last.rsi_14 > 50) {
      const { stopLoss, takeProfit } = this.calculateATRAdjustedLevels(last.close, last.atr, 'buy', riskMode);
      return {
        symbol,
        side: 'buy',
        confidence: 75,
        entryPrice: last.close,
        stopLoss,
        takeProfit,
        reasoning: 'Chasing Dragons: Probability score maintained (ATR-adjusted)',
        indicators: ['RSI']
      };
    }
    return null;
  }
}

import { RiskMode, RiskManager } from '../risk/manager.js';
import { runQuery } from '../database.js';
import { randomUUID } from 'crypto';
import { CostEstimator, OrderRequest, SlippageCircuitBreaker } from '../slippage/index.js';
import { Decimal } from 'decimal.js';

export class ShadowTrader {
  portfolios: Record<RiskMode, { balance: number, initialBalance: number, openTrades: any[] }>;
  riskManager: RiskManager;
  costEstimator?: CostEstimator;
  slippageCircuitBreaker?: SlippageCircuitBreaker;
  private runnerStates: Map<string, { tradeId: string, originalAmount: number, remainingAmount: number, partialExits: number, maxPartialExits: number, lastExitPrice: number, cumulativeExited: number }> = new Map();

  constructor() {
    this.portfolios = {
      [RiskMode.ULTRA_CONSERVATIVE]: { balance: 100000, initialBalance: 100000, openTrades: [] },
      [RiskMode.CONSERVATIVE]: { balance: 100000, initialBalance: 100000, openTrades: [] },
      [RiskMode.MODERATE]: { balance: 100000, initialBalance: 100000, openTrades: [] },
      [RiskMode.AGGRESSIVE]: { balance: 100000, initialBalance: 100000, openTrades: [] },
      [RiskMode.DEGEN]: { balance: 100000, initialBalance: 100000, openTrades: [] },
      [RiskMode.AI_ENHANCED]: { balance: 100000, initialBalance: 100000, openTrades: [] }
    };
    this.riskManager = new RiskManager();
  }

  private async logAuditTrade(
    tradeId: string,
    eventType: string,
    riskMode: string,
    leverage: number,
    symbol: string,
    side: string,
    amount: number,
    price: number,
    exitReason?: string,
    pnl?: number,
    metadata?: any
  ) {
    try {
      const auditId = randomUUID();
      const timestamp = Date.now();
      const metadataJson = metadata ? JSON.stringify(metadata) : null;

      await runQuery(`
        INSERT INTO audit_trades (id, trade_id, event_type, timestamp, risk_mode, leverage, symbol, side, amount, price, exit_reason, pnl, metadata)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `, [auditId, tradeId, eventType, timestamp, riskMode, leverage, symbol, side, amount, price, exitReason || null, pnl || null, metadataJson]);
    } catch (error) {
      console.error(`Failed to log audit trade ${tradeId}:`, error);
      // Don't throw - audit logging shouldn't break trading
    }
  }

  async init() {
    await this.loadState();
  }

  async reset() {
    try {
      await runQuery(`DELETE FROM shadow_trades`);
    } catch (error: any) {
      console.warn('ShadowTrader reset skipped: shadow_trades table unavailable', error?.message || error);
      return;
    }
    for (const mode of Object.values(RiskMode)) {
      this.portfolios[mode as RiskMode] = { balance: 100000, initialBalance: 100000, openTrades: [] };
      console.log(`[ShadowTrader] Resetting ${mode} to 100000`);
    }
  }

  async loadState() {
    for (const mode of Object.values(RiskMode)) {
      let openTrades: any[] = [];
      try {
        openTrades = await runQuery(`
        SELECT * FROM shadow_trades
        WHERE risk_mode = ? AND status = 'open'
      `, [mode], 'all');
      } catch {
        openTrades = [];
      }

      this.portfolios[mode].openTrades = openTrades.map((t: any) => ({
        ...t,
        stopLoss: t.stop_loss,
        takeProfit: t.take_profit
      }));

      let result: any[] = [];
      try {
        result = await runQuery(`
        SELECT SUM(pnl) as totalPnl FROM shadow_trades
        WHERE risk_mode = ? AND status = 'closed'
      `, [mode], 'all');
      } catch {
        result = [];
      }

      const totalPnl = result[0]?.totalPnl || 0;
      this.portfolios[mode].balance = this.portfolios[mode].initialBalance + totalPnl;
    }
  }

  async processSignal(
    signal: any,
    currentPrice: number,
    activeMode?: string,
    balanceManager?: any,
    exchange?: any,
    regime: string = 'uncertain'
  ) {
    for (const mode of Object.values(RiskMode)) {
      const portfolio = this.portfolios[mode];

      const balances = balanceManager ? await balanceManager.getBalances() : null;
      // Use bot balance for limit check
      const effectiveBalance = (mode === activeMode && balances) ? balances.botBalance : portfolio.balance;

      if (mode === activeMode) {
        console.log(`[ShadowTrader] Debug ${mode}: effectiveBalance=${effectiveBalance}, portfolio.balance=${portfolio.balance}, botBalance=${balances?.botBalance}, activeMode=${activeMode}`);
      }

      // Check circuit breakers
      const dailyLoss = 0; // Calculate daily loss from DB
      const haltReason = this.riskManager.checkCircuitBreakers(effectiveBalance, portfolio.initialBalance, dailyLoss, mode);
      if (haltReason) {
        console.log(`Shadow Trader [${mode}]: Halted - ${haltReason}. Effective Balance: ${effectiveBalance}, Initial: ${portfolio.initialBalance}`);
        continue;
      }

      // Validate trade
      if (!this.riskManager.validateTrade(signal, mode, portfolio.openTrades.length, regime)) {
        continue;
      }

      // Calculate position size with dynamic multiplier from MD Part 5.1
      let positionSize = this.riskManager.calculatePositionSize(effectiveBalance, signal.entryPrice, signal.stopLoss, mode as RiskMode, signal.confidence);
      if (positionSize <= 0) continue;

      // Cost estimation and circuit breaker check for active mode
      if (mode === activeMode && this.costEstimator && this.slippageCircuitBreaker) {
        const orderRequest: OrderRequest = {
          symbol: signal.symbol,
          side: signal.side as 'buy' | 'sell',
          size: new Decimal(positionSize),
          type: 'market',
          timeInForce: 'GTC'
        };

        const costEstimate = await this.costEstimator.estimateTotalCost(orderRequest);
        const marketState = {
          timestamp: Date.now(),
          midPrice: new Decimal(signal.entryPrice),
          spread: new Decimal(signal.entryPrice * 0.001), // Mock spread
          volatility: 0.02, // Mock volatility
          depth: {
            bidVolume: new Decimal(1000),
            askVolume: new Decimal(1000),
            bidLevels: 10,
            askLevels: 10,
            totalDepth: new Decimal(2000), // bidVolume + askVolume
            vpin: 0.1
          },
          regime: 'normal' as any
        };

        const breakerAction = this.slippageCircuitBreaker.evaluateBreaker(costEstimate, marketState);

        if (breakerAction.action === 'reject') {
          console.log(`Shadow Trader [${mode}]: Trade rejected by circuit breaker - ${breakerAction.reason}`);
          continue;
        }

        if (breakerAction.action === 'delay') {
          console.log(`Shadow Trader [${mode}]: Trade delayed by circuit breaker - ${breakerAction.reason}`);
          // In production, would implement delay logic
          continue;
        }

        if (breakerAction.action === 'scale_down' && breakerAction.scaleFactor) {
          positionSize *= breakerAction.scaleFactor;
          console.log(`Shadow Trader [${mode}]: Position size scaled down to ${positionSize} - ${breakerAction.reason}`);
        }
      }

      // Adjust TP/SL based on mode config
      const config = this.riskManager.getConfig(mode as RiskMode);

      // Part 5.2: Dynamic Stops (ATR-based)
      // Since we have ATR in candles, let's use it if available
      // For now, using percentage from config as fallback
      const slPct = (config.stopLoss || 2.0) / 100;
      const tpPct = (config.takeProfit || 1.5) / 100;

      const adjustedStopLoss = signal.side === 'buy' 
        ? signal.entryPrice * (1 - slPct)
        : signal.entryPrice * (1 + slPct);
      const adjustedTakeProfit = signal.side === 'buy'
        ? signal.entryPrice * (1 + tpPct)
        : signal.entryPrice * (1 - tpPct);

      // Execute shadow trade
      const trade = {
        id: `shadow-${mode}-${Date.now()}`,
        symbol: signal.symbol,
        side: signal.side,
        amount: positionSize,
        price: currentPrice,
        status: 'open',
        timestamp: Date.now(),
        risk_mode: mode,
        stopLoss: adjustedStopLoss,
        takeProfit: adjustedTakeProfit,
        initialStopLoss: adjustedStopLoss, // Save for trailing logic
        leverage: config.leverage || 1,
        candlesHeld: 0,
        isRunner: false,
        exchangeOrderId: null as string | null
      };

      // Check if trade cost exceeds bot balance for active mode
      const tradeCost = trade.amount * trade.price / trade.leverage;
      if (mode === activeMode && balances && tradeCost > balances.botBalance) {
        console.log(`Shadow Trader [${mode}]: Trade rejected - Insufficient bot balance. Cost: ${tradeCost}, Bot: ${balances.botBalance}`);
        continue;
      }

      if (mode === activeMode && exchange && exchange.apiKey) {
        try {
           const order = await exchange.placeOrder(trade.symbol, trade.side, trade.amount, 'market');
           trade.exchangeOrderId = order.id;
           console.log(`Live order executed for ${trade.symbol} (${trade.side}): ${order.id}`);
        } catch (e: any) {
           console.error(`Failed to execute live order for ${trade.symbol}: ${e.message}`);
           // If live execution fails, we might still want to record the shadow trade, or skip.
           // For now, we'll continue with the shadow trade.
        }
      }

      portfolio.openTrades.push(trade);

      if (mode === activeMode && balanceManager) {
        balanceManager.addActiveTrade(trade.amount * trade.price / trade.leverage);
      }

       // Save to DB
       await runQuery(`
         INSERT INTO shadow_trades (id, symbol, side, amount, price, status, timestamp, risk_mode, leverage, stop_loss, take_profit)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       `, [trade.id, trade.symbol, trade.side, trade.amount, trade.price, trade.status, trade.timestamp, trade.risk_mode, trade.leverage, trade.stopLoss, trade.takeProfit]);

       // Audit log: trade open
       await this.logAuditTrade(
         trade.id,
         'open',
         trade.risk_mode,
         trade.leverage,
         trade.symbol,
         trade.side,
         trade.amount,
         trade.price,
         undefined,
         undefined,
         { stopLoss: trade.stopLoss, takeProfit: trade.takeProfit, confidence: signal.confidence, regime }
       );
    }
  }

  async updatePositions(currentPrice: number, activeMode?: string, balanceManager?: any, exchange?: any, lastCandle: any = null) {
    for (const mode of Object.values(RiskMode)) {
      const portfolio = this.portfolios[mode];
      const newOpenTrades = [];
       const config = this.riskManager.getConfig(mode as RiskMode);
       const maintenanceMargin = 0.005; // 0.5% maintenance margin

       for (const trade of portfolio.openTrades) {
         // Increment candles held if a new candle is provided
         if (lastCandle && (!trade.lastUpdateTime || lastCandle.time > trade.lastUpdateTime)) {
           trade.candlesHeld = (trade.candlesHeld || 0) + 1;
           trade.lastUpdateTime = lastCandle.time;
         }

         console.log(`[ShadowTrader] Checking trade ${trade.id} for ${mode}. Price: ${currentPrice}, SL: ${trade.stopLoss}, TP: ${trade.takeProfit}`);
         let pnl = 0;
         let closed = false;
         let exitReason = '';
         const leverage = trade.leverage || config.leverage || 1;
         const marginUsed = trade.amount * trade.price / leverage;
         const currentNotional = trade.amount * currentPrice;
         const currentMargin = currentNotional / leverage;
         const profitPct = trade.side === 'buy'
           ? (currentPrice - trade.price) / trade.price
           : (trade.price - currentPrice) / trade.price;

         if (trade.side === 'buy') {
           pnl = (currentMargin - marginUsed); // Leveraged PnL based on margin

          // MD Part 2.1: Multi-candle hold & Trailing Stop
          if (config.multiCandleHoldEnabled && profitPct > 0.005) {
            const trailStop = currentPrice * 0.996; // 0.4% trail as per Moderate mode
            if (trailStop > trade.stopLoss) {
              trade.stopLoss = trailStop;
            }
          }

          // Part 2.1: Runner Position Logic
          if (config.runnerEnabled && !trade.isRunner && profitPct >= (config.runnerConditions?.triggerProfit / 100 || 0.015)) {
             console.log(`[ShadowTrader] [${mode}] Runner triggered for ${trade.id}`);
             // Partial exit (close e.g. 60%)
             const exitFactor = config.runnerConditions?.partialExit || 0.6;
             const closeAmount = trade.amount * exitFactor;
             const closeMargin = closeAmount * trade.price / leverage;
             const partialPnl = (currentMargin - marginUsed) * (closeAmount / trade.amount); // Proportional margin PnL

            portfolio.balance += partialPnl;
            trade.amount -= closeAmount;
            trade.isRunner = true;
            // Lock in minimum profit on runner (entry + 0.5%)
            trade.stopLoss = Math.max(trade.stopLoss, trade.price * 1.005);

            if (mode === activeMode && balanceManager) {
              const tradeCost = closeAmount * trade.price / trade.leverage;
              balanceManager.recordTradeResult(partialPnl, tradeCost);
            }

            // Audit log: partial exit
            await this.logAuditTrade(
              trade.id,
              'partial_exit',
              mode,
              trade.leverage,
              trade.symbol,
              trade.side,
              closeAmount,
              currentPrice,
              'runner',
              partialPnl,
              { remainingAmount: trade.amount, totalExited: closeAmount, profitPct }
            );
          }

          // Part 2.1: Early Exit Feature
          if (config.earlyExitEnabled && profitPct >= (config.earlyExitTarget / 100)) {
            closed = true;
            exitReason = 'early_exit';
          }

           // Liquidation Logic
           const lossPct = (marginUsed - currentMargin) / marginUsed; // Percentage of margin lost (same as notional loss %)
           if (lossPct >= (1 / leverage) - maintenanceMargin) { // Liquidation threshold based on leverage
             closed = true;
             exitReason = 'liquidation';
             pnl = -marginUsed; // Total loss of margin
           } else if (currentPrice <= trade.stopLoss) {
             closed = true;
             exitReason = 'stop_loss';
           } else if (currentPrice >= trade.takeProfit && !trade.isRunner) {
             closed = true;
             exitReason = 'take_profit';
           }

          // Multi-candle expiration
          if (config.multiCandleHoldEnabled && trade.candlesHeld >= (config.holdConditions?.maxCandles || 3)) {
            closed = true;
            exitReason = 'multi_candle_expiry';
          }
         } else {
           pnl = (marginUsed - currentMargin); // Leveraged PnL based on margin

           // Trailing Stop Logic for Shorts
          if (config.multiCandleHoldEnabled && profitPct > 0.005) {
            const trailStop = currentPrice * 1.004; // 0.4% trail
            if (trailStop < trade.stopLoss) {
              trade.stopLoss = trailStop;
            }
          }

          // Part 2.1: Early Exit Feature
          if (config.earlyExitEnabled && profitPct >= (config.earlyExitTarget / 100)) {
            closed = true;
            exitReason = 'early_exit';
          }

           // Liquidation Logic
           const lossPct = (marginUsed - currentMargin) / marginUsed; // Percentage of margin lost (same as notional loss %)
           if (lossPct >= (1 / leverage) - maintenanceMargin) { // Liquidation threshold based on leverage
             closed = true;
             exitReason = 'liquidation';
             pnl = -marginUsed; // Total loss of margin
           } else if (currentPrice >= trade.stopLoss) {
             closed = true;
             exitReason = 'stop_loss';
           } else if (currentPrice <= trade.takeProfit && !trade.isRunner) {
             closed = true;
             exitReason = 'take_profit';
           }

          // Multi-candle expiration
          if (config.multiCandleHoldEnabled && trade.candlesHeld >= (config.holdConditions?.maxCandles || 3)) {
            closed = true;
            exitReason = 'multi_candle_expiry';
          }
         }

         if (closed) {
           portfolio.balance += pnl;

           // Record win/loss for circuit breaker tracking
           if (pnl > 0) {
             this.riskManager.recordWin(mode);
           } else {
             this.riskManager.recordLoss(mode);
           }

           if (mode === activeMode && balanceManager) {
             const tradeCost = trade.amount * trade.price / trade.leverage;
             balanceManager.recordTradeResult(pnl, tradeCost);

             if (exchange && exchange.apiKey) {
                try {
                  const closeSide = trade.side === 'buy' ? 'sell' : 'buy';
                  const order = await exchange.placeOrder(trade.symbol, closeSide, trade.amount, 'market');
                  console.log(`Live close order executed for ${trade.symbol} (${closeSide}): ${order.id}`);
                } catch (e: any) {
                  console.error(`Failed to execute live close order for ${trade.symbol}: ${e.message}`);
                }
             }
           }

            // Update DB
            await runQuery(`
              UPDATE shadow_trades
              SET status = 'closed', pnl = ?, exit_price = ?, exit_timestamp = ?
              WHERE id = ?
            `, [pnl, currentPrice, Date.now(), trade.id]);

            // Audit log: trade close
            await this.logAuditTrade(
              trade.id,
              'close',
              mode,
              trade.leverage,
              trade.symbol,
              trade.side,
              trade.amount,
              currentPrice,
              exitReason,
              pnl,
              { candlesHeld: trade.candlesHeld, profitPct, liquidationThreshold: leverage ? 1 / leverage - maintenanceMargin : null }
            );

            console.log(`Shadow Trader [${mode}]: Trade ${trade.id} closed due to ${exitReason}. PnL: ${pnl.toFixed(2)}`);
         } else {
           newOpenTrades.push(trade);
         }
       }

       portfolio.openTrades = newOpenTrades;
     }
   }

    async closeTrade(tradeId: string, currentPrice: number, activeMode?: string, balanceManager?: any, exchange?: any) {
     for (const mode of Object.values(RiskMode)) {
       const portfolio = this.portfolios[mode];
       const tradeIndex = portfolio.openTrades.findIndex(t => t.id === tradeId);

       if (tradeIndex !== -1) {
         const trade = portfolio.openTrades[tradeIndex];
         const leverage = trade.leverage || 1;
         const marginUsed = trade.amount * trade.price / leverage;
         const currentNotional = trade.amount * currentPrice;
         const currentMargin = currentNotional / leverage;
         let pnl = 0;
         if (trade.side === 'buy') {
           pnl = currentMargin - marginUsed;
         } else {
           pnl = marginUsed - currentMargin;
         }

         portfolio.balance += pnl;

         // Record win/loss for circuit breaker tracking
         if (pnl > 0) {
           this.riskManager.recordWin(mode);
         } else {
           this.riskManager.recordLoss(mode);
         }

         if (mode === activeMode && balanceManager) {
           const tradeCost = trade.amount * trade.price / trade.leverage;
           balanceManager.recordTradeResult(pnl, tradeCost);

           if (exchange && exchange.apiKey) {
             try {
               const closeSide = trade.side === 'buy' ? 'sell' : 'buy';
               await exchange.placeOrder(trade.symbol, closeSide, trade.amount, 'market');
             } catch (e: any) {
               console.error(`Failed to execute live close order for ${trade.symbol}: ${e.message}`);
             }
           }
         }

          const result = await runQuery(`
            UPDATE shadow_trades
            SET status = 'closed', pnl = ?, exit_price = ?, exit_timestamp = ?
            WHERE id = ?
          `, [pnl, currentPrice, Date.now(), trade.id]);

          // Audit log: trade close (manual)
          await this.logAuditTrade(
            trade.id,
            'close',
            mode,
            trade.leverage,
            trade.symbol,
            trade.side,
            trade.amount,
            currentPrice,
            'manual_close',
            pnl,
            { candlesHeld: trade.candlesHeld }
          );

          portfolio.openTrades.splice(tradeIndex, 1);
         return true;
       }
     }
     return false;
   }

  async updateTradeParams(tradeId: string, stopLoss: number, takeProfit: number) {
    for (const mode of Object.values(RiskMode)) {
      const portfolio = this.portfolios[mode];
      const trade = portfolio.openTrades.find(t => t.id === tradeId);

      if (trade) {
        trade.stopLoss = stopLoss;
        trade.takeProfit = takeProfit;

        await runQuery(`
          UPDATE shadow_trades
          SET stop_loss = ?, take_profit = ?
          WHERE id = ?
        `, [stopLoss, takeProfit, tradeId]);
        return true;
      }
    }
    return false;
  }

  async getPerformance() {
    const performance: any = {};
    for (const mode of Object.values(RiskMode)) {
      const portfolio = this.portfolios[mode];

      const stats = await runQuery(`
        SELECT COUNT(*) as count, SUM(pnl) as totalPnl
        FROM shadow_trades
        WHERE risk_mode = ? AND status = 'closed'
      `, [mode], 'all');
      const stat = stats[0];

      const wins = await runQuery(`
        SELECT COUNT(*) as count
        FROM shadow_trades
        WHERE risk_mode = ? AND status = 'closed' AND pnl > 0
      `, [mode], 'all');
      const winCount = wins[0].count;

      // Get history
      const closedTrades = await runQuery(`
        SELECT exit_timestamp as time, pnl
        FROM shadow_trades
        WHERE risk_mode = ? AND status = 'closed'
        ORDER BY exit_timestamp ASC
      `, [mode], 'all');

      let currentBalance = portfolio.initialBalance;
      const history = [{ time: Date.now() - 24 * 60 * 60 * 1000, balance: currentBalance }]; // Start 24h ago

      for (const t of closedTrades) {
        currentBalance += t.pnl;
        history.push({ time: t.time, balance: currentBalance });
      }

      // Add current point
      history.push({ time: Date.now(), balance: portfolio.balance });

      const winRate = stat.count > 0 ? winCount / stat.count : 0;
      const totalPnl = stat.totalPnl || 0;
      const roi = ((portfolio.balance - portfolio.initialBalance) / portfolio.initialBalance) * 100;

      performance[mode] = {
        balance: portfolio.balance,
        roi: roi,
        winRate: winRate * 100,
        tradesCount: stat.count,
        totalPnl: totalPnl,
        history: history
      };
    }
    return performance;
  }
}

