export class RiskManager {
  RISK_CONFIGS: Record<string, any>;
  private consecutiveLosses: Record<string, number>;
  private consecutiveWins: Record<string, number>;
  private originalPositionSizes: Record<string, number>;

  constructor() {
    this.RISK_CONFIGS = JSON.parse(JSON.stringify(DEFAULT_RISK_CONFIGS));
    this.consecutiveLosses = {};
    this.consecutiveWins = {};
    this.originalPositionSizes = {};
    // Initialize original position sizes for each mode
    for (const mode of Object.values(RiskMode)) {
      this.originalPositionSizes[mode] = this.RISK_CONFIGS[mode].positionSize;
    }
  }

  private async logSystemEvent(eventType: string, message: string, metadata?: any) {
    try {
      const auditId = randomUUID();
      const timestamp = Date.now();
      const metadataJson = metadata ? JSON.stringify(metadata) : null;

      await runQuery(`
        INSERT INTO audit_system_events (id, event_type, message, timestamp, severity, metadata)
        VALUES (?, ?, ?, ?, ?, ?)
      `, [auditId, eventType, message, timestamp, 'info', metadataJson]);
    } catch (error) {
      logger.error('Failed to log system event', { error: error.message });
    }
  }

  async init() {
    await this.loadConfigs();
  }

  async loadConfigs() {
    try {
      const rows = await runQuery(`SELECT value FROM settings WHERE key = 'risk_configs'`, [], 'all');
      const row = rows[0];
      if (row && row.value) {
        const savedConfigs = JSON.parse(row.value);
        this.RISK_CONFIGS = { ...this.RISK_CONFIGS, ...savedConfigs };
      }
      // Re-initialize original position sizes after loading
      for (const mode of Object.values(RiskMode)) {
        this.originalPositionSizes[mode] = this.RISK_CONFIGS[mode].positionSize;
      }
    } catch (e) {
      console.error('Failed to load risk configs:', e);
    }
  }

  async saveConfigs(configs: any) {
    try {
      await runQuery(`INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)`, ['risk_configs', JSON.stringify(configs)]);
      this.RISK_CONFIGS = { ...this.RISK_CONFIGS, ...configs };
    } catch (e) {
      console.error('Failed to save risk configs:', e);
    }
  }

  getConfig(mode: RiskMode) {
    return this.RISK_CONFIGS[mode];
  }

  getConsecutiveLosses(mode: RiskMode): number {
    return this.consecutiveLosses[mode] || 0;
  }

  recordLoss(mode: RiskMode) {
    const current = this.consecutiveLosses[mode] || 0;
    this.consecutiveLosses[mode] = current + 1;
    this.applyCircuitBreaker(mode);
  }

  recordWin(mode: RiskMode) {
    this.consecutiveLosses[mode] = 0;
    const currentWins = (this.consecutiveWins[mode] || 0) + 1;
    this.consecutiveWins[mode] = currentWins;

    // Gradual recovery after multiple wins
    const RECOVERY_WINS = 3;
    if (currentWins >= RECOVERY_WINS) {
      this.resetPositionSize(mode);
      this.consecutiveWins[mode] = 0;
    } else {
      // Partial recovery - restore some position size
      this.partialRecovery(mode, currentWins);
    }
  }

  private partialRecovery(mode: RiskMode, wins: number) {
    const originalSize = this.originalPositionSizes[mode];
    const config = this.RISK_CONFIGS[mode];
    const losses = this.consecutiveLosses[mode] || 0;

    if (losses >= 7) {
      // After 7+ losses, gradual recovery from 25% towards original
      const recoveryFactor = 0.25 + (wins * 0.25);
      config.positionSize = Math.min(originalSize, originalSize * recoveryFactor);
    } else if (losses >= 5) {
      // After 5-6 losses, gradual recovery from 50% towards original
      const recoveryFactor = 0.5 + (wins * 0.25);
      config.positionSize = Math.min(originalSize, originalSize * recoveryFactor);
    }

    if (config.positionSize !== originalSize && wins <= 3) {
      logger.info(`[RiskManager] Circuit breaker: Position size for ${mode} recovering to ${(config.positionSize * 100).toFixed(1)}% after ${wins} win(s)`);
    }
  }

  private applyCircuitBreaker(mode: RiskMode) {
    const losses = this.consecutiveLosses[mode] || 0;
    const config = this.RISK_CONFIGS[mode];
    const originalSize = this.originalPositionSizes[mode];

    if (losses >= 5) {
      // Reduce position size by 50%
      const reducedSize = originalSize * 0.5;
      if (config.positionSize !== reducedSize) {
        config.positionSize = reducedSize;
        console.log(`[RiskManager] Circuit breaker: Position size for ${mode} reduced to ${(reducedSize * 100).toFixed(1)}% due to ${losses} consecutive losses`);
      }
    }
    if (losses >= 7) {
      // Further reduce to 25% of original
      const furtherReducedSize = originalSize * 0.25;
      if (config.positionSize !== furtherReducedSize) {
        config.positionSize = furtherReducedSize;
        console.log(`[RiskManager] Circuit breaker: Position size for ${mode} further reduced to ${(furtherReducedSize * 100).toFixed(1)}% due to ${losses} consecutive losses`);
      }
    }
  }

  private resetPositionSize(mode: RiskMode) {
    const originalSize = this.originalPositionSizes[mode];
    const config = this.RISK_CONFIGS[mode];
    if (config.positionSize !== originalSize) {
      config.positionSize = originalSize;
      logger.info(`[RiskManager] Circuit breaker: Position size for ${mode} reset to ${(originalSize * 100).toFixed(1)}% after winning trade`);
    }
  }

  async calculateKellyPositionSize(balance: number, riskMode: RiskMode, regime: string): Promise<number> {
    try {
      // Fetch historical performance for win rate and win/loss ratio calculation
      const thirtyDaysAgo = Date.now() - 30 * 24 * 60 * 60 * 1000;
      const historicalTrades = await runQuery(`
        SELECT pnl FROM shadow_trades
        WHERE timestamp > ? AND risk_mode = ? AND regime = ? AND status = 'closed'
        ORDER BY timestamp DESC LIMIT 100
      `, [thirtyDaysAgo, riskMode, regime], 'all');

      if (historicalTrades.length < 10) {
        // Not enough data, fall back to config
        return this.RISK_CONFIGS[riskMode].positionSize;
      }

      const wins = historicalTrades.filter((t: any) => t.pnl > 0);
      const losses = historicalTrades.filter((t: any) => t.pnl < 0);

      const p = wins.length / historicalTrades.length; // Win probability
      const q = 1 - p; // Loss probability

      if (p <= 0 || p >= 1) return this.RISK_CONFIGS[riskMode].positionSize;

      // Calculate average win and loss ratios
      const avgWin = wins.reduce((sum: number, t: any) => sum + Math.abs(t.pnl), 0) / wins.length;
      const avgLoss = losses.reduce((sum: number, t: any) => sum + Math.abs(t.pnl), 0) / losses.length;

      const b = avgWin / avgLoss; // Odds ratio (average win / average loss)

      // Kelly Criterion: f = (bp - q)/b
      const kellyFraction = (b * p - q) / b;

      // Apply bounds and safety factor
      const boundedKelly = Math.max(0.01, Math.min(0.25, kellyFraction * 0.5)); // Half-Kelly for safety

      return boundedKelly;
    } catch (error) {
      logger.error('Failed to calculate Kelly position size', { error: error.message, riskMode, regime });
      return this.RISK_CONFIGS[riskMode].positionSize; // Fallback
    }
  }

  calculatePositionSize(balance: number, entryPrice: number, stopLoss: number, riskMode: RiskMode, confidence: number = 75, regime: string = ''): number {
    const config = this.RISK_CONFIGS[riskMode];

    // Base position size from config (may be adjusted by circuit breaker)
    let baseSize = config.positionSize || 0.02;

    // MD Part 5.1: Dynamic Position Sizing with confidence multiplier
    const confidenceMultiplier = 1.0 + (confidence - 75) / 100;
    const clippedMultiplier = Math.max(0.7, Math.min(1.2, confidenceMultiplier));

    const finalPct = baseSize * clippedMultiplier;
    const amountInCurrency = balance * finalPct;

    const leverage = config.leverage || 1;
    const positionSize = (amountInCurrency * leverage) / entryPrice;

    return positionSize;
  }

  validateTrade(signal: any, riskMode: RiskMode, currentPositions: number, regime: string): boolean {
    const config = this.RISK_CONFIGS[riskMode];

    if (signal.confidence < config.confidenceThreshold) return false;
    if (currentPositions >= config.maxConcurrentPositions) return false;

    // Enforce active regimes from MD
    if (config.activeRegimes && !config.activeRegimes.includes(regime)) {
      return false;
    }

    return true;
  }

  checkCircuitBreakers(balance: number, initialBalance: number, dailyLoss: number, riskMode: RiskMode, consecutiveLosses: number = 0, currentAtr: number = 0, avgAtr: number = 0): string | null {
    const config = this.RISK_CONFIGS[riskMode];

    const currentDrawdown = (initialBalance - balance) / initialBalance;
    if (currentDrawdown >= config.maxDrawdown) {
      const reason = `Max drawdown reached: ${(currentDrawdown * 100).toFixed(2)}% >= ${(config.maxDrawdown * 100).toFixed(2)}%`;
      this.logSystemEvent('circuit_breaker', reason, { riskMode, balance, initialBalance, currentDrawdown, maxDrawdown: config.maxDrawdown });
      return reason;
    }

    if (dailyLoss >= initialBalance * (config.maxDailyLoss || 0.05)) {
      const reason = `Max daily loss reached: $${dailyLoss.toFixed(2)} (Limit: ${(config.maxDailyLoss * 100).toFixed(1)}%)`;
      this.logSystemEvent('circuit_breaker', reason, { riskMode, dailyLoss, maxDailyLoss: config.maxDailyLoss, initialBalance });
      return reason;
    }

    // MD Part 5.3: Consecutive Losses - track and reduce position size
    const currentLosses = consecutiveLosses > 0 ? consecutiveLosses : (this.consecutiveLosses[riskMode] || 0);
    if (currentLosses >= 5) {
      const reason = currentLosses >= 7
        ? `Extreme consecutive losses: ${currentLosses}. Position size reduced to 25%`
        : `High consecutive losses: ${currentLosses}. Position size reduced to 50%`;
      this.logSystemEvent('circuit_breaker', reason, { riskMode, consecutiveLosses: currentLosses });
      return reason;
    }

    // MD Part 5.3: Volatility Spike
    if (avgAtr > 0 && currentAtr > avgAtr * 3) {
      const reason = `Volatility spike detected: ATR ${currentAtr.toFixed(2)} > 3x Avg (${avgAtr.toFixed(2)})`;
      this.logSystemEvent('circuit_breaker', reason, { riskMode, currentAtr, avgAtr });
      return reason;
    }

    return null;
  }
}

import { runQuery } from '../database.js';
import { randomUUID } from 'crypto';

export interface Balances {
  mainBalance: number;
  botBalance: number;
  activeTradeBalance: number;
  totalPnl: number;
  totalPnlPct: number;
}

export class BalanceManager {
  constructor() {}

  private async logAuditBalance(
    eventType: string,
    beforeBalances: Balances,
    afterBalances: Balances,
    changeAmount: number,
    reason: string,
    metadata?: any
  ) {
    try {
      const auditId = randomUUID();
      const timestamp = Date.now();
      const metadataJson = metadata ? JSON.stringify(metadata) : null;

      await runQuery(`
        INSERT INTO audit_balances (
          id, balance_id, event_type, timestamp,
          before_main_balance, before_bot_balance, before_active_balance,
          after_main_balance, after_bot_balance, after_active_balance,
          change_amount, reason, metadata
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `, [
        auditId, 'default', eventType, timestamp,
        beforeBalances.mainBalance, beforeBalances.botBalance, beforeBalances.activeTradeBalance,
        afterBalances.mainBalance, afterBalances.botBalance, afterBalances.activeTradeBalance,
        changeAmount, reason, metadataJson
      ]);
    } catch (error) {
      console.error('Failed to log audit balance:', error);
      // Don't throw - audit logging shouldn't break balance operations
    }
  }

  async getBalances(): Promise<Balances> {
    const rows = await runQuery('SELECT * FROM balances WHERE id = ?', ['default'], 'all');
    const row = rows[0];
    const b = {
      mainBalance: row.main_balance,
      botBalance: row.bot_balance,
      activeTradeBalance: row.active_trade_balance,
      totalPnl: row.total_pnl,
      totalPnlPct: row.total_pnl_pct
    };
    console.log(`[BalanceManager] getBalances: botBalance=${b.botBalance}`);
    return b;
  }

  async updateBalances(balances: Partial<Balances>) {
    const current = await this.getBalances();
    const updated = { ...current, ...balances };

    await runQuery(`
      UPDATE balances 
      SET main_balance = ?, bot_balance = ?, active_trade_balance = ?, total_pnl = ?, total_pnl_pct = ?
      WHERE id = 'default'
    `, [
      updated.mainBalance,
      updated.botBalance,
      updated.activeTradeBalance,
      updated.totalPnl,
      updated.totalPnlPct
    ]);
  }

  async allocateToBot(amount: number) {
    const current = await this.getBalances();
    if (amount > current.mainBalance) throw new Error('Insufficient main balance');

    const updated = {
      mainBalance: current.mainBalance - amount,
      botBalance: current.botBalance + amount,
      activeTradeBalance: current.activeTradeBalance,
      totalPnl: current.totalPnl,
      totalPnlPct: current.totalPnlPct
    };

    await this.updateBalances(updated);

    // Audit log
    await this.logAuditBalance('allocation', current, updated, amount, 'allocate_to_bot');
  }

  async withdrawFromBot(amount: number) {
    const current = await this.getBalances();
    if (amount > current.botBalance) throw new Error('Insufficient bot balance');

    const updated = {
      mainBalance: current.mainBalance + amount,
      botBalance: current.botBalance - amount,
      activeTradeBalance: current.activeTradeBalance,
      totalPnl: current.totalPnl,
      totalPnlPct: current.totalPnlPct
    };

    await this.updateBalances(updated);

    // Audit log
    await this.logAuditBalance('withdrawal', current, updated, amount, 'withdraw_from_bot');
  }

  async halfBotBalance() {
    const current = await this.getBalances();
    const amount = current.botBalance / 2;
    await this.withdrawFromBot(amount);
  }

  async doubleBotBalance() {
    const current = await this.getBalances();
    await this.allocateToBot(current.botBalance);
  }

  async updateActiveTradeBalance(amount: number) {
    const current = await this.getBalances();
    await this.updateBalances({
      activeTradeBalance: current.activeTradeBalance + amount
    });
  }

  async recordTradeResult(pnl: number, tradeValue: number) {
    const current = await this.getBalances();
    // Return the initial trade value to bot balance, plus/minus the pnl
    const newBotBalance = current.botBalance + tradeValue + pnl;
    const newActiveTradeBalance = Math.max(0, current.activeTradeBalance - tradeValue);
    const newTotalPnl = current.totalPnl + pnl;

    // Calculate PnL % based on the total balance
    const totalBalance = current.mainBalance + current.botBalance;
    const newTotalPnlPct = totalBalance > 0 ? (newTotalPnl / totalBalance) * 100 : 0;

    const updated = {
      mainBalance: current.mainBalance,
      botBalance: newBotBalance,
      activeTradeBalance: newActiveTradeBalance,
      totalPnl: newTotalPnl,
      totalPnlPct: newTotalPnlPct
    };

    await this.updateBalances(updated);

    // Audit log
    await this.logAuditBalance('pnl_adjustment', current, updated, pnl, 'trade_result', { tradeValue });
  }

  async addActiveTrade(tradeValue: number) {
    const current = await this.getBalances();
    // Deduct trade value from bot balance and move to active trade balance
    const updated = {
      mainBalance: current.mainBalance,
      botBalance: current.botBalance - tradeValue,
      activeTradeBalance: current.activeTradeBalance + tradeValue,
      totalPnl: current.totalPnl,
      totalPnlPct: current.totalPnlPct
    };

    await this.updateBalances(updated);

    // Audit log
    await this.logAuditBalance('active_trade_addition', current, updated, tradeValue, 'add_active_trade');
  }
}

import axios from 'axios';
import { logger } from '../logging/logger.js';
import { runQuery } from '../database.js';

export interface MarketData {
  market_cap: number;
  total_volume: number;
  fear_greed_index: number;
  fear_greed_value: string;
  btc_dominance: number;
  last_updated: number;
}

export interface MarketNews {
  id: string;
  title: string;
  url: string;
  source: string;
  timestamp: number;
  sentiment?: string;
  sentiment_score?: number;
}

export class MarketDataService {
  private cgApiKey: string;
  private baseUrl = 'https://api.coingecko.com/api/v3';
  private marketDataFailures = 0;
  private newsFailures = 0;
  private marketDataCircuitOpenUntil = 0;
  private newsCircuitOpenUntil = 0;
  private readonly failureThreshold = 3;
  private readonly cooldownMs = 5 * 60 * 1000;
  private metrics = {
    marketDataFetchCount: 0,
    marketDataFetchFailures: 0,
    newsFetchCount: 0,
    newsFetchFailures: 0,
    lastMarketDataFetchAt: 0,
    lastNewsFetchAt: 0
  };

  constructor(cgApiKey: string = process.env.COINGECKO_API_KEY || '') {
    this.cgApiKey = cgApiKey;
  }

  private getUrl(endpoint: string) {
    return `${this.baseUrl}${endpoint}${endpoint.includes('?') ? '&' : '?'}x_cg_demo_api_key=${this.cgApiKey}`;
  }

  async fetchMarketData(): Promise<MarketData | null> {
    this.metrics.marketDataFetchCount++;
    this.metrics.lastMarketDataFetchAt = Date.now();
    if (Date.now() < this.marketDataCircuitOpenUntil) {
      logger.warn('Market-data circuit open; returning cached data', { service: 'MarketDataService' });
      return this.getLatestMarketData();
    }

    try {
      // 1. Fetch Global Data from CoinGecko
      const globalResponse = await axios.get(this.getUrl('/global'));
      const globalData = globalResponse.data.data;

      // 2. Fetch Fear & Greed Index from alternative.me
      const fgResponse = await axios.get('https://api.alternative.me/fng/');
      const fgData = fgResponse.data.data[0];

      const marketData: MarketData = {
        market_cap: globalData.total_market_cap.usd,
        total_volume: globalData.total_volume.usd,
        fear_greed_index: parseInt(fgData.value),
        fear_greed_value: fgData.value_classification,
        btc_dominance: globalData.market_cap_percentage.btc,
        last_updated: Date.now()
      };

      await this.saveMarketData(marketData);
      this.marketDataFailures = 0;
      return marketData;
    } catch (error) {
      this.marketDataFailures++;
      this.metrics.marketDataFetchFailures++;
      if (this.marketDataFailures >= this.failureThreshold) {
        this.marketDataCircuitOpenUntil = Date.now() + this.cooldownMs;
      }
      logger.error('Error fetching market data', { service: 'MarketDataService', error: (error as Error).message });
      return this.getLatestMarketData();
    }
  }

  async fetchNews(): Promise<MarketNews[]> {
    this.metrics.newsFetchCount++;
    this.metrics.lastNewsFetchAt = Date.now();
    if (Date.now() < this.newsCircuitOpenUntil) {
      logger.warn('News circuit open; returning cached data', { service: 'MarketDataService' });
      return this.getLatestNews();
    }

    try {
      let newsItems = [];
      try {
        const response = await axios.get(this.getUrl('/news'));
        newsItems = response.data.data || response.data || [];
      } catch (e) {
        logger.warn('CoinGecko news failed, trying CryptoCompare fallback', { service: 'MarketDataService' });
        const fallbackRes = await axios.get('https://min-api.cryptocompare.com/data/v2/news/?lang=EN');
        newsItems = fallbackRes.data.Data || [];
      }

      if (!Array.isArray(newsItems)) {
        logger.warn('News items is not an array', { service: 'MarketDataService' });
        return [];
      }

      const news: MarketNews[] = newsItems.map((item: any) => ({
        id: String(item.id || item.guid || Math.random().toString(36).substr(2, 9)),
        title: item.title || 'No Title',
        url: item.url || '#',
        source: item.source_info?.name || item.author || 'CryptoNews',
        timestamp: (item.published_on || (item.updated_at ? new Date(item.updated_at).getTime() / 1000 : Date.now() / 1000)) * 1000
      }));

      await this.saveNews(news);
      this.newsFailures = 0;
      return news;
    } catch (error) {
      this.newsFailures++;
      this.metrics.newsFetchFailures++;
      if (this.newsFailures >= this.failureThreshold) {
        this.newsCircuitOpenUntil = Date.now() + this.cooldownMs;
      }
      logger.error('Error fetching news', { service: 'MarketDataService', error: (error as Error).message });
      return this.getLatestNews();
    }
  }

  private async saveMarketData(data: MarketData) {
    await runQuery(`
      INSERT OR REPLACE INTO market_data (id, market_cap, total_volume, fear_greed_index, fear_greed_value, btc_dominance, last_updated)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `, ['current', data.market_cap, data.total_volume, data.fear_greed_index, data.fear_greed_value, data.btc_dominance, data.last_updated]);
  }

  private async saveNews(news: MarketNews[]) {
    for (const item of news) {
      await runQuery(`
        INSERT OR IGNORE INTO market_news (id, title, url, source, timestamp)
        VALUES (?, ?, ?, ?, ?)
      `, [item.id, item.title, item.url, item.source, item.timestamp]);
    }
  }

  async getLatestMarketData(): Promise<MarketData | null> {
    const result = await runQuery('SELECT * FROM market_data WHERE id = ?', ['current'], 'all');
    return result.length > 0 ? result[0] : null;
  }

  async getLatestNews(limit: number = 10): Promise<MarketNews[]> {
    return await runQuery('SELECT * FROM market_news ORDER BY timestamp DESC LIMIT ?', [limit], 'all');
  }

  getMetrics() {
    return {
      ...this.metrics,
      marketDataCircuitOpen: Date.now() < this.marketDataCircuitOpenUntil,
      newsCircuitOpen: Date.now() < this.newsCircuitOpenUntil,
      marketDataCircuitOpenUntil: this.marketDataCircuitOpenUntil,
      newsCircuitOpenUntil: this.newsCircuitOpenUntil
    };
  }
}

import { runQuery } from '../database.js';
import { RiskMode, RiskManager } from '../risk/manager.js';
import { GoogleGenAI, Type } from '@google/genai';

type QueryFn = (query: string, params?: any[], mode?: 'all' | 'get' | 'run') => Promise<any>;
type AiClientFactory = (apiKey: string) => {
  models: {
    generateContent: (input: any) => Promise<{ text?: string | null }>;
  };
};

export class OptimizationEngine {
  private riskManager: RiskManager;
  private isOptimizing: boolean = false;
  private queryFn: QueryFn;
  private aiClientFactory: AiClientFactory;
  private optimizationTrials: Array<{ params: number[], score: number }> = [];

  constructor(
    riskManager: RiskManager,
    deps: {
      queryFn?: QueryFn;
      aiClientFactory?: AiClientFactory;
    } = {}
  ) {
    this.riskManager = riskManager;
    this.queryFn = deps.queryFn || runQuery;
    this.aiClientFactory = deps.aiClientFactory || ((apiKey: string) => new GoogleGenAI({ apiKey }) as any);
  }

  async bayesianOptimize(regime: string): Promise<any> {
    // Simplified optimization: Grid search with random sampling
    const paramBounds = {
      stopLoss: [0.005, 0.05], // 0.5% to 5%
      takeProfit: [0.01, 0.1],  // 1% to 10%
      confidenceThreshold: [0.6, 0.9], // 60% to 90%
      leverage: [1, 5] // 1x to 5x
    };

    let bestParams: number[] = [];
    let bestScore = -Infinity;

    // Random search over parameter space
    for (let i = 0; i < 20; i++) {
      const params = [
        Math.random() * (paramBounds.stopLoss[1] - paramBounds.stopLoss[0]) + paramBounds.stopLoss[0],
        Math.random() * (paramBounds.takeProfit[1] - paramBounds.takeProfit[0]) + paramBounds.takeProfit[0],
        Math.random() * (paramBounds.confidenceThreshold[1] - paramBounds.confidenceThreshold[0]) + paramBounds.confidenceThreshold[0],
        Math.random() * (paramBounds.leverage[1] - paramBounds.leverage[0]) + paramBounds.leverage[0]
      ];

      const score = await this.evaluateParameters(regime, params);

      if (score > bestScore) {
        bestScore = score;
        bestParams = params;
      }
    }

    return {
      stopLoss: bestParams[0],
      takeProfit: bestParams[1],
      confidenceThreshold: bestParams[2],
      leverage: bestParams[3]
    };
  }

  private async evaluateParameters(regime: string, params: number[]): Promise<number> {
    // Simulate evaluation - in practice, this would run backtests or live evaluation
    const [stopLoss, takeProfit, confidenceThreshold, leverage] = params;

    // Fetch recent performance data
    const sevenDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
    const recentTrades = await this.queryFn(`
      SELECT pnl, confidence FROM shadow_trades
      WHERE timestamp > ? AND regime = ? AND status = 'closed'
    `, [sevenDaysAgo, regime], 'all');

    if (recentTrades.length === 0) return 0;

    // Calculate Sharpe-like ratio with parameter adjustments
    let totalPnL = 0;
    let totalVariance = 0;
    for (const trade of recentTrades) {
      if (trade.confidence >= confidenceThreshold) {
        const adjustedPnL = trade.pnl * (1 + (leverage - 1) * 0.1); // Simplified leverage effect
        totalPnL += adjustedPnL;
        totalVariance += adjustedPnL * adjustedPnL;
      }
    }

    const meanReturn = totalPnL / recentTrades.length;
    const variance = totalVariance / recentTrades.length - meanReturn * meanReturn;
    const sharpe = variance > 0 ? meanReturn / Math.sqrt(variance) : 0;

    return sharpe;
  }

  async optimize(regime: string) {
    if (this.isOptimizing) return;
    this.isOptimizing = true;
    console.log(`Starting Bayesian optimization for regime: ${regime}`);

    try {
      const currentConfigs = this.riskManager.RISK_CONFIGS;

      // Use Bayesian optimization for each risk mode
      const optimizedConfigs = { ...currentConfigs };

      for (const mode of Object.keys(currentConfigs)) {
        console.log(`Optimizing parameters for ${mode} mode...`);
        const optimalParams = await this.bayesianOptimize(regime);

        // Apply Bayesian optimization results with smoothing
        for (const [key, val] of Object.entries(optimalParams)) {
          const currentVal = currentConfigs[mode][key];
          if (typeof currentVal === 'number' && typeof val === 'number') {
            optimizedConfigs[mode][key] = Number((val * 0.8 + currentVal * 0.2).toFixed(4));
          }
        }

        // Store optimization trial in database
        await this.storeOptimizationTrial(regime, mode, optimalParams, 0); // score placeholder
      }

      await this.riskManager.saveConfigs(optimizedConfigs);
      console.log("Bayesian optimization complete. New configs saved.");

      // Run Monte Carlo validation
      await this.validateWithMonteCarlo(regime, optimizedConfigs);

    } catch (error) {
      console.error("Bayesian optimization failed:", error);
    } finally {
      this.isOptimizing = false;
    }
  }

  private async storeOptimizationTrial(regime: string, mode: string, params: any, score: number) {
    await this.queryFn(`
      INSERT INTO optimization_trials (regime, mode, params, score, timestamp)
      VALUES (?, ?, ?, ?, ?)
    `, [regime, mode, JSON.stringify(params), score, Date.now()]);
  }

  private async validateWithMonteCarlo(regime: string, configs: any) {
    // Placeholder for Monte Carlo validation - implement in next step
    console.log("Running Monte Carlo validation on optimized configs...");
  }
}

