export class NodeUploader implements Uploader {
  async stat(file: string | Blob): Promise<FileStat> {
    const fileStat: FileStat = {size: 0, type: undefined};
    if (typeof file === 'string') {
      const originalStat = await fs.stat(file);
      fileStat.size = originalStat.size;
      fileStat.type = this.inferMimeType(file);
      return fileStat;
    } else {
      return await getBlobStat(file);
    }
  }

  async upload(
    file: string | Blob,
    uploadUrl: string,
    apiClient: ApiClient,
    httpOptions?: HttpOptions,
  ): Promise<File> {
    if (typeof file === 'string') {
      return await this.uploadFileFromPath(
        file,
        uploadUrl,
        apiClient,
        httpOptions,
      );
    } else {
      return uploadBlob(file, uploadUrl, apiClient, httpOptions);
    }
  }

  async uploadToFileSearchStore(
    file: string | Blob,
    uploadUrl: string,
    apiClient: ApiClient,
    httpOptions?: HttpOptions,
  ): Promise<UploadToFileSearchStoreOperation> {
    if (typeof file === 'string') {
      return await this.uploadFileToFileSearchStoreFromPath(
        file,
        uploadUrl,
        apiClient,
        httpOptions,
      );
    } else {
      return uploadBlobToFileSearchStore(
        file,
        uploadUrl,
        apiClient,
        httpOptions,
      );
    }
  }

