  private async uploadFileFromPath(
    file: string,
    uploadUrl: string,
    apiClient: ApiClient,
    httpOptions?: HttpOptions,
  ): Promise<File> {
    const response = await this.uploadFileFromPathInternal(
      file,
      uploadUrl,
      apiClient,
      httpOptions,
    );
    const responseJson = (await response?.json()) as Record<
      string,
      File | unknown
    >;
    if (response?.headers?.[X_GOOG_UPLOAD_STATUS_HEADER_FIELD] !== 'final') {
      throw new Error('Failed to upload file: Upload status is not finalized.');
    }
    return responseJson['file'] as File;
  }

  private async uploadFileToFileSearchStoreFromPath(
    file: string,
    uploadUrl: string,
    apiClient: ApiClient,
    httpOptions?: HttpOptions,
  ): Promise<UploadToFileSearchStoreOperation> {
    const response = await this.uploadFileFromPathInternal(
      file,
      uploadUrl,
      apiClient,
      httpOptions,
    );
    const responseJson =
      (await response?.json()) as UploadToFileSearchStoreOperation;
    if (response?.headers?.[X_GOOG_UPLOAD_STATUS_HEADER_FIELD] !== 'final') {
      throw new Error('Failed to upload file: Upload status is not finalized.');
    }
    const resp =
      _converters.uploadToFileSearchStoreOperationFromMldev(responseJson);
    const typedResp = new UploadToFileSearchStoreOperation();
    Object.assign(typedResp, resp);
    return typedResp;
  }

  private async uploadFileFromPathInternal(
    file: string,
    uploadUrl: string,
    apiClient: ApiClient,
    httpOptions?: HttpOptions,
  ): Promise<HttpResponse> {
    let finalUrl = uploadUrl;
    const effectiveBaseUrl =
      httpOptions?.baseUrl || apiClient.clientOptions.httpOptions?.baseUrl;
    if (effectiveBaseUrl) {
      const baseUri = new URL(effectiveBaseUrl);
      const uploadUri = new URL(uploadUrl);
      uploadUri.protocol = baseUri.protocol;
      uploadUri.host = baseUri.host;
      uploadUri.port = baseUri.port;
      finalUrl = uploadUri.toString();
    }

    let fileSize = 0;
    let offset = 0;
    let response: HttpResponse = new HttpResponse(new Response());
    let uploadCommand = 'upload';
    let fileHandle: fs.FileHandle | undefined;
    const fileName = path.basename(file);
    try {
      fileHandle = await fs.open(file, 'r');
      if (!fileHandle) {
        throw new Error(`Failed to open file`);
      }
      fileSize = (await fileHandle.stat()).size;
      while (offset < fileSize) {
        const chunkSize = Math.min(MAX_CHUNK_SIZE, fileSize - offset);
        if (offset + chunkSize >= fileSize) {
          uploadCommand += ', finalize';
        }
        const buffer = new Uint8Array(chunkSize);
        const {bytesRead: bytesRead} = await fileHandle.read(
          buffer,
          0,
          chunkSize,
          offset,
        );

        if (bytesRead !== chunkSize) {
          throw new Error(
            `Failed to read ${chunkSize} bytes from file at offset ${
              offset
            }. bytes actually read: ${bytesRead}`,
          );
        }

        const chunk = new Blob([buffer]);
        let retryCount = 0;
        let currentDelayMs = INITIAL_RETRY_DELAY_MS;
        while (retryCount < MAX_RETRY_COUNT) {
          const mergedHeaders = {
            ...(httpOptions?.headers || {}),
            'X-Goog-Upload-Command': uploadCommand,
            'X-Goog-Upload-Offset': String(offset),
            'Content-Length': String(bytesRead),
            'X-Goog-Upload-File-Name': fileName,
          };

          response = await apiClient.request({
            path: '',
            body: chunk,
            httpMethod: 'POST',
            httpOptions: {
              ...httpOptions,
              apiVersion: '',
              baseUrl: finalUrl,
              headers: mergedHeaders,
            },
          });
          if (response?.headers?.[X_GOOG_UPLOAD_STATUS_HEADER_FIELD]) {
            break;
          }
          retryCount++;
          await sleep(currentDelayMs);
          currentDelayMs = currentDelayMs * DELAY_MULTIPLIER;
        }
        offset += bytesRead;
        // The `x-goog-upload-status` header field can be `active`, `final` and
        //`cancelled` in resposne.
        if (
          response?.headers?.[X_GOOG_UPLOAD_STATUS_HEADER_FIELD] !== 'active'
        ) {
          break;
        }
        if (fileSize <= offset) {
          throw new Error(
            'All content has been uploaded, but the upload status is not finalized.',
          );
        }
      }
      return response;
    } finally {
      // Ensure the file handle is always closed
      if (fileHandle) {
        await fileHandle.close();
      }
    }
  }
}
