function resolveCloudFlag(options: GoogleGenAIOptions): boolean {
  if (options.enterprise !== undefined || options.vertexai !== undefined) {
    if (
      options.enterprise !== undefined &&
      options.vertexai !== undefined &&
      options.enterprise !== options.vertexai
    ) {
      throw new Error(
        'enterprise and vertexAI flags have conflicting values, please set enterprise value only.',
      );
    }
    return options.enterprise ?? options.vertexai!;
  }

  const envEnterpriseStr = getEnv('GOOGLE_GENAI_USE_ENTERPRISE');
  const envVertexaiStr = getEnv('GOOGLE_GENAI_USE_VERTEXAI');
  const useEnterpriseEnv = stringToBoolean(envEnterpriseStr);
  const useVertexaiEnv = stringToBoolean(envVertexaiStr);

  if (
    envEnterpriseStr !== undefined &&
    envVertexaiStr !== undefined &&
    useEnterpriseEnv !== useVertexaiEnv
  ) {
    console.warn(
      'Warning: Both GOOGLE_GENAI_USE_ENTERPRISE and GOOGLE_GENAI_USE_VERTEXAI are set with conflicting values. The value of GOOGLE_GENAI_USE_ENTERPRISE will be used.',
    );
  }

  if (envEnterpriseStr !== undefined) {
    return useEnterpriseEnv;
  }
  if (envVertexaiStr !== undefined) {
    return useVertexaiEnv;
  }

  return false;
}

/**
 * The Google GenAI SDK.
 *
 * @remarks
 * Provides access to the GenAI features through either the {@link
 * https://cloud.google.com/vertex-ai/docs/reference/rest | Gemini API} or
 * the {@link https://cloud.google.com/vertex-ai/docs/reference/rest | Vertex AI
 * API}.
 *
 * The {@link GoogleGenAIOptions.vertexai} value determines which of the API
 * services to use.
 *
 * When using the Gemini API, a {@link GoogleGenAIOptions.apiKey} must also be
 * set. When using Vertex AI, both {@link GoogleGenAIOptions.project} and {@link
 * GoogleGenAIOptions.location} must be set, or a {@link
 * GoogleGenAIOptions.apiKey} must be set when using Express Mode.
 *
 * Explicitly passed in values in {@link GoogleGenAIOptions} will always take
 * precedence over environment variables. If both project/location and api_key
 * exist in the environment variables, the project/location will be used.
 *
 * @example
 * Initializing the SDK for using the Gemini API:
 * ```ts
 * import {GoogleGenAI} from '@google/genai';
 * const ai = new GoogleGenAI({apiKey: 'GEMINI_API_KEY'});
 * ```
 *
 * @example
 * Initializing the SDK for using the Vertex AI API:
 * ```ts
 * import {GoogleGenAI} from '@google/genai';
 * const ai = new GoogleGenAI({
 *   vertexai: true,
 *   project: 'PROJECT_ID',
 *   location: 'PROJECT_LOCATION'
 * });
 * ```
 *
 */
export class GoogleGenAI {
  protected readonly apiClient: ApiClient;
  private readonly apiKey?: string;
  public readonly vertexai: boolean;
  private readonly googleAuthOptions?: GoogleAuthOptions;
  private readonly project?: string;
  private readonly location?: string;
  private readonly apiVersion?: string;
  private readonly httpOptions?: HttpOptions;
  readonly models: Models;
  readonly live: Live;
  readonly batches: Batches;
  readonly chats: Chats;
  readonly caches: Caches;
  readonly files: Files;
  readonly operations: Operations;
  readonly authTokens: Tokens;
  readonly tunings: Tunings;
  readonly fileSearchStores: FileSearchStores;
  private _interactions: GeminiNextGenInteractions | undefined;
  private _webhooks: GeminiNextGenWebhooks | undefined;
  private _nextGenClient: GeminiNextGenAPI | undefined;

  private getNextGenClient(): GeminiNextGenAPI {
    const httpOpts = this.httpOptions;
    if (this._nextGenClient === undefined) {
      this._nextGenClient = new GeminiNextGenAPI({
        baseURL: this.apiClient.getBaseUrl(),
        apiKey: this.apiKey,
        apiVersion: this.apiClient.getApiVersion(),
        clientAdapter: this.apiClient,
        defaultHeaders: this.apiClient.getDefaultHeaders(),
        timeout: httpOpts?.timeout,
        maxRetries: httpOpts?.retryOptions?.attempts,
      });
    }

    // Unsupported Options Warnings
    if (httpOpts?.extraBody) {
      console.warn(
        'GoogleGenAI.interactions: Client level httpOptions.extraBody is not supported by the interactions client and will be ignored.',
      );
    }

    return this._nextGenClient;
  }

  get interactions(): GeminiNextGenInteractions {
    if (this._interactions !== undefined) {
      return this._interactions;
    }

    console.warn(
      'GoogleGenAI.interactions: Interactions usage is experimental and may change in future versions.',
    );

    this._interactions = this.getNextGenClient().interactions;
    return this._interactions;
  }

  get webhooks(): GeminiNextGenWebhooks {
    if (this._webhooks !== undefined) {
      return this._webhooks;
    }

    this._webhooks = this.getNextGenClient().webhooks;
    return this._webhooks;
  }
  constructor(options: GoogleGenAIOptions) {
    // Validate explicitly set initializer values.
    if ((options.project || options.location) && options.apiKey) {
      throw new Error(
        'Project/location and API key are mutually exclusive in the client initializer.',
      );
    }

    this.vertexai = resolveCloudFlag(options);
    const envApiKey = getApiKeyFromEnv();
    const envProject = getEnv('GOOGLE_CLOUD_PROJECT');
    const envLocation = getEnv('GOOGLE_CLOUD_LOCATION');

    this.apiKey = options.apiKey ?? envApiKey;
    this.project = options.project ?? envProject;
    this.location = options.location ?? envLocation;

    if (!this.vertexai && !this.apiKey) {
      console.warn('API key should be set when using the Gemini API.');
    }

    // Handle when to use Vertex AI in express mode (api key)
    if (this.vertexai) {
      if (options.googleAuthOptions?.credentials) {
        // Explicit credentials take precedence over implicit api_key.
        console.debug(
          'The user provided Google Cloud credentials will take precedence' +
            ' over the API key from the environment variable.',
        );
        this.apiKey = undefined;
      }
      // Explicit api_key and explicit project/location already handled above.
      if ((envProject || envLocation) && options.apiKey) {
        // Explicit api_key takes precedence over implicit project/location.
        console.debug(
          'The user provided Vertex AI API key will take precedence over' +
            ' the project/location from the environment variables.',
        );
        this.project = undefined;
        this.location = undefined;
      } else if ((options.project || options.location) && envApiKey) {
        // Explicit project/location takes precedence over implicit api_key.
        console.debug(
          'The user provided project/location will take precedence over' +
            ' the API key from the environment variables.',
        );
        this.apiKey = undefined;
      } else if ((envProject || envLocation) && envApiKey) {
        // Implicit project/location takes precedence over implicit api_key.
        console.debug(
          'The project/location from the environment variables will take' +
            ' precedence over the API key from the environment variables.',
        );
        this.apiKey = undefined;
      }

      if (!this.location && !this.apiKey) {
        this.location = 'global';
      }
    }

    const baseUrl = getBaseUrl(
      options.httpOptions,
      this.vertexai,
      getEnv('GOOGLE_VERTEX_BASE_URL'),
      getEnv('GOOGLE_GEMINI_BASE_URL'),
    );
    if (baseUrl) {
      if (options.httpOptions) {
        options.httpOptions.baseUrl = baseUrl;
      } else {
        options.httpOptions = {baseUrl: baseUrl};
      }
    }

    this.apiVersion = options.apiVersion;
    this.httpOptions = options.httpOptions;
    const auth = new NodeAuth({
      apiKey: this.apiKey,
      googleAuthOptions: options.googleAuthOptions,
    });
    this.apiClient = new ApiClient({
      auth: auth,
      project: this.project,
      location: this.location,
      apiVersion: this.apiVersion,
      apiKey: this.apiKey,
      vertexai: this.vertexai,
      httpOptions: this.httpOptions,
      userAgentExtra: LANGUAGE_LABEL_PREFIX + process.version,
      uploader: new NodeUploader(),
      downloader: new NodeDownloader(),
    });
    this.models = new Models(this.apiClient);
    this.live = new Live(this.apiClient, auth, new NodeWebSocketFactory());
    this.batches = new Batches(this.apiClient);
    this.chats = new Chats(this.models, this.apiClient);
    this.caches = new Caches(this.apiClient);
    this.files = new NodeFiles(this.apiClient);
    this.operations = new Operations(this.apiClient);
    this.authTokens = new Tokens(this.apiClient);
    this.tunings = new Tunings(this.apiClient);
    this.fileSearchStores = new FileSearchStores(this.apiClient);
  }
}

function getEnv(env: string): string | undefined {
  return process?.env?.[env]?.trim() ?? undefined;
}

function stringToBoolean(str?: string): boolean {
  if (str === undefined) {
    return false;
  }
  return str.toLowerCase() === 'true';
}

function getApiKeyFromEnv(): string | undefined {
  const envGoogleApiKey = getEnv('GOOGLE_API_KEY');
  const envGeminiApiKey = getEnv('GEMINI_API_KEY');
  if (envGoogleApiKey && envGeminiApiKey) {
    console.warn(
      'Both GOOGLE_API_KEY and GEMINI_API_KEY are set. Using GOOGLE_API_KEY.',
    );
  }
  return envGoogleApiKey || envGeminiApiKey || undefined;
}

// Main Monte Carlo Engine - Integration and Performance Optimization
import { PathGenerator } from './path-generator';
import { CorrelationMatrix } from './correlation-matrix';
import { RiskCalculator } from './risk-calculator';
import { StressTestRunner, BlackSwanScenario, FlashCrashScenario, LiquidityCrisisScenario, RegimeShiftScenario, StressTestResult } from './stress-test-engine';
import { MonteCarloRequest, MonteCarloResult, RiskMetrics } from '../types';
import { randomUUID } from 'crypto';

export class MonteCarloEngine {
  private pathGenerator: PathGenerator;
  private riskCalculator: RiskCalculator;
  private stressTestRunner: StressTestRunner;
  private activeJobs: Map<string, JobStatus>;
  private useGPU: boolean;

  constructor() {
    this.pathGenerator = new PathGenerator({
      initialPrice: 100,
      drift: 0.05,
      volatility: 0.2,
      timeSteps: 252,
      numPaths: 10000,
      seed: 42,
      useGPU: true
    });
    this.riskCalculator = new RiskCalculator();
    this.stressTestRunner = new StressTestRunner();
    this.activeJobs = new Map();
    this.useGPU = this.detectGPU();
  }

  private detectGPU(): boolean {
    try {
      // Check for WebGL availability
      return typeof window !== 'undefined' && !!window.WebGLRenderingContext;
    } catch {
      return false;
    }
  }

  /**
   * Start Monte Carlo simulation
   */
  async simulate(request: MonteCarloRequest): Promise<MonteCarloResult> {
    const jobId = `mc_${randomUUID().substring(0, 8)}`;

    // Create job status
    this.activeJobs.set(jobId, {
      id: jobId,
      status: 'running',
      progress: 0,
      startTime: Date.now()
    });

    try {
      // Run simulation asynchronously
      const result = await this.runSimulation(request, jobId);

      this.activeJobs.set(jobId, {
        ...this.activeJobs.get(jobId)!,
        status: 'completed',
        progress: 100,
        result
      });

      return {
        jobId,
        status: 'completed',
        result
      };
    } catch (error) {
      this.activeJobs.set(jobId, {
        ...this.activeJobs.get(jobId)!,
        status: 'failed',
        error: error instanceof Error ? error.message : 'Unknown error'
      });

      return {
        jobId,
        status: 'failed',
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }

  /**
   * Run the actual simulation
   */
  private async runSimulation(
    request: MonteCarloRequest,
    jobId: string
  ): Promise<RiskMetrics> {
    const startTime = Date.now();
    const { portfolio, parameters } = request;

    // Calculate portfolio value
    const portfolioValue = portfolio.positions.reduce(
      (sum, pos) => sum + pos.quantity * pos.currentPrice,
      0
    );

    // Step 1: Generate correlated price paths
    this.updateProgress(jobId, 10, 'Generating price paths...');
    const paths = await this.generateCorrelatedPaths(portfolio, parameters);

    // Step 2: Calculate loss distribution
    this.updateProgress(jobId, 40, 'Calculating loss distribution...');
    const timeSteps = parameters.timeHorizon * 252; // Trading days per year
    const losses = this.riskCalculator.calculateLossDistribution(
      paths,
      timeSteps,
      portfolioValue
    );

    // Step 3: Calculate risk metrics
    this.updateProgress(jobId, 70, 'Computing risk metrics...');
    const var95 = this.riskCalculator.historicalVaR(losses, 0.95);
    const var99 = this.riskCalculator.historicalVaR(losses, 0.99);
    const cvar95 = this.riskCalculator.conditionalVaR(losses, 0.95);
    const cvar99 = this.riskCalculator.conditionalVaR(losses, 0.99);

    // Step 4: Component VaR
    this.updateProgress(jobId, 85, 'Computing component VaR...');
    const componentVaR = this.calculateComponentVaR(portfolio, losses, portfolioValue);

    // Step 5: Tail risk
    this.updateProgress(jobId, 95, 'Analyzing tail risk...');
    const tailRisk = this.calculateTailRisk(losses);

    // Step 6: Convergence check
    const convergence = this.checkConvergence(losses, parameters.numPaths);

    const runtimeMs = Date.now() - startTime;

    return {
      var: { '95%': var95, '99%': var99 },
      cvar: { '95%': cvar95, '99%': cvar99 },
      expectedShortfall: cvar99,
      componentVaR,
      tailRisk,
      simulationStats: {
        numPaths: parameters.numPaths,
        convergence: this.checkConvergence(losses, parameters.numPaths),
        runtimeMs
      }
    };
  }

  /**
   * Generate correlated price paths for portfolio
   */
  private async generateCorrelatedPaths(
    portfolio: MonteCarloRequest['portfolio'],
    parameters: MonteCarloRequest['parameters']
  ): Promise<Float64Array> {
    const numAssets = portfolio.positions.length;
    const timeSteps = parameters.timeHorizon * 252;
    const numPaths = parameters.numPaths;

    // Use GPU if available and beneficial
    const useGPU = this.useGPU && numPaths >= 1000;

    if (useGPU) {
      return this.generatePathsGPU(portfolio, parameters);
    } else {
      return this.generatePathsCPU(portfolio, parameters);
    }
  }

  /**
   * Generate paths using CPU (NumJS)
   */
  private generatePathsCPU(
    portfolio: MonteCarloRequest['portfolio'],
    parameters: MonteCarloRequest['parameters']
  ): Float64Array {
    const numAssets = portfolio.positions.length;
    const timeSteps = parameters.timeHorizon * 252;
    const numPaths = parameters.numPaths;
    const totalPoints = numPaths * (timeSteps + 1);

    // For simplicity, generate aggregate portfolio paths
    // In production, generate per-asset paths and aggregate
    const paths = new Float64Array(totalPoints);
    const dt = 1 / timeSteps;

    // Portfolio-level parameters (simplified)
    const portfolioDrift = 0.08;
    const portfolioVol = 0.25;
    const driftAdj = (portfolioDrift - 0.5 * portfolioVol * portfolioVol) * dt;
    const volAdj = portfolioVol * Math.sqrt(dt);

    // Initialize
    const initialValue = portfolio.positions.reduce(
      (sum, pos) => sum + pos.quantity * pos.currentPrice,
      0
    );

    for (let i = 0; i < numPaths; i++) {
      paths[i * (timeSteps + 1)] = initialValue;
    }

    // Generate paths
    for (let i = 0; i < numPaths; i++) {
      const baseIdx = i * (timeSteps + 1);
      for (let t = 1; t <= timeSteps; t++) {
        const z = this.gaussianRandom();
        const logReturn = driftAdj + volAdj * z;
        const prevPrice = paths[baseIdx + t - 1];
        const newPrice = prevPrice * Math.exp(logReturn);
        paths[baseIdx + t] = Math.max(newPrice, 1e-8);
      }
    }

    return paths;
  }

  /**
   * Generate paths using GPU (WebGL)
   */
  private async generatePathsGPU(
    portfolio: MonteCarloRequest['portfolio'],
    parameters: MonteCarloRequest['parameters']
  ): Promise<Float64Array> {
    // Fallback to CPU for now (GPU.js requires browser environment)
    // In production, use gpu.js with headless-gl in Node.js
    return this.generatePathsCPU(portfolio, parameters);
  }

  /**
   * Calculate component VaR for each position
   */
  private calculateComponentVaR(
    portfolio: MonteCarloRequest['portfolio'],
    losses: number[],
    portfolioValue: number
  ): Record<string, number> {
    const componentVaR: Record<string, number> = {};

    portfolio.positions.forEach(position => {
      const positionValue = position.quantity * position.currentPrice;
      const weight = positionValue / portfolioValue;

      // Simplified: proportional contribution
      // In production, use marginal VaR calculation
      const totalVaR = this.riskCalculator.historicalVaR(losses, 0.95);
      componentVaR[position.symbol] = totalVaR * weight;
    });

    return componentVaR;
  }

  /**
   * Calculate tail risk metrics
   */
  private calculateTailRisk(losses: number[]) {
    const sorted = [...losses].sort((a, b) => b - a);

    return {
      worstCaseLoss: sorted[0],
      percentile99_9: sorted[Math.floor(0.001 * sorted.length)]
    };
  }

  /**
   * Check convergence of VaR estimate
   */
  private checkConvergence(losses: number[], numPaths: number): number {
    // Split into two halves and compare VaR estimates
    const half = Math.floor(losses.length / 2);
    const firstHalf = losses.slice(0, half);
    const secondHalf = losses.slice(half);

    const var1 = this.riskCalculator.historicalVaR(firstHalf, 0.95);
    const var2 = this.riskCalculator.historicalVaR(secondHalf, 0.95);

    return Math.abs(var1 - var2) / ((var1 + var2) / 2);
  }

  /**
   * Update job progress
   */
  private updateProgress(jobId: string, progress: number, message?: string): void {
    const job = this.activeJobs.get(jobId);
    if (job) {
      job.progress = progress;
      job.lastUpdate = Date.now();
      if (message) {
        job.message = message;
      }
    }
  }

/**
    * Get job status
    */
  async getStatus(jobId: string): Promise<MonteCarloResult | null> {
    const job = this.activeJobs.get(jobId);
    if (!job) {
      return null;
    }

    return {
      jobId,
      status: job.status,
      result: job.result,
      error: job.error
    };
  }

  /**
   * Run stress tests
   */
  async runStressTests(
    portfolio: MonteCarloRequest['portfolio'],
    scenarios: Array<{
      type: 'black-swan' | 'flash-crash' | 'liquidity-crisis' | 'regime-shift';
      intensity?: number;
    }>
  ): Promise<StressTestResult[]> {
    const portfolioValue = portfolio.positions.reduce(
      (sum, pos) => sum + pos.quantity * pos.currentPrice,
      0
    );

    // Add scenarios
    scenarios.forEach(s => {
      switch (s.type) {
        case 'black-swan':
          this.stressTestRunner.addScenario(new BlackSwanScenario(s.intensity));
          break;
        case 'flash-crash':
          this.stressTestRunner.addScenario(new FlashCrashScenario(s.intensity));
          break;
        case 'liquidity-crisis':
          this.stressTestRunner.addScenario(new LiquidityCrisisScenario(s.intensity));
          break;
        case 'regime-shift':
          this.stressTestRunner.addScenario(new RegimeShiftScenario(s.intensity));
          break;
      }
    });

    // Run all scenarios
    const report = await this.stressTestRunner.runAllScenarios(portfolioValue);
    return report.results;
  }

  /**
   * Validate VaR model with backtesting
   */
  async validateVaR(
    historicalReturns: number[],
    varEstimates: number[],
    confidenceLevel: number
  ): Promise<{
    passes: boolean;
    pValue: number;
    failureRate: number;
  }> {
    const losses = historicalReturns.map(r => -r);
    const result = this.riskCalculator.kupiecTest(
      losses,
      this.riskCalculator.historicalVaR(losses, confidenceLevel),
      confidenceLevel
    );

    return {
      passes: result.passes,
      pValue: result.pValue,
      failureRate: result.failureRate
    };
  }

  private gaussianRandom(): number {
    const u1 = Math.random();
    const u2 = Math.random();
    const r = Math.sqrt(-2 * Math.log(u1));
    const theta = 2 * Math.PI * u2;
    return r * Math.cos(theta);
  }
}

