import { Queue, Worker } from 'bullmq';
import IORedis from 'ioredis';
import { MarketDataService } from './api/marketDataService.js';
import { OptimizationEngine } from './strategy/optimization_engine.js';
import { logger } from './logging/logger.js';

// Redis connection with graceful error handling
let redisConnection: IORedis | null = null;
let redisAvailable = false;
let marketDataWorker: Worker | null = null;
let optimizationWorker: Worker | null = null;
let connectionAttempted = false;

function getRedisConnection(): IORedis | null {
  if (redisConnection) return redisConnection;
  if (connectionAttempted) return null; // Already tried and failed
  connectionAttempted = true;

  try {
    redisConnection = new IORedis({
      host: process.env.REDIS_HOST || 'localhost',
      port: parseInt(process.env.REDIS_PORT || '6379'),
      password: process.env.REDIS_PASSWORD || '',
      maxRetriesPerRequest: null,
      lazyConnect: true,
    });

    redisConnection.on('connect', () => {
      redisAvailable = true;
      logger.info('Redis connection established', { service: 'JobQueue' });
    });

    redisConnection.on('error', (err) => {
      redisAvailable = false;
      logger.warn('Redis connection error, queue jobs will be disabled', { 
        error: err.message,
        service: 'JobQueue'
      });
    });

    return redisConnection;
  } catch (err) {
    logger.warn('Failed to create Redis connection, queue jobs disabled', { 
      error: err instanceof Error ? err.message : String(err),
      service: 'JobQueue'
    });
    return null;
  }
}

// Job queues (lazy initialization)
let marketDataQueue: Queue | null = null;
let optimizationQueue: Queue | null = null;

export function getMarketDataQueue(): Queue | null {
  const conn = getRedisConnection();
  if (!marketDataQueue && conn && redisAvailable) {
    try {
      marketDataQueue = new Queue('market-data', {
        connection: conn,
        defaultJobOptions: {
          priority: 5, // Medium priority for market data
          attempts: 3,
          backoff: {
            type: 'exponential',
            delay: 5000
          }
        }
      });
    } catch (err) {
      logger.warn('Failed to create market data queue', {
        error: err instanceof Error ? err.message : String(err),
        service: 'JobQueue'
      });
    }
  }
  return marketDataQueue;
}

export function getOptimizationQueue(): Queue | null {
  const conn = getRedisConnection();
  if (!optimizationQueue && conn && redisAvailable) {
    try {
      optimizationQueue = new Queue('optimization', {
        connection: conn,
        defaultJobOptions: {
          priority: 3, // Lower priority for optimization
          attempts: 2,
          backoff: {
            type: 'exponential',
            delay: 30000
          }
        }
      });
    } catch (err) {
      logger.warn('Failed to create optimization queue', {
        error: err instanceof Error ? err.message : String(err),
        service: 'JobQueue'
      });
    }
  }
  return optimizationQueue;
}

// Data pipeline queue for high-priority data processing
let dataPipelineQueue: Queue | null = null;
let dataPipelineWorker: Worker | null = null;

export function getDataPipelineQueue(): Queue | null {
  const conn = getRedisConnection();
  if (!dataPipelineQueue && conn && redisAvailable) {
    try {
      dataPipelineQueue = new Queue('data-pipeline', {
        connection: conn,
        defaultJobOptions: {
          priority: 10, // High priority for data pipeline
          attempts: 5,
          backoff: {
            type: 'exponential',
            delay: 1000
          },
          removeOnComplete: 50,
          removeOnFail: 20
        }
      });
    } catch (err) {
      logger.warn('Failed to create data pipeline queue', {
        error: err instanceof Error ? err.message : String(err),
        service: 'JobQueue'
      });
    }
  }
  return dataPipelineQueue;
}

// Initialize workers (called after services are ready)
export function initializeWorkers(marketDataService: MarketDataService, optimizationEngine: OptimizationEngine) {
  const conn = getRedisConnection();
  if (!conn || !redisAvailable) {
    logger.warn('Cannot initialize workers: Redis not available', { service: 'JobQueue' });
    return;
  }

  // Market data worker
  marketDataWorker = new Worker('market-data', async (job) => {
    logger.info('Processing market data job', { jobId: job.id, service: 'JobQueue' });
    try {
      await marketDataService.fetchMarketData();
      await marketDataService.fetchNews();
      logger.info('Market data job completed successfully', { jobId: job.id, service: 'JobQueue' });
    } catch (error) {
      logger.error('Market data job failed', {
        jobId: job.id,
        error: error instanceof Error ? error.message : String(error),
        service: 'JobQueue'
      });
      throw error;
    }
  }, {
    connection: conn,
    concurrency: 1,
    limiter: { max: 1, duration: 60000 },
  });

  // Optimization worker
  optimizationWorker = new Worker('optimization', async (job) => {
    const { currentRegime }: { currentRegime: string } = job.data;
    logger.info('Processing optimization job', { jobId: job.id, regime: currentRegime, service: 'JobQueue' });
    try {
      await optimizationEngine.optimize(currentRegime);
      logger.info('Optimization job completed successfully', { jobId: job.id, service: 'JobQueue' });
    } catch (error) {
      logger.error('Optimization job failed', {
        jobId: job.id,
        error: error instanceof Error ? error.message : String(error),
        service: 'JobQueue'
      });
      throw error;
    }
  }, {
    connection: conn,
    concurrency: 1,
    limiter: { max: 1, duration: 3600000 },
  });

  // Data pipeline worker (high priority)
  dataPipelineWorker = new Worker('data-pipeline', async (job) => {
    logger.info('Processing data pipeline job', { jobId: job.id, priority: job.opts.priority, service: 'JobQueue' });
    try {
      const { operation, data } = job.data;

      // Process based on operation type
      switch (operation) {
        case 'indicator_calculation':
          // Handle parallel indicator calculation
          break;
        case 'cache_invalidation':
          // Handle cache invalidation
          break;
        case 'data_deduplication':
          // Handle data deduplication
          break;
        default:
          logger.warn('Unknown data pipeline operation', { operation });
      }

      logger.info('Data pipeline job completed successfully', { jobId: job.id, service: 'JobQueue' });
    } catch (error) {
      logger.error('Data pipeline job failed', {
        jobId: job.id,
        error: error instanceof Error ? error.message : String(error),
        service: 'JobQueue'
      });
      throw error;
    }
  }, {
    connection: conn,
    concurrency: 4, // Higher concurrency for data pipeline
    limiter: { max: 100, duration: 60000 }, // Allow more jobs per minute
  });

  // Worker event handlers
  marketDataWorker.on('failed', (job, err) => {
    logger.error('Market data job failed permanently', {
      jobId: job?.id,
      error: err.message,
      attempts: job?.attemptsMade,
      service: 'JobQueue'
    });
  });

  optimizationWorker.on('failed', (job, err) => {
    logger.error('Optimization job failed permanently', {
      jobId: job?.id,
      error: err.message,
      attempts: job?.attemptsMade,
      service: 'JobQueue'
    });
  });

  marketDataWorker.on('completed', (job) => {
    logger.info('Market data job completed', { jobId: job.id, service: 'JobQueue' });
  });

  optimizationWorker.on('completed', (job) => {
    logger.info('Optimization job completed', { jobId: job.id, service: 'JobQueue' });
  });

  logger.info('BullMQ workers initialized', { service: 'JobQueue' });
}

// Queue monitoring
export async function getQueueHealth() {
  try {
    const mdQueue = getMarketDataQueue();
    const optQueue = getOptimizationQueue();
    const dpQueue = getDataPipelineQueue();

    if (!mdQueue || !optQueue) {
      return {
        marketData: { waiting: 0, active: 0, completed: 0, failed: 0, delayed: 0 },
        optimization: { waiting: 0, active: 0, completed: 0, failed: 0, delayed: 0 },
        dataPipeline: { waiting: 0, active: 0, completed: 0, failed: 0, delayed: 0 },
        timestamp: Date.now(),
        redisAvailable,
      };
    }

    const [marketDataStats, optimizationStats, dataPipelineStats] = await Promise.all([
      mdQueue.getJobCounts(),
      optQueue.getJobCounts(),
      dpQueue ? dpQueue.getJobCounts() : Promise.resolve({ waiting: 0, active: 0, completed: 0, failed: 0, delayed: 0 }),
    ]);

    return {
      marketData: {
        waiting: marketDataStats.waiting || 0,
        active: marketDataStats.active || 0,
        completed: marketDataStats.completed || 0,
        failed: marketDataStats.failed || 0,
        delayed: marketDataStats.delayed || 0,
      },
      optimization: {
        waiting: optimizationStats.waiting || 0,
        active: optimizationStats.active || 0,
        completed: optimizationStats.completed || 0,
        failed: optimizationStats.failed || 0,
        delayed: optimizationStats.delayed || 0,
      },
      dataPipeline: {
        waiting: dataPipelineStats.waiting || 0,
        active: dataPipelineStats.active || 0,
        completed: dataPipelineStats.completed || 0,
        failed: dataPipelineStats.failed || 0,
        delayed: dataPipelineStats.delayed || 0,
      },
      timestamp: Date.now(),
      redisAvailable,
    };
  } catch (error) {
    logger.error('Failed to get queue health', {
      error: error instanceof Error ? error.message : String(error),
      service: 'JobQueue'
    });
    return null;
  }
}

// Graceful shutdown
export async function closeQueues() {
  logger.info('Closing job queues', { service: 'JobQueue' });

  const closePromises: Promise<void>[] = [];

  if (marketDataWorker) closePromises.push(marketDataWorker.close().then(() => {}).catch(() => {}));
  if (optimizationWorker) closePromises.push(optimizationWorker.close().then(() => {}).catch(() => {}));
  if (dataPipelineWorker) closePromises.push(dataPipelineWorker.close().then(() => {}).catch(() => {}));
  if (marketDataQueue) closePromises.push(marketDataQueue.close().then(() => {}).catch(() => {}));
  if (optimizationQueue) closePromises.push(optimizationQueue.close().then(() => {}).catch(() => {}));
  if (dataPipelineQueue) closePromises.push(dataPipelineQueue.close().then(() => {}).catch(() => {}));
  if (redisConnection) closePromises.push(redisConnection.quit().then(() => {}).catch(() => {}));

  await Promise.all(closePromises);

  logger.info('Job queues closed successfully', { service: 'JobQueue' });
}

import { PaperTradingStateMachine, PaperTradingState, PaperTradingEvent, PaperTradingContext } from './state-machine';
import { OrderBookSimulator, PaperOrder } from './order-book';
import { PaperPositionTracker, PaperPosition, PnlCalculation } from './position-tracker';
import { Decimal } from 'decimal.js';
import { randomUUID } from 'crypto';

export interface PaperTradeRequest {
  symbol: string;
  side: 'buy' | 'sell';
  type: 'market' | 'limit';
  quantity: number;
  price?: number;
  stopLoss?: number;
  takeProfit?: number;
  leverage?: number;
  timeInForce: 'GTC' | 'IOC' | 'FOK';
  idempotencyKey?: string;
}

export interface PaperTradeResponse {
  id: string;
  status: 'pending' | 'filled' | 'cancelled' | 'expired';
  symbol: string;
  side: 'buy' | 'sell';
  quantity: string;
  price?: string;
  filledQuantity?: string;
  fillPrice?: string;
  timestamp: number;
  pnl?: string;
}

export interface PositionResponse {
  id: string;
  symbol: string;
  side: 'buy' | 'sell';
  quantity: string;
  entryPrice: string;
  currentPrice?: string;
  stopLoss?: string;
  takeProfit?: string;
  leverage: number;
  status: 'open' | 'closed' | 'liquidated';
  unrealizedPnl?: string;
  realizedPnl?: string;
  pnlPercentage?: string;
  roi?: string;
  openedAt: number;
  closedAt?: number;
  candlesHeld: number;
  exitReason?: string;
}

export interface PaperTradingSummary {
  totalUnrealizedPnl: string;
  totalRealizedPnl: string;
  totalMarginUsed: string;
  positionCount: {
    total: number;
    open: number;
    closed: number;
    liquidated: number;
  };
  positions: PositionResponse[];
}

export interface IdempotencyRecord {
  key: string;
  requestHash: string;
  response: any;
  timestamp: number;
  expiresAt: number;
}

export class PaperTradingService {
  private stateMachines: Map<string, PaperTradingStateMachine> = new Map();
  private orderBook: OrderBookSimulator;
  private positionTracker: PaperPositionTracker;
  private idempotencyCache: Map<string, IdempotencyRecord> = new Map();
  private readonly IDEMPOTENCY_TTL = 24 * 60 * 60 * 1000; // 24 hours
  private orderMatchingInterval: NodeJS.Timeout | null = null;
  private priceUpdateInterval: NodeJS.Timeout | null = null;
  private idempotencyCleanupInterval: NodeJS.Timeout | null = null;

  constructor() {
    this.orderBook = new OrderBookSimulator();
    this.positionTracker = new PaperPositionTracker();
    this.startOrderMatching();
    this.startPriceUpdates();
    this.startIdempotencyCleanup();
  }

  public stop(): void {
    if (this.orderMatchingInterval) {
      clearInterval(this.orderMatchingInterval);
      this.orderMatchingInterval = null;
    }
    if (this.priceUpdateInterval) {
      clearInterval(this.priceUpdateInterval);
      this.priceUpdateInterval = null;
    }
    if (this.idempotencyCleanupInterval) {
      clearInterval(this.idempotencyCleanupInterval);
      this.idempotencyCleanupInterval = null;
    }
  }

  private startOrderMatching(): void {
    this.orderMatchingInterval = setInterval(() => {
      // Match orders for all symbols
      const symbols = ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'BNB/USDT', 'XRP/USDT'];

      for (const symbol of symbols) {
        const orderBook = this.orderBook.getOrderBook(symbol);
        if (orderBook) {
          const { filledOrders } = this.orderBook.matchOrders(symbol);

          for (const order of filledOrders) {
            this.handleOrderFill(order);
          }
        }
      }
    }, 100); // Match every 100ms
    this.orderMatchingInterval.unref();
  }

  private startPriceUpdates(): void {
    this.priceUpdateInterval = setInterval(() => {
      // Update prices for all symbols
      const symbols = ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'BNB/USDT', 'XRP/USDT'];

      for (const symbol of symbols) {
        const orderBook = this.orderBook.getOrderBook(symbol);
        if (orderBook) {
          const currentPrice = orderBook.midPrice.toNumber();
          const volatility = 0.02;

          this.orderBook.updateOrderBook(symbol, currentPrice, volatility);

          // Update position prices
          const newPrice = new Decimal(currentPrice);
          const positionUpdates = this.positionTracker.updatePositionPriceBySymbol(symbol, newPrice, Date.now());

          // Check stop loss and take profit
          for (const { position } of positionUpdates) {
            if (this.positionTracker.checkStopLoss(position.id, newPrice)) {
              this.closePosition(position.id, newPrice, Date.now(), 'stop_loss');
            } else if (this.positionTracker.checkTakeProfit(position.id, newPrice)) {
              this.closePosition(position.id, newPrice, Date.now(), 'take_profit');
            }
          }
        }
      }
    }, 100); // Update every 100ms
    this.priceUpdateInterval.unref();
  }

  private startIdempotencyCleanup(): void {
    this.idempotencyCleanupInterval = setInterval(() => {
      const now = Date.now();
      for (const [key, record] of this.idempotencyCache) {
        if (now > record.expiresAt) {
          this.idempotencyCache.delete(key);
        }
      }
    }, 60 * 60 * 1000); // Clean up every hour
    this.idempotencyCleanupInterval.unref();
  }

  private handleOrderFill(order: PaperOrder): void {
    const stateMachine = this.stateMachines.get(order.id);
    if (stateMachine) {
      stateMachine.sendEvent('FILL_ORDER', {
        positionId: order.id,
        price: order.fillPrice?.toNumber(),
        timestamp: Date.now(),
      });
    }

    // Update position tracker
    if (order.fillPrice && order.filledQuantity) {
      const position = this.positionTracker.getPosition(order.id);
      if (position) {
        this.positionTracker.updatePositionPrice(order.id, order.fillPrice);
      }
    }
  }

  public async createPaperTrade(request: PaperTradeRequest): Promise<PaperTradeResponse> {
    // Check idempotency
    if (request.idempotencyKey) {
      const cached = this.checkIdempotency(request.idempotencyKey, request);
      if (cached) {
        return cached;
      }
    }

    const orderId = randomUUID();
    const quantity = new Decimal(request.quantity);
    const price = request.price ? new Decimal(request.price) : undefined;

    // Create state machine
    const stateMachine = new PaperTradingStateMachine({
      positionId: orderId,
      symbol: request.symbol,
      side: request.side,
      amount: request.quantity,
      price: request.price,
      stopLoss: request.stopLoss,
      takeProfit: request.takeProfit,
      leverage: request.leverage || 1,
      timestamp: Date.now(),
    });

    this.stateMachines.set(orderId, stateMachine);

    // Create paper order
    const paperOrder: PaperOrder = {
      id: orderId, // Use same ID as position
      symbol: request.symbol,
      side: request.side,
      type: request.type,
      quantity,
      price,
      timeInForce: request.timeInForce,
      timestamp: Date.now(),
      status: 'pending',
    };

    this.orderBook.addPaperOrder(paperOrder);

    // Create position (use same ID as order for simplicity)
    const position = this.positionTracker.openPosition({
      symbol: request.symbol,
      side: request.side,
      quantity,
      entryPrice: price || new Decimal(0), // Will be updated on fill
      stopLoss: request.stopLoss ? new Decimal(request.stopLoss) : undefined,
      takeProfit: request.takeProfit ? new Decimal(request.takeProfit) : undefined,
      leverage: request.leverage || 1,
    });

    // Trigger order creation
    stateMachine.sendEvent('CREATE_ORDER');

    const response: PaperTradeResponse = {
      id: position.id, // Use position ID instead of order ID
      status: 'pending',
      symbol: request.symbol,
      side: request.side,
      quantity: quantity.toString(),
      price: price?.toString(),
      timestamp: Date.now(),
    };

    // Cache idempotency
    if (request.idempotencyKey) {
      this.cacheIdempotency(request.idempotencyKey, request, response);
    }

    return response;
  }

  public async cancelPaperTrade(positionId: string, idempotencyKey?: string): Promise<PaperTradeResponse> {
    // Check idempotency
    if (idempotencyKey) {
      const cached = this.checkIdempotency(idempotencyKey, { positionId });
      if (cached) {
        return cached;
      }
    }

    const stateMachine = this.stateMachines.get(positionId);
    const order = this.orderBook.getPaperOrder(positionId);

    if (!stateMachine || !order) {
      throw new Error('Order not found');
    }

    if (stateMachine.getState() !== 'PENDING_ORDER') {
      throw new Error('Order cannot be cancelled in current state');
    }

    stateMachine.sendEvent('CANCEL_ORDER');
    this.orderBook.cancelPaperOrder(positionId);
    // Remove the pending position
    this.positionTracker.closePosition(positionId, new Decimal(0), Date.now());

    const response: PaperTradeResponse = {
      id: positionId,
      status: 'cancelled',
      symbol: order.symbol,
      side: order.side,
      quantity: order.quantity.toString(),
      price: order.price?.toString(),
      timestamp: Date.now(),
    };

    if (idempotencyKey) {
      this.cacheIdempotency(idempotencyKey, { positionId }, response);
    }

    return response;
  }

  public async closePosition(positionId: string, currentPrice: Decimal, timestamp: number, reason?: string): Promise<PaperPosition | null> {
    const position = this.positionTracker.closePosition(positionId, currentPrice, timestamp);

    if (position) {
      const stateMachine = this.stateMachines.get(positionId);
      if (stateMachine) {
        stateMachine.sendEvent('CLOSE_POSITION', {
          positionId,
          price: currentPrice.toNumber(),
          timestamp,
        });
      }

      const order = this.orderBook.getPaperOrder(positionId);
      if (order) {
        order.status = 'filled';
        order.fillPrice = currentPrice;
        order.fillTimestamp = timestamp;
      }
    }

    return position;
  }

  public async getPosition(positionId: string): Promise<PositionResponse | null> {
    const position = this.positionTracker.getPosition(positionId);
    if (!position) {
      return null;
    }

    const pnl = this.positionTracker.calculatePnl(position, position.currentPrice || position.entryPrice);

    return {
      id: position.id,
      symbol: position.symbol,
      side: position.side,
      quantity: position.quantity.toString(),
      entryPrice: position.entryPrice.toString(),
      currentPrice: position.currentPrice?.toString(),
      stopLoss: position.stopLoss?.toString(),
      takeProfit: position.takeProfit?.toString(),
      leverage: position.leverage,
      status: position.status,
      unrealizedPnl: position.unrealizedPnl?.toString(),
      realizedPnl: position.realizedPnl?.toString(),
      pnlPercentage: pnl.pnlPercentage.toString(),
      roi: pnl.roi.toString(),
      openedAt: position.openedAt,
      closedAt: position.closedAt,
      candlesHeld: position.candlesHeld,
      exitReason: position.exitReason,
    };
  }

  public async getOpenPositions(): Promise<PositionResponse[]> {
    const positions = this.positionTracker.getOpenPositions();

    return positions.map(position => {
      const pnl = this.positionTracker.calculatePnl(position, position.currentPrice || position.entryPrice);

      return {
        id: position.id,
        symbol: position.symbol,
        side: position.side,
        quantity: position.quantity.toString(),
        entryPrice: position.entryPrice.toString(),
        currentPrice: position.currentPrice?.toString(),
        stopLoss: position.stopLoss?.toString(),
        takeProfit: position.takeProfit?.toString(),
        leverage: position.leverage,
        status: position.status,
        unrealizedPnl: position.unrealizedPnl?.toString(),
        realizedPnl: position.realizedPnl?.toString(),
        pnlPercentage: pnl.pnlPercentage.toString(),
        roi: pnl.roi.toString(),
        openedAt: position.openedAt,
        closedAt: position.closedAt,
        candlesHeld: position.candlesHeld,
        exitReason: position.exitReason,
      };
    });
  }

  public async getSummary(): Promise<PaperTradingSummary> {
    const positions = await this.getOpenPositions();

    const summary: PaperTradingSummary = {
      totalUnrealizedPnl: this.positionTracker.getTotalUnrealizedPnl().toString(),
      totalRealizedPnl: this.positionTracker.getTotalRealizedPnl().toString(),
      totalMarginUsed: this.positionTracker.getTotalMarginUsed().toString(),
      positionCount: this.positionTracker.getPositionCount(),
      positions,
    };

    return summary;
  }

  public getOrderBookSnapshot(symbol: string): any {
    return this.orderBook.getOrderBook(symbol);
  }

  private checkIdempotency(key: string, request: any): PaperTradeResponse | null {
    const record = this.idempotencyCache.get(key);
    if (!record) {
      return null;
    }

    const requestHash = this.hashRequest(request);
    if (record.requestHash !== requestHash) {
      throw new Error('Idempotency key conflict: different request');
    }

    if (Date.now() > record.expiresAt) {
      this.idempotencyCache.delete(key);
      return null;
    }

    return record.response as PaperTradeResponse;
  }

  private cacheIdempotency(key: string, request: any, response: PaperTradeResponse): void {
    const requestHash = this.hashRequest(request);

    this.idempotencyCache.set(key, {
      key,
      requestHash,
      response,
      timestamp: Date.now(),
      expiresAt: Date.now() + this.IDEMPOTENCY_TTL,
    });
  }

  private hashRequest(request: any): string {
    // Simple hash function for idempotency
    const str = JSON.stringify(request);
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32bit integer
    }
    return hash.toString(16);
  }
}

export type PaperTradingState = 
  | 'IDLE'
  | 'PENDING_ORDER'
  | 'OPEN_POSITION'
  | 'PENDING_CLOSE'
  | 'CLOSED'
  | 'ERROR';

export type PaperTradingEvent = 
  | 'CREATE_ORDER'
  | 'FILL_ORDER'
  | 'CANCEL_ORDER'
  | 'UPDATE_PRICE'
  | 'CLOSE_POSITION'
  | 'ERROR_OCCURRED'
  | 'RESET';

export interface PaperTradingContext {
  positionId?: string;
  symbol?: string;
  side?: 'buy' | 'sell';
  amount?: number;
  price?: number;
  stopLoss?: number;
  takeProfit?: number;
  leverage?: number;
  currentPrice?: number;
  unrealizedPnl?: number;
  realizedPnl?: number;
  error?: string;
  timestamp: number;
}

interface Transition {
  from: PaperTradingState | PaperTradingState[];
  to: PaperTradingState;
  event: PaperTradingEvent;
  guard?: (ctx: PaperTradingContext) => boolean;
  action?: (ctx: PaperTradingContext) => void;
}

export class PaperTradingStateMachine {
  private currentState: PaperTradingState;
  private context: PaperTradingContext;
  private transitions: Transition[] = [];
  private stateHistory: Array<{ state: PaperTradingState; context: PaperTradingContext; timestamp: number }> = [];

  constructor(initialContext: PaperTradingContext = { timestamp: Date.now() }) {
    this.currentState = 'IDLE';
    this.context = { ...initialContext };
    this.configureTransitions();
    this.recordStateChange('IDLE', this.context);
  }

  private configureTransitions(): void {
    // IDLE state transitions
    this.addTransition({
      from: 'IDLE',
      to: 'PENDING_ORDER',
      event: 'CREATE_ORDER',
      guard: (ctx) => this.validateOrderCreation(ctx),
      action: (ctx) => this.onOrderCreated(ctx),
    });

    // PENDING_ORDER state transitions
    this.addTransition({
      from: 'PENDING_ORDER',
      to: 'OPEN_POSITION',
      event: 'FILL_ORDER',
      guard: (ctx) => this.validateOrderFill(ctx),
      action: (ctx) => this.onOrderFilled(ctx),
    });

    this.addTransition({
      from: 'PENDING_ORDER',
      to: 'IDLE',
      event: 'CANCEL_ORDER',
      action: (ctx) => this.onOrderCancelled(ctx),
    });

    this.addTransition({
      from: 'PENDING_ORDER',
      to: 'ERROR',
      event: 'ERROR_OCCURRED',
      action: (ctx) => this.onError(ctx),
    });

    // OPEN_POSITION state transitions
    this.addTransition({
      from: 'OPEN_POSITION',
      to: 'PENDING_CLOSE',
      event: 'CLOSE_POSITION',
      guard: (ctx) => this.validateClosePosition(ctx),
      action: (ctx) => this.onCloseInitiated(ctx),
    });

    this.addTransition({
      from: 'OPEN_POSITION',
      to: 'OPEN_POSITION',
      event: 'UPDATE_PRICE',
      action: (ctx) => this.onPriceUpdated(ctx),
    });

    this.addTransition({
      from: 'OPEN_POSITION',
      to: 'ERROR',
      event: 'ERROR_OCCURRED',
      action: (ctx) => this.onError(ctx),
    });

    // PENDING_CLOSE state transitions
    this.addTransition({
      from: 'PENDING_CLOSE',
      to: 'CLOSED',
      event: 'FILL_ORDER',
      guard: (ctx) => this.validateCloseFill(ctx),
      action: (ctx) => this.onPositionClosed(ctx),
    });

    this.addTransition({
      from: 'PENDING_CLOSE',
      to: 'OPEN_POSITION',
      event: 'CANCEL_ORDER',
      action: (ctx) => this.onCloseCancelled(ctx),
    });

    // ERROR state transitions
    this.addTransition({
      from: 'ERROR',
      to: 'IDLE',
      event: 'RESET',
      action: (ctx) => this.onReset(ctx),
    });

    // CLOSED state transitions
    this.addTransition({
      from: 'CLOSED',
      to: 'IDLE',
      event: 'RESET',
      action: (ctx) => this.onReset(ctx),
    });
  }

  private addTransition(transition: Transition): void {
    this.transitions.push(transition);
  }

  private validateOrderCreation(ctx: PaperTradingContext): boolean {
    return !!
      ctx.symbol &&
      ctx.side &&
      ctx.amount && ctx.amount > 0 &&
      ctx.price && ctx.price > 0 &&
      ctx.leverage && ctx.leverage > 0;
  }

  private validateOrderFill(ctx: PaperTradingContext): boolean {
    // For canTransition check, we just need to know if the fields exist
    // The actual validation happens when the event is sent with context
    return !!ctx.positionId;
  }

  private validateClosePosition(ctx: PaperTradingContext): boolean {
    return !!ctx.positionId;
  }

  private validateCloseFill(ctx: PaperTradingContext): boolean {
    return !!ctx.positionId;
  }

  private onOrderCreated(ctx: PaperTradingContext): void {
    this.updateContext({
      ...ctx,
      timestamp: Date.now(),
    });
  }

  private onOrderFilled(ctx: PaperTradingContext): void {
    this.updateContext({
      ...ctx,
      timestamp: Date.now(),
    });
  }

  private onOrderCancelled(ctx: PaperTradingContext): void {
    this.updateContext({
      ...ctx,
      timestamp: Date.now(),
    });
  }

  private onCloseInitiated(ctx: PaperTradingContext): void {
    this.updateContext({
      ...ctx,
      timestamp: Date.now(),
    });
  }

  private onCloseCancelled(ctx: PaperTradingContext): void {
    this.updateContext({
      ...ctx,
      timestamp: Date.now(),
    });
  }

  private onPositionClosed(ctx: PaperTradingContext): void {
    this.updateContext({
      ...ctx,
      timestamp: Date.now(),
    });
  }

  private onPriceUpdated(ctx: PaperTradingContext): void {
    if (ctx.currentPrice && ctx.price) {
      const unrealizedPnl = ctx.side === 'buy'
        ? (ctx.currentPrice - ctx.price) * (ctx.amount || 0)
        : (ctx.price - ctx.currentPrice) * (ctx.amount || 0);

      this.updateContext({
        ...ctx,
        currentPrice: ctx.currentPrice,
        unrealizedPnl,
        timestamp: Date.now(),
      });
    }
  }

  private onError(ctx: PaperTradingContext): void {
    this.updateContext({
      ...ctx,
      timestamp: Date.now(),
    });
  }

  private onReset(ctx: PaperTradingContext): void {
    this.updateContext({
      ...ctx,
      symbol: undefined,
      side: undefined,
      amount: undefined,
      price: undefined,
      stopLoss: undefined,
      takeProfit: undefined,
      leverage: undefined,
      currentPrice: undefined,
      unrealizedPnl: undefined,
      realizedPnl: undefined,
      error: undefined,
      timestamp: Date.now(),
    });
  }

  private updateContext(newContext: Partial<PaperTradingContext>): void {
    this.context = { ...this.context, ...newContext };
  }

  public sendEvent(event: PaperTradingEvent, context?: Partial<PaperTradingContext>): boolean {
    if (context) {
      this.context = { ...this.context, ...context };
    }

    const validTransitions = this.transitions.filter(t => {
      const fromMatch = Array.isArray(t.from) 
        ? t.from.includes(this.currentState)
        : t.from === this.currentState;
      return fromMatch && t.event === event;
    });

    for (const transition of validTransitions) {
      if (!transition.guard || transition.guard(this.context)) {
        this.currentState = transition.to;
        if (transition.action) {
          transition.action(this.context);
        }
        this.recordStateChange(this.currentState, this.context);
        return true;
      }
    }

    return false;
  }

  public getState(): PaperTradingState {
    return this.currentState;
  }

  public getContext(): PaperTradingContext {
    return { ...this.context };
  }

  private recordStateChange(state: PaperTradingState, context: PaperTradingContext): void {
    this.stateHistory.push({
      state,
      context: { ...context },
      timestamp: Date.now(),
    });
  }

  public getStateHistory(): Array<{ state: PaperTradingState; context: PaperTradingContext; timestamp: number }> {
    return [...this.stateHistory];
  }

  public canTransition(event: PaperTradingEvent): boolean {
    return this.transitions.some(t => {
      const fromMatch = Array.isArray(t.from) 
        ? t.from.includes(this.currentState)
        : t.from === this.currentState;
      return fromMatch && t.event === event;
    });
  }
}

import { Decimal } from 'decimal.js';
import { randomUUID } from 'crypto';

export interface OrderBookLevel {
  price: Decimal;
  quantity: Decimal;
}

export interface OrderBookSnapshot {
  symbol: string;
  timestamp: number;
  bids: OrderBookLevel[];
  asks: OrderBookLevel[];
  midPrice: Decimal;
  spread: Decimal;
}

export interface PaperOrder {
  id: string;
  symbol: string;
  side: 'buy' | 'sell';
  type: 'market' | 'limit';
  quantity: Decimal;
  price?: Decimal;
  timeInForce: 'GTC' | 'IOC' | 'FOK';
  timestamp: number;
  status: 'pending' | 'filled' | 'cancelled' | 'expired';
  filledQuantity?: Decimal;
  fillPrice?: Decimal;
  fillTimestamp?: number;
}

export class OrderBookSimulator {
  private orderBooks: Map<string, {
    bids: OrderBookLevel[];
    asks: OrderBookLevel[];
    lastUpdateTime: number;
  }> = new Map();

  private pendingOrders: Map<string, PaperOrder> = new Map();
  private readonly MAX_LEVELS = 10;

  constructor() {
    this.initializeOrderBooks();
  }

  private initializeOrderBooks(): void {
    // Initialize with common trading pairs
    const symbols = ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'BNB/USDT', 'XRP/USDT'];

    for (const symbol of symbols) {
      this.orderBooks.set(symbol, {
        bids: this.generateInitialLevels(100000, true),
        asks: this.generateInitialLevels(100000, false),
        lastUpdateTime: Date.now(),
      });
    }
  }

  private generateInitialLevels(midPrice: number, isBid: boolean): OrderBookLevel[] {
    const levels: OrderBookLevel[] = [];
    const baseQuantity = new Decimal(10);

    for (let i = 0; i < this.MAX_LEVELS; i++) {
      const priceOffset = (i + 1) * 0.001 * midPrice; // 0.1% per level
      const price = isBid 
        ? new Decimal(midPrice - priceOffset)
        : new Decimal(midPrice + priceOffset);

      const quantityMultiplier = Math.max(0.1, 1 - i * 0.1);
      const quantity = baseQuantity.mul(new Decimal(quantityMultiplier));

      levels.push({
        price,
        quantity,
      });
    }

    return levels;
  }

  public updateOrderBook(symbol: string, currentPrice: number, volatility: number = 0.02): void {
    const orderBook = this.orderBooks.get(symbol);
    if (!orderBook) {
      // Initialize new symbol
      const newBook = {
        bids: this.generateInitialLevels(currentPrice, true),
        asks: this.generateInitialLevels(currentPrice, false),
        lastUpdateTime: Date.now(),
      };
      this.orderBooks.set(symbol, newBook);
      return;
    }

    // Simulate market movement
    const priceChange = currentPrice * volatility * (Math.random() - 0.5) * 0.1;
    const newMidPrice = currentPrice + priceChange;

    // Update bid levels
    orderBook.bids = orderBook.bids.map((level, index) => {
      const newPrice = new Decimal(newMidPrice - (index + 1) * 0.001 * newMidPrice);
      const quantityChange = 1 + (Math.random() - 0.5) * 0.2;
      return {
        price: newPrice,
        quantity: level.quantity.mul(new Decimal(Math.max(0.1, quantityChange))),
      };
    });

    // Update ask levels
    orderBook.asks = orderBook.asks.map((level, index) => {
      const newPrice = new Decimal(newMidPrice + (index + 1) * 0.001 * newMidPrice);
      const quantityChange = 1 + (Math.random() - 0.5) * 0.2;
      return {
        price: newPrice,
        quantity: level.quantity.mul(new Decimal(Math.max(0.1, quantityChange))),
      };
    });

    orderBook.lastUpdateTime = Date.now();
  }

  public getOrderBook(symbol: string): OrderBookSnapshot | null {
    const orderBook = this.orderBooks.get(symbol);
    if (!orderBook) {
      return null;
    }

    const bestBid = orderBook.bids[0]?.price || new Decimal(0);
    const bestAsk = orderBook.asks[0]?.price || new Decimal(0);
    const midPrice = bestBid.add(bestAsk).div(2);
    const spread = bestAsk.minus(bestBid);

    return {
      symbol,
      timestamp: orderBook.lastUpdateTime,
      bids: [...orderBook.bids],
      asks: [...orderBook.asks],
      midPrice,
      spread,
    };
  }

  public getTopLevels(symbol: string, levels: number = 10): {
    bids: OrderBookLevel[];
    asks: OrderBookLevel[];
  } | null {
    const orderBook = this.orderBooks.get(symbol);
    if (!orderBook) {
      return null;
    }

    return {
      bids: orderBook.bids.slice(0, levels),
      asks: orderBook.asks.slice(0, levels),
    };
  }

  public addPaperOrder(order: PaperOrder): string {
    order.id = order.id || randomUUID();
    order.timestamp = Date.now();
    order.status = 'pending';
    this.pendingOrders.set(order.id, order);
    return order.id;
  }

  public cancelPaperOrder(orderId: string): boolean {
    const order = this.pendingOrders.get(orderId);
    if (order && order.status === 'pending') {
      order.status = 'cancelled';
      return true;
    }
    return false;
  }

  public getPaperOrder(orderId: string): PaperOrder | undefined {
    return this.pendingOrders.get(orderId);
  }

  public matchOrders(symbol: string, slippageModel?: SlippageModel): {
    filledOrders: PaperOrder[];
    remainingOrders: PaperOrder[];
  } {
    const orderBook = this.orderBooks.get(symbol);
    if (!orderBook) {
      return { filledOrders: [], remainingOrders: [] };
    }

    const filledOrders: PaperOrder[] = [];
    const remainingOrders: PaperOrder[] = [];

    for (const [orderId, order] of this.pendingOrders) {
      if (order.symbol !== symbol || order.status !== 'pending') {
        if (order.symbol === symbol) {
          remainingOrders.push(order);
        }
        continue;
      }

      if (order.type === 'market') {
        const fillResult = this.matchMarketOrder(order, orderBook, slippageModel);
        if (fillResult.filled) {
          filledOrders.push(fillResult.order);
        } else {
          remainingOrders.push(order);
        }
      } else if (order.type === 'limit') {
        const fillResult = this.matchLimitOrder(order, orderBook);
        if (fillResult.filled) {
          filledOrders.push(fillResult.order);
        } else {
          remainingOrders.push(order);
        }
      }
    }

    return { filledOrders, remainingOrders };
  }

  private matchMarketOrder(
    order: PaperOrder,
    orderBook: { bids: OrderBookLevel[]; asks: OrderBookLevel[]; lastUpdateTime: number },
    slippageModel?: SlippageModel
  ): { filled: boolean; order: PaperOrder } {
    const levels = order.side === 'buy' ? orderBook.asks : orderBook.bids;
    let remainingQuantity = order.quantity;
    let totalCost = new Decimal(0);
    let filledQuantity = new Decimal(0);

    for (const level of levels) {
      if (remainingQuantity.lte(0)) break;

      const fillQuantity = Decimal.min(remainingQuantity, level.quantity);
      const fillPrice = slippageModel 
        ? this.applySlippage(level.price, order.side, slippageModel)
        : level.price;

      totalCost = totalCost.add(fillQuantity.mul(fillPrice));
      filledQuantity = filledQuantity.add(fillQuantity);
      remainingQuantity = remainingQuantity.sub(fillQuantity);
    }

    if (filledQuantity.gt(0)) {
      const avgPrice = totalCost.div(filledQuantity);
      order.status = 'filled';
      order.filledQuantity = filledQuantity;
      order.fillPrice = avgPrice;
      order.fillTimestamp = Date.now();
      return { filled: true, order };
    }

    return { filled: false, order };
  }

  private matchLimitOrder(
    order: PaperOrder,
    orderBook: { bids: OrderBookLevel[]; asks: OrderBookLevel[]; lastUpdateTime: number }
  ): { filled: boolean; order: PaperOrder } {
    if (!order.price) {
      return { filled: false, order };
    }

    const levels = order.side === 'buy' ? orderBook.asks : orderBook.bids;
    let canFill = false;

    for (const level of levels) {
      if (order.side === 'buy' && level.price.lte(order.price)) {
        canFill = true;
        break;
      } else if (order.side === 'sell' && level.price.gte(order.price)) {
        canFill = true;
        break;
      }
    }

    if (canFill) {
      return this.matchMarketOrder(order, orderBook);
    }

    return { filled: false, order };
  }

  private applySlippage(price: Decimal, side: 'buy' | 'sell', slippageModel: SlippageModel): Decimal {
    const slippageFactor = new Decimal(1 + slippageModel.slippagePercent / 100);
    return side === 'buy' 
      ? price.mul(slippageFactor)
      : price.div(slippageFactor);
  }
}

export interface SlippageModel {
  slippagePercent: number;
  volatilityImpact: number;
  liquidityImpact: number;
}

import { Decimal } from 'decimal.js';
import { randomUUID } from 'crypto';

export interface PaperPosition {
  id: string;
  symbol: string;
  side: 'buy' | 'sell';
  quantity: Decimal;
  entryPrice: Decimal;
  currentPrice?: Decimal;
  stopLoss?: Decimal;
  takeProfit?: Decimal;
  leverage: number;
  openedAt: number;
  closedAt?: number;
  status: 'open' | 'closed' | 'liquidated';
  realizedPnl?: Decimal;
  unrealizedPnl?: Decimal;
  candlesHeld: number;
  isRunner?: boolean;
  exitReason?: string;
}

export interface PositionUpdate {
  symbol: string;
  currentPrice: Decimal;
  timestamp: number;
}

export interface PnlCalculation {
  unrealizedPnl: Decimal;
  realizedPnl: Decimal;
  totalPnl: Decimal;
  pnlPercentage: Decimal;
  marginUsed: Decimal;
  currentMargin: Decimal;
  roi: Decimal;
}

export class PaperPositionTracker {
  private positions: Map<string, PaperPosition> = new Map();
  private positionHistory: Map<string, PaperPosition[]> = new Map();
  private readonly MAINTENANCE_MARGIN = new Decimal(0.005); // 0.5%

  constructor() {}

  public openPosition(position: Omit<PaperPosition, 'id' | 'status' | 'candlesHeld' | 'openedAt'>): PaperPosition {
    const id = randomUUID();
    const newPosition: PaperPosition = {
      ...position,
      id,
      status: 'open',
      candlesHeld: 0,
      openedAt: Date.now(),
    };

    this.positions.set(id, newPosition);

    // Add to position history
    if (!this.positionHistory.has(position.symbol)) {
      this.positionHistory.set(position.symbol, []);
    }
    this.positionHistory.get(position.symbol)!.push(newPosition);

    return newPosition;
  }

  public closePosition(positionId: string, exitPrice: Decimal, timestamp: number): PaperPosition | null {
    const position = this.positions.get(positionId);
    if (!position || position.status !== 'open') {
      return null;
    }

    const pnl = this.calculatePnl(position, exitPrice);
    const closedPosition: PaperPosition = {
      ...position,
      currentPrice: exitPrice,
      realizedPnl: pnl.totalPnl,
      unrealizedPnl: new Decimal(0),
      status: 'closed',
      closedAt: timestamp,
      exitReason: 'manual_close',
    };

    this.positions.set(positionId, closedPosition);
    return closedPosition;
  }

  public updatePositionPrice(positionId: string, currentPrice: Decimal): PaperPosition | null {
    const position = this.positions.get(positionId);
    if (!position || position.status !== 'open') {
      return null;
    }

    const updatedPosition: PaperPosition = {
      ...position,
      currentPrice,
    };

    this.positions.set(positionId, updatedPosition);
    return updatedPosition;
  }

  public updatePositionPriceBySymbol(symbol: string, currentPrice: Decimal, timestamp: number): Array<{ position: PaperPosition; pnl: PnlCalculation; liquidated: boolean }> {
    const results: Array<{ position: PaperPosition; pnl: PnlCalculation; liquidated: boolean }> = [];

    for (const [positionId, position] of this.positions) {
      if (position.symbol === symbol && position.status === 'open') {
        const updatedPosition = this.updatePositionPrice(positionId, currentPrice);
        if (updatedPosition) {
          const pnl = this.calculatePnl(updatedPosition, currentPrice);
          const liquidated = this.checkLiquidation(updatedPosition, currentPrice);

          if (liquidated) {
            this.liquidatePosition(positionId, currentPrice, timestamp);
          }

          results.push({
            position: updatedPosition,
            pnl,
            liquidated,
          });
        }
      }
    }

    return results;
  }

  public incrementCandlesHeld(positionId: string): PaperPosition | null {
    const position = this.positions.get(positionId);
    if (!position || position.status !== 'open') {
      return null;
    }

    const updatedPosition: PaperPosition = {
      ...position,
      candlesHeld: position.candlesHeld + 1,
    };

    this.positions.set(positionId, updatedPosition);
    return updatedPosition;
  }

  public liquidatePosition(positionId: string, currentPrice: Decimal, timestamp: number): PaperPosition | null {
    const position = this.positions.get(positionId);
    if (!position || position.status !== 'open') {
      return null;
    }

    const pnl = this.calculatePnl(position, currentPrice);
    const liquidatedPosition: PaperPosition = {
      ...position,
      currentPrice,
      realizedPnl: pnl.realizedPnl,
      unrealizedPnl: new Decimal(0),
      status: 'liquidated',
      closedAt: timestamp,
      exitReason: 'liquidation',
    };

    this.positions.set(positionId, liquidatedPosition);
    return liquidatedPosition;
  }

  public checkStopLoss(positionId: string, currentPrice: Decimal): boolean {
    const position = this.positions.get(positionId);
    if (!position || position.status !== 'open' || !position.stopLoss) {
      return false;
    }

    if (position.side === 'buy' && currentPrice.lte(position.stopLoss)) {
      return true;
    }
    if (position.side === 'sell' && currentPrice.gte(position.stopLoss)) {
      return true;
    }

    return false;
  }

  public checkTakeProfit(positionId: string, currentPrice: Decimal): boolean {
    const position = this.positions.get(positionId);
    if (!position || position.status !== 'open' || !position.takeProfit) {
      return false;
    }

    if (position.side === 'buy' && currentPrice.gte(position.takeProfit)) {
      return true;
    }
    if (position.side === 'sell' && currentPrice.lte(position.takeProfit)) {
      return true;
    }

    return false;
  }

  public checkLiquidation(position: PaperPosition, currentPrice: Decimal): boolean {
    const pnl = this.calculatePnl(position, currentPrice);
    const lossPercentage = pnl.marginUsed.gt(0) 
      ? pnl.totalPnl.abs().div(pnl.marginUsed)
      : new Decimal(0);

    return lossPercentage.gte(new Decimal(1).div(position.leverage).minus(this.MAINTENANCE_MARGIN));
  }

  public calculatePnl(position: PaperPosition, currentPrice?: Decimal): PnlCalculation {
    const price = currentPrice || position.currentPrice || position.entryPrice;
    const isLong = position.side === 'buy';
    const priceDiff = isLong 
      ? price.minus(position.entryPrice)
      : position.entryPrice.minus(price);

    const notionalValue = position.quantity.mul(position.entryPrice);
    const marginUsed = notionalValue.div(new Decimal(position.leverage));
    const currentNotional = position.quantity.mul(price);
    const currentMargin = currentNotional.div(new Decimal(position.leverage));

    let pnl: Decimal;
    if (position.status === 'closed' || position.status === 'liquidated') {
      pnl = position.realizedPnl || new Decimal(0);
    } else {
      pnl = isLong 
        ? currentMargin.minus(marginUsed)
        : marginUsed.minus(currentMargin);
    }

    const pnlPercentage = marginUsed.gt(0) 
      ? pnl.div(marginUsed).mul(100)
      : new Decimal(0);

    const roi = marginUsed.gt(0)
      ? pnl.div(marginUsed).mul(100)
      : new Decimal(0);

    return {
      unrealizedPnl: position.status === 'open' ? pnl : new Decimal(0),
      realizedPnl: position.status === 'open' ? new Decimal(0) : pnl,
      totalPnl: pnl,
      pnlPercentage,
      marginUsed,
      currentMargin,
      roi,
    };
  }

  public getPosition(positionId: string): PaperPosition | undefined {
    return this.positions.get(positionId);
  }

  public getOpenPositions(): PaperPosition[] {
    return Array.from(this.positions.values()).filter(p => p.status === 'open');
  }

  public getPositionsBySymbol(symbol: string): PaperPosition[] {
    return Array.from(this.positions.values()).filter(p => p.symbol === symbol);
  }

  public getPositionHistory(symbol?: string): PaperPosition[] {
    if (symbol) {
      return this.positionHistory.get(symbol) || [];
    }
    return Array.from(this.positionHistory.values()).flat();
  }

  public getTotalUnrealizedPnl(): Decimal {
    return this.getOpenPositions().reduce((sum, position) => {
      const pnl = this.calculatePnl(position, position.currentPrice || position.entryPrice);
      return sum.add(pnl.unrealizedPnl);
    }, new Decimal(0));
  }

  public getTotalRealizedPnl(): Decimal {
    return Array.from(this.positions.values())
      .filter(p => p.status === 'closed' || p.status === 'liquidated')
      .reduce((sum, position) => sum.add(position.realizedPnl || new Decimal(0)), new Decimal(0));
  }

  public getTotalMarginUsed(): Decimal {
    return this.getOpenPositions().reduce((sum, position) => {
      const pnl = this.calculatePnl(position, position.currentPrice || position.entryPrice);
      return sum.add(pnl.marginUsed);
    }, new Decimal(0));
  }

  public getPositionCount(): { total: number; open: number; closed: number; liquidated: number } {
    const positions = Array.from(this.positions.values());
    return {
      total: positions.length,
      open: positions.filter(p => p.status === 'open').length,
      closed: positions.filter(p => p.status === 'closed').length,
      liquidated: positions.filter(p => p.status === 'liquidated').length,
    };
  }
}

import { WebSocketServer, WebSocket } from 'ws';
import { PaperTradingService } from '../paper-trading/paper-trading-service';
import { logger } from '../logging/logger.js';

export interface PaperTradingWebSocketMessage {
  type: 
    | 'subscribe_paper_positions'
    | 'subscribe_paper_pnl'
    | 'subscribe_paper_prices'
    | 'paper_position_update'
    | 'paper_pnl_update'
    | 'paper_price_update'
    | 'paper_order_fill'
    | 'paper_error';
  data: any;
  timestamp: number;
}

export class PaperTradingWebSocketHandler {
  private clients: Map<string, WebSocket> = new Map();
  private paperTradingService: PaperTradingService;
  private updateInterval: NodeJS.Timeout | null = null;
  private readonly UPDATE_INTERVAL = 100; // 100ms = 10 updates per second

  constructor(paperTradingService: PaperTradingService) {
    this.paperTradingService = paperTradingService;
  }

  public handleConnection(ws: WebSocket, clientId: string): void {
    this.clients.set(clientId, ws);

    logger.info('Paper trading WebSocket client connected', { 
      clientId,
      totalClients: this.clients.size 
    });

    // Send initial data
    this.sendInitialData(clientId).catch(error => {
      logger.error('Failed to send initial data', { clientId, error });
    });

    ws.on('message', (message: string) => {
      try {
        const data = JSON.parse(message);
        this.handleMessage(clientId, data);
      } catch (error) {
        logger.error('Failed to parse WebSocket message', { clientId, error });
        this.sendError(clientId, 'Invalid message format');
      }
    });

    ws.on('close', () => {
      this.clients.delete(clientId);
      logger.info('Paper trading WebSocket client disconnected', { 
        clientId,
        totalClients: this.clients.size 
      });

      // Stop updates if no clients left
      if (this.clients.size === 0) {
        this.stopUpdates();
      }
    });

    ws.on('error', (error) => {
      logger.error('Paper trading WebSocket error', { clientId, error });
      this.clients.delete(clientId);
    });

    // Start sending updates if this is the first client
    if (this.clients.size === 1) {
      this.startUpdates();
    }
  }

  private async sendInitialData(clientId: string): Promise<void> {
    const ws = this.clients.get(clientId);
    if (!ws || ws.readyState !== WebSocket.OPEN) {
      return;
    }

    try {
      // Send initial positions
      const positions = await this.paperTradingService.getOpenPositions();
      this.sendMessage(clientId, {
        type: 'paper_position_update',
        data: { positions },
        timestamp: Date.now(),
      });

      // Send initial P&L
      const summary = await this.paperTradingService.getSummary();
      this.sendMessage(clientId, {
        type: 'paper_pnl_update',
        data: {
          totalUnrealizedPnl: summary.totalUnrealizedPnl,
          totalRealizedPnl: summary.totalRealizedPnl,
          positionCount: summary.positionCount,
        },
        timestamp: Date.now(),
      });
    } catch (error) {
      logger.error('Failed to send initial data', { clientId, error });
    }
  }

  private handleMessage(clientId: string, message: any): void {
    switch (message.type) {
      case 'subscribe_paper_positions':
        this.sendMessage(clientId, {
          type: 'paper_position_update',
          data: { subscribed: true, channel: 'positions' },
          timestamp: Date.now(),
        });
        break;

      case 'subscribe_paper_pnl':
        this.sendMessage(clientId, {
          type: 'paper_pnl_update',
          data: { subscribed: true, channel: 'pnl' },
          timestamp: Date.now(),
        });
        break;

      case 'subscribe_paper_prices':
        this.sendMessage(clientId, {
          type: 'paper_price_update',
          data: { subscribed: true, channel: 'prices' },
          timestamp: Date.now(),
        });
        break;

      default:
        this.sendError(clientId, 'Unknown message type');
    }
  }

  private sendMessage(clientId: string, message: PaperTradingWebSocketMessage): void {
    const ws = this.clients.get(clientId);
    if (ws && ws.readyState === WebSocket.OPEN) {
      try {
        ws.send(JSON.stringify(message));
      } catch (error) {
        logger.error('Failed to send WebSocket message', { clientId, error });
      }
    }
  }

  private sendError(clientId: string, error: string): void {
    this.sendMessage(clientId, {
      type: 'paper_error',
      data: { error },
      timestamp: Date.now(),
    });
  }

  private startUpdates(): void {
    if (this.updateInterval) {
      return;
    }

    logger.info('Starting paper trading WebSocket updates', {
      interval: this.UPDATE_INTERVAL,
    });

    this.updateInterval = setInterval(() => {
      this.broadcastPositionUpdates().catch(error => {
        logger.error('Failed to broadcast position updates', { error });
      });
      this.broadcastPnlUpdates().catch(error => {
        logger.error('Failed to broadcast P&L updates', { error });
      });
    }, this.UPDATE_INTERVAL);
  }

  public stopUpdates(): void {
    if (this.updateInterval) {
      clearInterval(this.updateInterval);
      this.updateInterval = null;
      logger.info('Stopped paper trading WebSocket updates');
    }
  }

  private async broadcastPositionUpdates(): Promise<void> {
    try {
      const positions = await this.paperTradingService.getOpenPositions();

      const message: PaperTradingWebSocketMessage = {
        type: 'paper_position_update',
        data: { positions },
        timestamp: Date.now(),
      };

      this.broadcast(message);
    } catch (error) {
      logger.error('Failed to broadcast position updates', { error });
    }
  }

  private async broadcastPnlUpdates(): Promise<void> {
    try {
      const summary = await this.paperTradingService.getSummary();

      const message: PaperTradingWebSocketMessage = {
        type: 'paper_pnl_update',
        data: {
          totalUnrealizedPnl: summary.totalUnrealizedPnl,
          totalRealizedPnl: summary.totalRealizedPnl,
          positionCount: summary.positionCount,
        },
        timestamp: Date.now(),
      };

      this.broadcast(message);
    } catch (error) {
      logger.error('Failed to broadcast P&L updates', { error });
    }
  }

  private broadcast(message: PaperTradingWebSocketMessage): void {
    const deadClients: string[] = [];

    for (const [clientId, ws] of this.clients) {
      if (ws.readyState === WebSocket.OPEN) {
        try {
          ws.send(JSON.stringify(message));
        } catch (error) {
          logger.error('Failed to broadcast to client', { clientId, error });
          deadClients.push(clientId);
        }
      } else {
        deadClients.push(clientId);
      }
    }

    // Clean up dead clients
    for (const clientId of deadClients) {
      this.clients.delete(clientId);
    }
  }

  public getClientCount(): number {
    return this.clients.size;
  }
}

import Redis from 'ioredis';
import { logger } from './logging/logger.js';

export class StatelessServiceManager {
  private redis?: Redis;
  private serviceKey: string;

  constructor(redis: Redis | undefined, serviceName: string) {
    this.redis = redis;
    this.serviceKey = `service:${serviceName}`;
  }

  async getState(key: string): Promise<any> {
    if (!this.redis) return null;
    try {
      const data = await this.redis.get(`${this.serviceKey}:${key}`);
      return data ? JSON.parse(data) : null;
    } catch (error) {
      logger.error('Failed to get service state', { key, error: error.message });
      return null;
    }
  }

  async setState(key: string, value: any, ttl?: number): Promise<void> {
    if (!this.redis) return;
    try {
      const data = JSON.stringify(value);
      if (ttl) {
        await this.redis.setex(`${this.serviceKey}:${key}`, ttl, data);
      } else {
        await this.redis.set(`${this.serviceKey}:${key}`, data);
      }
    } catch (error) {
      logger.warn('Failed to set service state (Redis unavailable)', { key, error: error.message });
      // Don't throw - allow operation to continue without Redis
    }
  }

  async deleteState(key: string): Promise<void> {
    if (!this.redis) return;
    try {
      await this.redis.del(`${this.serviceKey}:${key}`);
    } catch (error) {
      logger.error('Failed to delete service state', { key, error: error.message });
    }
  }

  async getAllState(): Promise<Record<string, any>> {
    if (!this.redis) return {};
    try {
      const keys = await this.redis.keys(`${this.serviceKey}:*`);
      if (keys.length === 0) return {};

      const values = await this.redis.mget(keys);
      const result: Record<string, any> = {};

      keys.forEach((key, index) => {
        const stateKey = key.replace(`${this.serviceKey}:`, '');
        if (values[index]) {
          try {
            result[stateKey] = JSON.parse(values[index]);
          } catch (error) {
            logger.error('Failed to parse state value', { key: stateKey, error: error.message });
          }
        }
      });

      return result;
    } catch (error) {
      logger.warn('Failed to get all service state (Redis unavailable)', { error: error.message });
      return {};
    }
  }

  // Atomic state updates with Lua scripts
  async updateStateAtomically(key: string, updateFn: (currentValue: any) => any): Promise<any> {
    if (!this.redis) {
      return updateFn(null);
    }
    const script = `
      local key = KEYS[1]
      local current = redis.call('GET', key)
      local newValue = ARGV[1]
      redis.call('SET', key, newValue)
      return newValue
    `;

    try {
      let currentValue = await this.getState(key);
      const newValue = updateFn(currentValue);
      const serialized = JSON.stringify(newValue);

      await this.redis.eval(script, 1, `${this.serviceKey}:${key}`, serialized);
      return newValue;
    } catch (error) {
      logger.warn('Failed to update state atomically (Redis unavailable)', { key, error: error.message });
      // Return the updated value even if Redis failed - state management should continue
      return updateFn(await this.getState(key));
    }
  }

  // Pub/Sub for state change notifications
  async publishStateChange(key: string, oldValue: any, newValue: any): Promise<void> {
    if (!this.redis) return;
    try {
      await this.redis.publish(`${this.serviceKey}:changes`, JSON.stringify({
        key,
        oldValue,
        newValue,
        timestamp: Date.now()
      }));
    } catch (error) {
      logger.error('Failed to publish state change', { key, error: error.message });
    }
  }

  async subscribeToStateChanges(callback: (change: any) => void): Promise<void> {
    if (!this.redis) return;
    const subscriber = this.redis.duplicate();

    try {
      await subscriber.subscribe(`${this.serviceKey}:changes`);
      subscriber.on('message', (channel, message) => {
        if (channel === `${this.serviceKey}:changes`) {
          try {
            const change = JSON.parse(message);
            callback(change);
          } catch (error) {
            logger.error('Failed to parse state change message', { error: error.message });
          }
        }
      });
    } catch (error) {
      logger.error('Failed to subscribe to state changes', { error: error.message });
    }
  }

  // Session management for horizontal scaling
  async createSession(sessionId: string, data: any, ttl: number = 3600): Promise<void> {
    await this.setState(`session:${sessionId}`, data, ttl);
  }

  async getSession(sessionId: string): Promise<any> {
    return await this.getState(`session:${sessionId}`);
  }

  async updateSession(sessionId: string, updateFn: (session: any) => any): Promise<any> {
    return await this.updateStateAtomically(`session:${sessionId}`, updateFn);
  }

  async destroySession(sessionId: string): Promise<void> {
    await this.deleteState(`session:${sessionId}`);
  }

  async cleanupExpiredSessions(): Promise<void> {
    try {
      // This would require Redis key expiration events or periodic cleanup
      // For now, rely on TTL expiration
      logger.info('Session cleanup completed (TTL-based)');
    } catch (error) {
      logger.error('Failed to cleanup expired sessions', { error: error.message });
    }
  }
}

// Global service manager factory
const serviceManagers = new Map<string, StatelessServiceManager>();

export function getServiceManager(redis: Redis, serviceName: string): StatelessServiceManager {
  const host = redis?.options?.host || 'memory';
  const port = redis?.options?.port || 'none';
  const key = `${host}:${port}:${serviceName}`;
  if (!serviceManagers.has(key)) {
    serviceManagers.set(key, new StatelessServiceManager(redis, serviceName));
  }
  return serviceManagers.get(key)!;
}

type RouteMetrics = {
  requests: number;
  errors: number;
  totalLatencyMs: number;
  maxLatencyMs: number;
};

const routes = new Map<string, RouteMetrics>();
let totalRequests = 0;
let totalErrors = 0;
let totalLatencyMs = 0;
let maxLatencyMs = 0;

function getOrCreateRouteMetrics(routeKey: string): RouteMetrics {
  const existing = routes.get(routeKey);
  if (existing) return existing;
  const created: RouteMetrics = {
    requests: 0,
    errors: 0,
    totalLatencyMs: 0,
    maxLatencyMs: 0
  };
  routes.set(routeKey, created);
  return created;
}

export function recordApiRequest(routeKey: string, method: string, statusCode: number, latencyMs: number) {
  totalRequests += 1;
  totalLatencyMs += latencyMs;
  maxLatencyMs = Math.max(maxLatencyMs, latencyMs);
  if (statusCode >= 400) totalErrors += 1;

  const route = getOrCreateRouteMetrics(routeKey);
  route.requests += 1;
  route.totalLatencyMs += latencyMs;
  route.maxLatencyMs = Math.max(route.maxLatencyMs, latencyMs);
  if (statusCode >= 400) route.errors += 1;
}

export function getApiMetricsSnapshot() {
  const routeSummary = [...routes.entries()]
    .map(([route, metrics]) => {
      const avgLatencyMs = metrics.requests > 0 ? metrics.totalLatencyMs / metrics.requests : 0;
      const errorRate = metrics.requests > 0 ? metrics.errors / metrics.requests : 0;
      return {
        route,
        requests: metrics.requests,
        errors: metrics.errors,
        errorRate,
        avgLatencyMs,
        maxLatencyMs: metrics.maxLatencyMs
      };
    })
    .sort((a, b) => b.avgLatencyMs - a.avgLatencyMs)
    .slice(0, 5);

  return {
    requests: totalRequests,
    errors: totalErrors,
    errorRate: totalRequests > 0 ? totalErrors / totalRequests : 0,
    avgLatencyMs: totalRequests > 0 ? totalLatencyMs / totalRequests : 0,
    maxLatencyMs,
    slowestRoutes: routeSummary
  };
}

export function resetApiMetrics() {
  routes.clear();
  totalRequests = 0;
  totalErrors = 0;
  totalLatencyMs = 0;
  maxLatencyMs = 0;
}

export function toPrometheusMetrics(marketMetrics?: {
  marketDataFetchCount?: number;
  marketDataFetchFailures?: number;
  newsFetchCount?: number;
  newsFetchFailures?: number;
}) {
  const snapshot = getApiMetricsSnapshot();
  const lines = [
    '# TYPE api_requests_total counter',
    `api_requests_total ${snapshot.requests}`,
    '# TYPE api_errors_total counter',
    `api_errors_total ${snapshot.errors}`,
    '# TYPE api_error_rate gauge',
    `api_error_rate ${snapshot.errorRate}`,
    '# TYPE api_latency_avg_ms gauge',
    `api_latency_avg_ms ${snapshot.avgLatencyMs}`,
    '# TYPE api_latency_max_ms gauge',
    `api_latency_max_ms ${snapshot.maxLatencyMs}`
  ];

  if (marketMetrics) {
    lines.push(
      '# TYPE market_data_fetch_total counter',
      `market_data_fetch_total ${marketMetrics.marketDataFetchCount || 0}`,
      '# TYPE market_data_fetch_failures_total counter',
      `market_data_fetch_failures_total ${marketMetrics.marketDataFetchFailures || 0}`,
      '# TYPE news_fetch_total counter',
      `news_fetch_total ${marketMetrics.newsFetchCount || 0}`,
      '# TYPE news_fetch_failures_total counter',
      `news_fetch_failures_total ${marketMetrics.newsFetchFailures || 0}`
    );
  }

  return `${lines.join('\n')}\n`;
}

import { Router } from 'express';
import { PaperTradingService, PaperTradeRequest, PaperTradeResponse, PositionResponse } from './paper-trading-service';
import { z } from 'zod';
import { getRequestId, logger } from '../logging/logger.js';
import { recordApiRequest } from '../observability/requestMetrics.js';

const paperTradingRouter = Router();
const paperTradingService = new PaperTradingService();

// Validation schemas
const paperTradeSchema = z.object({
  symbol: z.string().min(1, 'Symbol is required'),
  side: z.enum(['buy', 'sell'], { errorMap: () => ({ message: 'Side must be "buy" or "sell"' }) }),
  type: z.enum(['market', 'limit'], { errorMap: () => ({ message: 'Type must be "market" or "limit"' }) }),
  quantity: z.number().positive('Quantity must be positive'),
  price: z.number().positive('Price must be positive').optional(),
  stopLoss: z.number().positive('Stop loss must be positive').optional(),
  takeProfit: z.number().positive('Take profit must be positive').optional(),
  leverage: z.number().min(1, 'Leverage must be at least 1').max(100, 'Leverage must not exceed 100').optional().default(1),
  timeInForce: z.enum(['GTC', 'IOC', 'FOK'], { errorMap: () => ({ message: 'Time in force must be GTC, IOC, or FOK' }) }),
  idempotencyKey: z.string().optional(),
});

const cancelTradeSchema = z.object({
  idempotencyKey: z.string().optional(),
});

// Middleware
paperTradingRouter.use((req, res, next) => {
  const start = process.hrtime.bigint();
  req.requestId = getRequestId(req.headers['x-request-id'] as string | string[] | undefined);
  res.setHeader('x-request-id', req.requestId);

  res.on('finish', () => {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    const routeKey = `${req.method} ${req.route?.path || req.path || req.originalUrl || req.url}`;
    recordApiRequest(routeKey, req.method, res.statusCode, durationMs);

    if (res.statusCode >= 500 || durationMs >= 1000) {
      logger.warn('Paper trading API request completed with warning', {
        requestId: req.requestId,
        route: routeKey,
        statusCode: res.statusCode,
        latencyMs: Number(durationMs.toFixed(2)),
      });
    }
  });

  next();
});

/**
 * @swagger
 * /api/paper/order:
 *   post:
 *     summary: Create a paper trading order
 *     description: Create a simulated trading order in the paper trading environment
 *     tags: [Paper Trading]
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - symbol
 *               - side
 *               - type
 *               - quantity
 *               - timeInForce
 *             properties:
 *               symbol:
 *                 type: string
 *                 description: Trading pair symbol (e.g., BTC/USDT)
 *               side:
 *                 type: string
 *                 enum: [buy, sell]
 *                 description: Order side
 *               type:
 *                 type: string
 *                 enum: [market, limit]
 *                 description: Order type
 *               quantity:
 *                 type: number
 *                 description: Order quantity
 *                 minimum: 0.00000001
 *               price:
 *                 type: number
 *                 description: Order price (required for limit orders)
 *                 minimum: 0.00000001
 *               stopLoss:
 *                 type: number
 *                 description: Stop loss price
 *                 minimum: 0.00000001
 *               takeProfit:
 *                 type: number
 *                 description: Take profit price
 *                 minimum: 0.00000001
 *               leverage:
 *                 type: number
 *                 description: Leverage multiplier
 *                 minimum: 1
 *                 maximum: 100
 *                 default: 1
 *               timeInForce:
 *                 type: string
 *                 enum: [GTC, IOC, FOK]
 *                 description: Time in force
 *               idempotencyKey:
 *                 type: string
 *                 description: Unique key to prevent duplicate orders
 *     responses:
 *       200:
 *         description: Order created successfully
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 id:
 *                   type: string
 *                   description: Order ID
 *                 status:
 *                   type: string
 *                   enum: [pending, filled, cancelled, expired]
 *                   description: Order status
 *                 symbol:
 *                   type: string
 *                   description: Trading pair symbol
 *                 side:
 *                   type: string
 *                   enum: [buy, sell]
 *                   description: Order side
 *                 quantity:
 *                   type: string
 *                   description: Order quantity
 *                 price:
 *                   type: string
 *                   description: Order price (if limit order)
 *                 filledQuantity:
 *                   type: string
 *                   description: Filled quantity (if filled)
 *                 fillPrice:
 *                   type: string
 *                   description: Fill price (if filled)
 *                 timestamp:
 *                   type: number
 *                   description: Order creation timestamp
 *       400:
 *         description: Invalid request parameters
 *       500:
 *         description: Internal server error
 */
paperTradingRouter.post('/order', async (req, res) => {
  const requestId = req.requestId;
  const startTime = Date.now();

  try {
    const parsed = paperTradeSchema.safeParse(req.body);

    if (!parsed.success) {
      logger.warn('Paper trade validation failed', {
        requestId,
        issues: parsed.error.issues,
      });

      return res.status(400).json({
        error: 'Invalid request parameters',
        details: parsed.error.issues,
      });
    }

    const tradeRequest = parsed.data as PaperTradeRequest;

    // Validate limit order has price
    if (tradeRequest.type === 'limit' && !tradeRequest.price) {
      return res.status(400).json({
        error: 'Limit orders require a price',
      });
    }

    const result = await paperTradingService.createPaperTrade(tradeRequest);

    recordApiRequest('/api/paper/order', 'POST', 200, Date.now() - startTime);

    logger.info('Paper trade created', {
      requestId,
      orderId: result.id,
      symbol: result.symbol,
      side: result.side,
      quantity: result.quantity,
    });

    res.json(result);
  } catch (error: any) {
    recordApiRequest('/api/paper/order', 'POST', 500, Date.now() - startTime);

    logger.error('Failed to create paper trade', {
      requestId,
      error: error.message,
      stack: error.stack,
    });

    res.status(500).json({
      error: 'Failed to create paper trade',
      message: error.message,
    });
  }
});

/**
 * @swagger
 * /api/paper/order/{id}/cancel:
 *   put:
 *     summary: Cancel a paper trading order
 *     description: Cancel a pending paper trading order
 *     tags: [Paper Trading]
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Order ID
 *     requestBody:
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             properties:
 *               idempotencyKey:
 *                 type: string
 *                 description: Unique key to prevent duplicate cancellations
 *     responses:
 *       200:
 *         description: Order cancelled successfully
 *       400:
 *         description: Invalid request or order cannot be cancelled
 *       404:
 *         description: Order not found
 *       500:
 *         description: Internal server error
 */
paperTradingRouter.put('/order/:id/cancel', async (req, res) => {
  const requestId = req.requestId;
  const startTime = Date.now();
  const orderId = req.params.id;

  try {
    const parsed = cancelTradeSchema.safeParse(req.body);

    if (!parsed.success) {
      return res.status(400).json({
        error: 'Invalid request parameters',
      });
    }

    const idempotencyKey = parsed.data.idempotencyKey;
    const result = await paperTradingService.cancelPaperTrade(orderId, idempotencyKey);

    recordApiRequest('/api/paper/order/{id}/cancel', 'PUT', 200, Date.now() - startTime);

    logger.info('Paper trade cancelled', {
      requestId,
      orderId,
    });

    res.json(result);
  } catch (error: any) {
    const statusCode = error.message.includes('not found') ? 404 : 500;

    recordApiRequest('/api/paper/order/{id}/cancel', 'PUT', statusCode, Date.now() - startTime);

    logger.error('Failed to cancel paper trade', {
      requestId,
      orderId,
      error: error.message,
    });

    res.status(statusCode).json({
      error: 'Failed to cancel paper trade',
      message: error.message,
    });
  }
});

